INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C1','math',6,1,'u2',2,'각기둥의 뜻 — 직육면체를 되짚고, 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 각기둥이라 하며, 그 두 면이 밑면(위치가 아니라 관계로 정함), 두 밑면과 만나는 면이 옆면(모두 직사각형, 밑면과 수직)임을 알기',ARRAY['6수03-02']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C2','math',6,1,'u2',3,'각기둥의 이름과 구성 요소 — 밑면의 모양에 따라 삼각기둥·사각기둥…으로 부르고, 모서리(면과 면이 만나는 선분)·꼭짓점(모서리와 모서리가 만나는 점)·높이(두 밑면 사이의 거리)를 찾고 세기',ARRAY['6수03-02']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C3','math',6,1,'u2',4,'각기둥의 전개도 알기 — 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도이고, 실선은 잘린 모서리·점선은 접히는 모서리이며, 옆면의 수 = 한 밑면의 변의 수, 맞닿는 선분의 길이는 같음을 알기',ARRAY['6수03-03']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C4','math',6,1,'u2',5,'각기둥의 전개도 그리기 — 밑면 2개와 옆면(변의 수만큼)을 그리고, 옆면의 가로는 밑면의 변의 길이·세로는 높이와 같게 맞추며, 자르는 모서리에 따라 모양이 다른 전개도가 여럿 나옴을 알기',ARRAY['6수03-03']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C5','math',6,1,'u2',6,'각뿔의 뜻 — 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형을 각뿔이라 하고, 다각형인 면이 밑면(1개), 밑면과 만나는 면이 옆면(모두 삼각형)이며 각기둥·원뿔과 구별하기',ARRAY['6수03-02']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C6','math',6,1,'u2',7,'각뿔의 이름과 구성 요소 — 밑면의 모양에 따라 삼각뿔·사각뿔…으로 부르고, 옆면이 모두 만나는 점(각뿔의 꼭짓점)을 빠뜨리지 않고 세며, 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이임을 알기',ARRAY['6수03-02']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('M6-1-u2-C7','math',6,1,'u2',8,'규칙 찾기 — 한 밑면의 변의 수로 각기둥(면 +2·꼭짓점 ×2·모서리 ×3)과 각뿔(면 +1·꼭짓점 +1·모서리 ×2)의 수를 구하고, 거꾸로 수에서 입체도형의 이름을 찾으며 규칙이 세는 방법에서 나옴을 설명하기',ARRAY['6수03-02']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X01','math',6,'u2',ARRAY['M6-1-u2-C1','M6-1-u2-C3','M6-1-u2-C5']::text[],'밑면을 「아래에 놓인 면」으로만 여겨, 눕혀 놓으면 밑면을 옆면이라 부른다','밑면은 위치가 아니라 평행·합동으로 찾아요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X02','math',6,'u2',ARRAY['M6-1-u2-C1']::text[],'평행한 두 면만 보고 합동인지·옆면이 직사각형인지·굽은 면이 없는지를 확인하지 않는다','평행·합동·모두 다각형 — 세 기준') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X03','math',6,'u2',ARRAY['M6-1-u2-C1','M6-1-u2-C5']::text[],'옆면의 모양을 바꾸어 기억한다(각기둥 옆면을 삼각형·사다리꼴로, 각뿔 옆면을 직사각형으로)','기둥 옆면은 직사각형, 뿔 옆면은 삼각형') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X04','math',6,'u2',ARRAY['M6-1-u2-C2','M6-1-u2-C6','M6-1-u2-C7']::text[],'이름을 밑면이 아니라 꼭짓점·모서리·면의 수로 붙인다(꼭짓점이 10개인 각기둥을 십각기둥으로)','이름은 밑면의 변의 수가 정해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X05','math',6,'u2',ARRAY['M6-1-u2-C2','M6-1-u2-C6']::text[],'면·모서리·꼭짓점의 뜻을 서로 바꾸어 안다','면이 만나면 모서리, 모서리가 만나면 꼭짓점') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X06','math',6,'u2',ARRAY['M6-1-u2-C2','M6-1-u2-C6']::text[],'높이를 잘못 잡는다(밑면의 변을 높이로, 각뿔의 옆 모서리를 높이로)','기둥은 두 밑면 사이, 뿔은 꼭짓점에서 수직으로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X07','math',6,'u2',ARRAY['M6-1-u2-C3','M6-1-u2-C4']::text[],'전개도의 실선·점선 뜻을 거꾸로 알거나, 면이 떨어져 있어도 전개도라 여긴다','실선은 자른 곳, 점선은 접는 곳') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X08','math',6,'u2',ARRAY['M6-1-u2-C3','M6-1-u2-C4']::text[],'전개도의 밑면·옆면 수를 잘못 센다(옆면 수를 변의 수와 다르게, 밑면을 1개로)','밑면 2개, 옆면은 변의 수만큼') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X09','math',6,'u2',ARRAY['M6-1-u2-C3','M6-1-u2-C4']::text[],'옆면의 가로·세로를 바꾸어 잡거나 맞닿는 선분의 길이를 맞추지 않는다','가로는 밑면의 변, 세로는 높이') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X10','math',6,'u2',ARRAY['M6-1-u2-C5','M6-1-u2-C6','M6-1-u2-C7']::text[],'각뿔의 꼭짓점을 빠뜨리고 세거나 각뿔의 밑면을 2개로 센다','위의 한 점을 꼭 더해요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X11','math',6,'u2',ARRAY['M6-1-u2-C1','M6-1-u2-C5']::text[],'각기둥과 각뿔(또는 원기둥·원뿔)을 섞어 부르거나 성질을 옮겨 쓴다','밑면이 몇 개? 옆면은 무슨 모양?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X12','math',6,'u2',ARRAY['M6-1-u2-C2','M6-1-u2-C6','M6-1-u2-C7']::text[],'규칙을 섞는다 — 각기둥의 규칙(+2·×2·×3)을 각뿔에 쓰거나 면·꼭짓점·모서리 자리를 바꾼다','규칙은 세는 방법에서 나와요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X13','math',6,'u2',ARRAY['M6-1-u2-C3','M6-1-u2-C4']::text[],'같은 각기둥의 전개도는 하나뿐이라 여기거나, 접으면 면이 겹치는 그림도 전개도라 여긴다','자르는 모서리가 달라지면 모양이 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('M6-1-u2-X14','math',6,'u2',ARRAY['M6-1-u2-C1','M6-1-u2-C2','M6-1-u2-C3','M6-1-u2-C4','M6-1-u2-C5','M6-1-u2-C6','M6-1-u2-C7']::text[],'묻는 말을 거꾸로 읽거나 놓친다 — 잘못된↔알맞은, 합↔차, 밑면만↔모두','물음의 「잘못·모두·합·차」에 동그라미') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#1','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',1,'sa','auto','5학년에서 배운 직육면체의 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C1","difficulty":1,"kind":"sa","stem":"5학년에서 배운 직육면체의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","앞뒤·위아래·양옆 — 직사각형이 2개씩 3쌍이에요.","그래서 면은 6개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"5학년에서 배운 직육면체의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","면과 면이 만나는 선분이 4개씩 3방향 — 4 × 3 = 12개예요.","그래서 모서리는 12개예요."]},{"stem":"5학년에서 배운 직육면체의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["직육면체는 직사각형 6개로 둘러싸인 입체도형이에요.","위에 4개, 아래에 4개 — 4 + 4 = 8개예요.","그래서 꼭짓점은 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#2','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',1,'mc','auto','두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?',ARRAY['M6-1-u2-X11']::text[],true,'{"seq":2,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"밑면","mis":"M6-1-u2-X11"},{"t":"옆면","mis":"M6-1-u2-X11"},{"t":"각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「각기둥」이에요."],"variant_rule":{"alt":[{"stem":"각기둥에서 서로 평행하고 합동인 두 면을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「밑면」이에요."]},{"stem":"두 밑면과 만나는 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「옆면」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#3','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',1,'mc','auto','각기둥의 옆면은 모두 어떤 도형인가요?',ARRAY['M6-1-u2-X03','M6-1-u2-X01']::text[],true,'{"seq":3,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"각기둥의 옆면은 모두 어떤 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「직사각형」이에요."],"variant_rule":{"alt":[{"stem":"각기둥의 옆면은 두 밑면과 어떻게 만나나요?","options":[{"t":"수직으로 만나요","correct":true},{"t":"비스듬히 기울어져 만나요","mis":"M6-1-u2-X03"},{"t":"한 점에서 모두 만나요","mis":"M6-1-u2-X11"},{"t":"만나지 않아요","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「수직으로 만나요」예요."]},{"stem":"각기둥의 두 밑면은 서로 어떤 관계인가요?","options":[{"t":"서로 평행하고 합동이에요","correct":true},{"t":"서로 수직이에요","mis":"M6-1-u2-X01"},{"t":"평행하지만 크기가 달라요","mis":"M6-1-u2-X02"},{"t":"한 꼭짓점에서 만나요","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「서로 평행하고 합동이에요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#4','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',1,'sa','auto','밑면이 육각형인 각기둥의 옆면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C1","difficulty":1,"kind":"sa","stem":"밑면이 육각형인 각기둥의 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면의 변 하나마다 옆면이 하나 — 6개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 오각형인 각기둥의 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면의 변 하나마다 옆면이 하나 — 5개예요."]},{"stem":"각기둥에서 밑면은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","서로 평행하고 합동인 두 면 — 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#5','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'mc','auto','기둥 모양과 뿔 모양을 가르는 기준으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X14']::text[],true,'{"seq":5,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"기둥 모양과 뿔 모양을 가르는 기준으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 다각형이 둘인지, 하나이고 나머지가 삼각형인지","correct":true},{"t":"색깔이 서로 다른지","mis":"M6-1-u2-X14"},{"t":"크기가 큰지 작은지","mis":"M6-1-u2-X14"},{"t":"면의 수가 짝수인지","mis":"M6-1-u2-X14"}],"explanation":["입체도형은 둘러싼 면을 보고 나눠요.","위아래에 똑같은 다각형이 둘이면 기둥 모양, 다각형이 하나이고 나머지가 삼각형이면 뿔 모양이에요.","색이나 크기는 모양을 가르는 기준이 아니에요."],"variant_rule":{"alt":[{"stem":"조각 공원의 뾰족한 작품은 아래에 다각형이 하나 있고 나머지 면이 모두 한 점으로 모여요. 어떤 모양이라고 할 수 있나요?","options":[{"t":"뿔 모양","correct":true},{"t":"기둥 모양","mis":"M6-1-u2-X11"},{"t":"직육면체 모양","mis":"M6-1-u2-X11"},{"t":"공 모양","mis":"M6-1-u2-X11"}],"explanation":["입체도형은 둘러싼 면을 보고 나눠요.","위아래에 똑같은 다각형이 둘이면 기둥 모양, 다각형이 하나이고 나머지가 삼각형이면 뿔 모양이에요.","색이나 크기는 모양을 가르는 기준이 아니에요."]},{"stem":"위와 아래에 똑같은 다각형이 마주 보고 있는 작품은 어떤 모양이라고 할 수 있나요?","options":[{"t":"기둥 모양","correct":true},{"t":"뿔 모양","mis":"M6-1-u2-X11"},{"t":"공 모양","mis":"M6-1-u2-X11"},{"t":"평면도형","mis":"M6-1-u2-X14"}],"explanation":["입체도형은 둘러싼 면을 보고 나눠요.","위아래에 똑같은 다각형이 둘이면 기둥 모양, 다각형이 하나이고 나머지가 삼각형이면 뿔 모양이에요.","색이나 크기는 모양을 가르는 기준이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#6','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'mc','auto','다음 가운데 각기둥 모양인 것은 어느 것인가요?',ARRAY['M6-1-u2-X02','M6-1-u2-X11']::text[],true,'{"seq":6,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"다음 가운데 각기둥 모양인 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통","correct":true},{"t":"서로 평행한 두 사각형의 크기가 서로 다른 저금통","mis":"M6-1-u2-X02"},{"t":"한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통","mis":"M6-1-u2-X11"},{"t":"위아래 면이 서로 평행하고 합동인 원인 저금통","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","보기를 하나씩 이 뜻에 대어 봐요 — 크기가 다르거나 굽은 면이 있으면 안 돼요.","「서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통」이 각기둥이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 각기둥 모양인 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자","correct":true},{"t":"서로 평행한 두 사각형의 크기가 서로 다른 저금통","mis":"M6-1-u2-X02"},{"t":"굽은 면 하나로만 둘러싸인 공 모양 저금통","mis":"M6-1-u2-X02"},{"t":"한 원과 뾰족한 점이 있는 고깔","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","보기를 하나씩 이 뜻에 대어 봐요 — 크기가 다르거나 굽은 면이 있으면 안 돼요.","「서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자」가 각기둥이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 각기둥 모양인 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필","correct":true},{"t":"한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통","mis":"M6-1-u2-X11"},{"t":"위아래 면이 서로 평행하고 합동인 원인 저금통","mis":"M6-1-u2-X02"},{"t":"서로 평행한 두 사각형의 크기가 서로 다른 저금통","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","보기를 하나씩 이 뜻에 대어 봐요 — 크기가 다르거나 굽은 면이 있으면 안 돼요.","「서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필」이 각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#7','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'mc','auto','오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X05']::text[],true,'{"seq":7,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 오각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 오각형은 여전히 밑면이에요."],"variant_rule":{"alt":[{"stem":"육각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 육각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 육각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 육각형은 여전히 밑면이에요."]},{"stem":"삼각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 삼각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 삼각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 삼각형은 여전히 밑면이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#8','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'ox','auto','각기둥의 밑면은 언제나 바닥에 닿은 면이에요.',ARRAY['M6-1-u2-X01']::text[],true,'{"seq":8,"concept":"M6-1-u2-C1","difficulty":2,"kind":"ox","stem":"각기둥의 밑면은 언제나 바닥에 닿은 면이에요.","answer":"X","reason_options":[{"t":"밑면은 위치가 아니라 서로 평행하고 합동인 두 면이라는 관계로 정해지기 때문에","correct":true},{"t":"각기둥은 바닥에 닿은 면을 밑면이라고 정했기 때문에","mis":"M6-1-u2-X01"}],"mis":"M6-1-u2-X01","explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."],"variant_rule":{"alt":[{"stem":"각기둥의 옆면은 모두 직사각형이에요.","answer":"O","reason_options":[{"t":"옆면은 두 밑면과 수직으로 만나는 직사각형이기 때문에","correct":true},{"t":"옆면은 밑면과 모양이 같기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."]},{"stem":"각기둥의 밑면은 2개예요.","answer":"O","reason_options":[{"t":"서로 평행하고 합동인 두 면이 밑면이기 때문에","correct":true},{"t":"위에 있는 면 하나만 밑면이기 때문에","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#9','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',2,'sa','auto','밑면이 사각형인 각기둥은 밑면과 옆면을 합해 면이 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C1","difficulty":2,"kind":"sa","stem":"밑면이 사각형인 각기둥은 밑면과 옆면을 합해 면이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 육각형인 각기둥은 밑면과 옆면을 합해 면이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요."]},{"stem":"밑면이 오각형인 각기둥은 밑면과 옆면을 합해 면이 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 두 면이에요.","옆면은 밑면의 변 하나마다 하나씩 세워져요.","밑면 2개와 옆면 5개 — 5 + 2 = 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_basic#10','math',6,1,'u2','L02','g6_1_math_u2_L02_basic','lesson_basic','M6-1-u2-C1',3,'mc','auto','「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":10,"concept":"M6-1-u2-C1","difficulty":3,"kind":"mc","stem":"「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평행한 두 면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행한 두 오각형의 크기가 다른 입체도형」을 이 조건에 하나씩 대어 봐요.","평행한 두 면이 서로 합동이 아니기 때문에 각기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「서로 평행하고 합동인 두 원과 굽은 옆면으로 둘러싸인 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X11"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행하고 합동인 두 원과 굽은 옆면으로 둘러싸인 입체도형」을 이 조건에 하나씩 대어 봐요.","밑면이 다각형이 아니고 굽은 면이 있기 때문에 각기둥이 아니에요."]},{"stem":"「한 면이 육각형이고 나머지 면이 모두 삼각형인 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 면이 없기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X11"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「한 면이 육각형이고 나머지 면이 모두 삼각형인 입체도형」을 이 조건에 하나씩 대어 봐요.","서로 평행하고 합동인 두 면이 없기 때문에 각기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#1','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',2,'sa','auto','한 모서리가 4 cm인 정육면체가 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C1","difficulty":2,"kind":"sa","stem":"한 모서리가 4 cm인 정육면체가 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["정육면체의 모서리는 모두 12개이고 길이가 모두 같아요.","한 모서리가 4 cm예요.","4 × 12 = 48 — 모두 48 cm예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"한 모서리가 5 cm인 정육면체가 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["정육면체의 모서리는 모두 12개이고 길이가 모두 같아요.","한 모서리가 5 cm예요.","5 × 12 = 60 — 모두 60 cm예요."]},{"stem":"한 모서리가 7 cm인 정육면체가 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["정육면체의 모서리는 모두 12개이고 길이가 모두 같아요.","한 모서리가 7 cm예요.","7 × 12 = 84 — 모두 84 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#2','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',2,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C1","difficulty":2,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"각기둥의 옆면","r":"모두 직사각형"},{"l":"각기둥의 두 밑면","r":"평행하고 합동인 다각형"},{"l":"옆면과 밑면이 만나는 모양","r":"수직"}],"mis":"M6-1-u2-X03","explanation":["각기둥의 두 밑면은 서로 평행하고 합동인 다각형이에요.","옆면은 두 밑면과 만나는 면이고 모두 직사각형이에요.","직육면체는 면 6개·모서리 12개·꼭짓점 8개예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"서로 평행하고 합동인 두 면","r":"밑면"},{"l":"두 밑면과 만나는 면","r":"옆면"},{"l":"평행하고 합동인 다각형으로 이루어진 입체도형","r":"각기둥"}],"explanation":["각기둥의 두 밑면은 서로 평행하고 합동인 다각형이에요.","옆면은 두 밑면과 만나는 면이고 모두 직사각형이에요.","직육면체는 면 6개·모서리 12개·꼭짓점 8개예요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"직육면체의 면","r":"6개"},{"l":"직육면체의 모서리","r":"12개"},{"l":"직육면체의 꼭짓점","r":"8개"}],"explanation":["각기둥의 두 밑면은 서로 평행하고 합동인 다각형이에요.","옆면은 두 밑면과 만나는 면이고 모두 직사각형이에요.","직육면체는 면 6개·모서리 12개·꼭짓점 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#3','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'mc','auto','「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":3,"concept":"M6-1-u2-C1","difficulty":3,"kind":"mc","stem":"「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」을 이 조건에 하나씩 대어 봐요.","옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에 각기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평행한 두 면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행한 두 오각형의 크기가 다른 입체도형」을 이 조건에 하나씩 대어 봐요.","평행한 두 면이 서로 합동이 아니기 때문에 각기둥이 아니에요."]},{"stem":"「한 면이 육각형이고 나머지 면이 모두 삼각형인 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 면이 없기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X11"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「한 면이 육각형이고 나머지 면이 모두 삼각형인 입체도형」을 이 조건에 하나씩 대어 봐요.","서로 평행하고 합동인 두 면이 없기 때문에 각기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#4','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'error','auto','각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X14']::text[],true,'{"seq":4,"concept":"M6-1-u2-C1","difficulty":3,"kind":"error","stem":"각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「각기둥을 옆으로 눕히면 바닥에 닿은 옆면이 밑면이 돼.」","correct":true,"mis_target":"M6-1-u2-X01"},{"t":"이현 — 「각기둥의 옆면은 모두 직사각형이야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥을 눕혀도 서로 평행하고 합동인 두 면이 밑면이에요.","바닥에 닿은 면이 직사각형 옆면이면 그것은 여전히 옆면이에요.","준희는 밑면을 위치로 잘못 정했어요."],"variant_rule":{"alt":[{"stem":"오각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「옆면은 오각형이야.」","correct":true,"mis_target":"M6-1-u2-X03"},{"t":"수아 — 「밑면은 오각형 2개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「옆면은 5개야.」","mis":"M6-1-u2-X14"}],"explanation":["오각기둥의 밑면은 오각형 2개예요.","옆면은 밑면의 변 하나마다 하나씩, 모두 직사각형이에요.","서호는 옆면의 모양을 잘못 말했어요."]},{"stem":"육각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「옆면은 육각형이야.」","correct":true,"mis_target":"M6-1-u2-X03"},{"t":"나린 — 「밑면은 육각형 2개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「옆면은 6개야.」","mis":"M6-1-u2-X14"}],"explanation":["육각기둥의 밑면은 육각형 2개예요.","옆면은 밑면의 변 하나마다 하나씩, 모두 직사각형이에요.","가온은 옆면의 모양을 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#5','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'ox','auto','서로 평행한 두 면이 있으면 모두 각기둥이에요.',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":5,"concept":"M6-1-u2-C1","difficulty":3,"kind":"ox","stem":"서로 평행한 두 면이 있으면 모두 각기둥이에요.","answer":"X","reason_options":[{"t":"두 면이 서로 합동인 다각형이고 옆면이 직사각형이어야 하기 때문에","correct":true},{"t":"평행한 면이 둘이면 각기둥이라고 정했기 때문에","mis":"M6-1-u2-X02"}],"mis":"M6-1-u2-X02","explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."],"variant_rule":{"alt":[{"stem":"직육면체도 각기둥이에요.","answer":"O","reason_options":[{"t":"서로 평행하고 합동인 두 직사각형이 밑면이고 옆면이 직사각형이기 때문에","correct":true},{"t":"직육면체는 면이 6개라서 각기둥이 아니기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."]},{"stem":"원기둥도 두 밑면이 평행하고 합동이니 각기둥이에요.","answer":"X","reason_options":[{"t":"각기둥은 밑면이 다각형이어야 하는데 원은 다각형이 아니기 때문에","correct":true},{"t":"기둥 모양은 모두 각기둥이기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 직사각형이 옆면이에요.","밑면은 놓인 위치가 아니라 관계로 정해져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#6','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'sa','auto','가 서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통 · 나 서로 평행한 두 사각형의 크기가 서로 다른 저금통 · 다 서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자 · 라 위아래 면이 서로 평행하고 합동인 원인 저금통 · 마 서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필 — 이 가운데 각기둥 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C1","difficulty":3,"kind":"sa","stem":"가 서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통 · 나 서로 평행한 두 사각형의 크기가 서로 다른 저금통 · 다 서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자 · 라 위아래 면이 서로 평행하고 합동인 원인 저금통 · 마 서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필 — 이 가운데 각기둥 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["각기둥의 뜻에 하나씩 대어 봐요.","각기둥인 것은 가, 다, 마예요.","모두 3개예요."],"mis":"M6-1-u2-X02","variant_rule":{"alt":[{"stem":"가 서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자 · 나 한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통 · 다 서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필 · 라 굽은 면 하나로만 둘러싸인 공 모양 저금통 · 마 서로 평행한 두 사각형의 크기가 서로 다른 저금통 — 이 가운데 각기둥 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각기둥의 뜻에 하나씩 대어 봐요.","각기둥인 것은 가, 다예요.","모두 2개예요."]},{"stem":"가 서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통 · 나 한 원과 뾰족한 점이 있는 고깔 · 다 위아래 면이 서로 평행하고 합동인 원인 저금통 · 라 한 면이 오각형이고 나머지 면이 모두 삼각형인 탑 지붕 · 마 서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자 — 이 가운데 각기둥 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각기둥의 뜻에 하나씩 대어 봐요.","각기둥인 것은 가, 마예요.","모두 2개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#7','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',3,'mc','auto','사각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 사각형은 무엇인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X05']::text[],true,'{"seq":7,"concept":"M6-1-u2-C1","difficulty":3,"kind":"mc","stem":"사각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 사각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 사각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 사각형은 여전히 밑면이에요."],"variant_rule":{"alt":[{"stem":"칠각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 칠각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 칠각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 칠각형은 여전히 밑면이에요."]},{"stem":"팔각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 팔각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 팔각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 팔각형은 여전히 밑면이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#8','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',4,'sa','auto','밑면이 사각형인 각기둥과 밑면이 육각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C1","difficulty":4,"kind":"sa","stem":"밑면이 사각형인 각기둥과 밑면이 육각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["밑면 2개와 옆면 4개 — 4 + 2 = 6개예요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요.","두 수를 더하면 6 + 8 = 14개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 오각형인 각기둥과 밑면이 팔각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["밑면 2개와 옆면 5개 — 5 + 2 = 7개예요.","밑면 2개와 옆면 8개 — 8 + 2 = 10개예요.","두 수를 더하면 7 + 10 = 17개예요."]},{"stem":"밑면이 삼각형인 각기둥과 밑면이 칠각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["밑면 2개와 옆면 3개 — 3 + 2 = 5개예요.","밑면 2개와 옆면 7개 — 7 + 2 = 9개예요.","두 수를 더하면 5 + 9 = 14개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#9','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',4,'sa','auto','밑면이 육각형인 각기둥과 밑면이 구각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C1","difficulty":4,"kind":"sa","stem":"밑면이 육각형인 각기둥과 밑면이 구각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["밑면 2개와 옆면 6개 — 6 + 2 = 8개예요.","밑면 2개와 옆면 9개 — 9 + 2 = 11개예요.","두 수를 더하면 8 + 11 = 19개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 칠각형인 각기둥과 밑면이 십각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["밑면 2개와 옆면 7개 — 7 + 2 = 9개예요.","밑면 2개와 옆면 10개 — 10 + 2 = 12개예요.","두 수를 더하면 9 + 12 = 21개예요."]},{"stem":"밑면이 오각형인 각기둥과 밑면이 십이각형인 각기둥이 있어요. 두 각기둥의 면의 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["밑면 2개와 옆면 5개 — 5 + 2 = 7개예요.","밑면 2개와 옆면 12개 — 12 + 2 = 14개예요.","두 수를 더하면 7 + 14 = 21개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L02_challenge#10','math',6,1,'u2','L02','g6_1_math_u2_L02_challenge','lesson_challenge','M6-1-u2-C1',4,'essay','teacher','기부 저금통 가운데 하나는 서로 평행하고 합동인 두 오각형이 있는데 옆면이 평행사변형이고 밑면과 비스듬히 만나요. 이 저금통이 각기둥인지 아닌지 쓰고, 그 까닭을 각기둥의 뜻으로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C1","difficulty":4,"kind":"essay","stem":"기부 저금통 가운데 하나는 서로 평행하고 합동인 두 오각형이 있는데 옆면이 평행사변형이고 밑면과 비스듬히 만나요. 이 저금통이 각기둥인지 아닌지 쓰고, 그 까닭을 각기둥의 뜻으로 설명해 보세요.","answer_guide":{"answer":"예: 각기둥이 아니다. 각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어지고, 두 밑면과 만나는 옆면이 모두 직사각형이며 밑면과 수직으로 만나야 한다. 이 저금통은 두 오각형이 평행하고 합동이지만 옆면이 직사각형이 아니고 밑면과 비스듬히 만나므로 각기둥이 아니다.","scoring_points":["각기둥이 아니라고 답했는가","옆면이 직사각형이고 밑면과 수직이어야 한다는 조건을 썼는가","이 저금통은 옆면이 평행사변형이라 조건에 맞지 않는다고 설명했는가"]},"explanation":["각기둥의 옆면은 모두 직사각형이고 밑면과 수직으로 만나요.","이 저금통의 옆면은 평행사변형이고 비스듬해요.","그래서 각기둥이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#1','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',1,'mc','auto','밑면이 육각형인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":1,"concept":"M6-1-u2-C2","difficulty":1,"kind":"mc","stem":"밑면이 육각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"육각기둥","correct":true},{"t":"육각뿔","mis":"M6-1-u2-X11"},{"t":"팔각기둥","mis":"M6-1-u2-X04"},{"t":"십이각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 육각형이에요.","그래서 이름은 육각기둥이에요."],"variant_rule":{"alt":[{"stem":"밑면이 오각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X04"},{"t":"십각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 오각형이에요.","그래서 이름은 오각기둥이에요."]},{"stem":"밑면이 팔각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"팔각기둥","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X04"},{"t":"십육각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 팔각형이에요.","그래서 이름은 팔각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#2','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',1,'sa','auto','삼각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C2","difficulty":1,"kind":"sa","stem":"삼각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["삼각기둥의 밑면은 삼각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 3개, 아래 밑면 3개, 옆 모서리 3개 — 3 × 3 = 9개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"사각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["사각기둥의 밑면은 사각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 4개가 위아래로 짝을 이뤄 — 4 × 2 = 8개예요."]},{"stem":"삼각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["삼각기둥의 밑면은 삼각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 3개가 위아래로 짝을 이뤄 — 3 × 2 = 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#3','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',1,'mc','auto','각기둥에서 모서리는 무엇인가요?',ARRAY['M6-1-u2-X05','M6-1-u2-X06']::text[],true,'{"seq":3,"concept":"M6-1-u2-C2","difficulty":1,"kind":"mc","stem":"각기둥에서 모서리는 무엇인가요?","options":[{"t":"면과 면이 만나는 선분","correct":true},{"t":"모서리와 모서리가 만나는 점","mis":"M6-1-u2-X05"},{"t":"두 밑면 사이의 거리","mis":"M6-1-u2-X06"},{"t":"두 밑면과 만나는 면","mis":"M6-1-u2-X05"}],"explanation":["면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","두 밑면 사이의 거리가 높이예요.","그래서 모서리는 면과 면이 만나는 선분예요."],"variant_rule":{"alt":[{"stem":"각기둥에서 꼭짓점은 무엇인가요?","options":[{"t":"모서리와 모서리가 만나는 점","correct":true},{"t":"면과 면이 만나는 선분","mis":"M6-1-u2-X05"},{"t":"두 밑면 사이의 거리","mis":"M6-1-u2-X06"},{"t":"두 밑면과 만나는 면","mis":"M6-1-u2-X05"}],"explanation":["면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","두 밑면 사이의 거리가 높이예요.","그래서 꼭짓점은 모서리와 모서리가 만나는 점예요."]},{"stem":"각기둥에서 높이는 무엇인가요?","options":[{"t":"두 밑면 사이의 거리","correct":true},{"t":"면과 면이 만나는 선분","mis":"M6-1-u2-X06"},{"t":"모서리와 모서리가 만나는 점","mis":"M6-1-u2-X06"},{"t":"두 밑면과 만나는 면","mis":"M6-1-u2-X06"}],"explanation":["면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","두 밑면 사이의 거리가 높이예요.","그래서 높이는 두 밑면 사이의 거리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#4','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',1,'sa','auto','오각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C2","difficulty":1,"kind":"sa","stem":"오각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["오각기둥의 밑면은 오각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"육각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["육각기둥의 밑면은 육각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요."]},{"stem":"사각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["사각기둥의 밑면은 사각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 4개, 아래 밑면 4개, 옆 모서리 4개 — 4 × 3 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#5','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'mc','auto','막대 과자 상자 세 개의 옆면은 모두 직사각형으로 같아요. 세 상자의 이름을 서로 다르게 정하는 것은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X06']::text[],true,'{"seq":5,"concept":"M6-1-u2-C2","difficulty":2,"kind":"mc","stem":"막대 과자 상자 세 개의 옆면은 모두 직사각형으로 같아요. 세 상자의 이름을 서로 다르게 정하는 것은 무엇인가요?","options":[{"t":"밑면의 모양","correct":true},{"t":"옆면의 모양","mis":"M6-1-u2-X04"},{"t":"상자의 높이","mis":"M6-1-u2-X06"},{"t":"꼭짓점의 수","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 옆면은 모두 직사각형이라 모양이 같아요.","다른 것은 밑면의 모양뿐이라 이름도 밑면이 정해요.","그래서 답은 「밑면의 모양」이에요."],"variant_rule":{"alt":[{"stem":"직육면체 모양 과자 상자를 각기둥의 이름으로 부르면 무엇인가요?","options":[{"t":"사각기둥","correct":true},{"t":"육각기둥","mis":"M6-1-u2-X04"},{"t":"직사각기둥","mis":"M6-1-u2-X04"},{"t":"사각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥의 옆면은 모두 직사각형이라 모양이 같아요.","다른 것은 밑면의 모양뿐이라 이름도 밑면이 정해요.","그래서 답은 「사각기둥」이에요."]},{"stem":"밑면이 삼각형인 막대 과자 상자의 이름은 무엇인가요?","options":[{"t":"삼각기둥","correct":true},{"t":"삼각뿔","mis":"M6-1-u2-X11"},{"t":"육각기둥","mis":"M6-1-u2-X04"},{"t":"사각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 옆면은 모두 직사각형이라 모양이 같아요.","다른 것은 밑면의 모양뿐이라 이름도 밑면이 정해요.","그래서 답은 「삼각기둥」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#6','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'sa','auto','오각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"오각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["오각기둥의 밑면은 오각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 5개, 아래 밑면 5개, 옆 모서리 5개 — 5 × 3 = 15개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"육각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["육각기둥의 밑면은 육각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 6개, 아래 밑면 6개, 옆 모서리 6개 — 6 × 3 = 18개예요."]},{"stem":"칠각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["칠각기둥의 밑면은 칠각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 7개 — 7 + 2 = 9개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#7','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'mc','auto','각기둥의 높이를 재는 곳으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X06','M6-1-u2-X01']::text[],true,'{"seq":7,"concept":"M6-1-u2-C2","difficulty":2,"kind":"mc","stem":"각기둥의 높이를 재는 곳으로 알맞은 것은 어느 것인가요?","options":[{"t":"옆면과 옆면이 만나는 모서리","correct":true},{"t":"밑면의 가장 긴 변","mis":"M6-1-u2-X06"},{"t":"밑면의 둘레","mis":"M6-1-u2-X06"},{"t":"바닥에서 천장까지","mis":"M6-1-u2-X01"}],"explanation":["높이는 두 밑면 사이의 거리예요.","두 밑면이 평행해서 그 거리는 어디에서 재도 같아요.","그래서 옆면과 옆면이 만나는 모서리의 길이가 곧 높이예요."],"variant_rule":{"alt":[{"stem":"각기둥의 높이에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"두 밑면 사이의 거리이고 어디에서 재도 같아요","correct":true},{"t":"밑면의 가장 긴 변의 길이예요","mis":"M6-1-u2-X06"},{"t":"재는 곳마다 달라요","mis":"M6-1-u2-X06"},{"t":"바닥에 닿은 면의 둘레예요","mis":"M6-1-u2-X01"}],"explanation":["높이는 두 밑면 사이의 거리예요.","두 밑면이 평행해서 그 거리는 어디에서 재도 같아요.","그래서 옆면과 옆면이 만나는 모서리의 길이가 곧 높이예요."]},{"stem":"눕혀 놓은 오각기둥의 높이는 어디의 길이인가요?","options":[{"t":"두 오각형 밑면 사이의 거리","correct":true},{"t":"바닥에서 가장 높은 곳까지의 길이","mis":"M6-1-u2-X01"},{"t":"밑면의 한 변의 길이","mis":"M6-1-u2-X06"},{"t":"밑면의 둘레","mis":"M6-1-u2-X06"}],"explanation":["높이는 두 밑면 사이의 거리예요.","두 밑면이 평행해서 그 거리는 어디에서 재도 같아요.","그래서 옆면과 옆면이 만나는 모서리의 길이가 곧 높이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#8','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'sa','auto','문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 3 cm, 4 cm, 5 cm이고 옆면과 옆면이 만나는 모서리가 7 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 3 cm, 4 cm, 5 cm이고 옆면과 옆면이 만나는 모서리가 7 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 3 cm, 4 cm, 5 cm는 높이가 아니에요 — 높이는 7 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 5 cm, 12 cm, 13 cm이고 옆면과 옆면이 만나는 모서리가 9 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 5 cm, 12 cm, 13 cm는 높이가 아니에요 — 높이는 9 cm예요."]},{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 6 cm, 8 cm, 10 cm이고 옆면과 옆면이 만나는 모서리가 4 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 6 cm, 8 cm, 10 cm는 높이가 아니에요 — 높이는 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#9','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',2,'ox','auto','직육면체와 정육면체는 사각기둥이에요.',ARRAY['M6-1-u2-X04']::text[],true,'{"seq":9,"concept":"M6-1-u2-C2","difficulty":2,"kind":"ox","stem":"직육면체와 정육면체는 사각기둥이에요.","answer":"O","reason_options":[{"t":"밑면이 사각형인 각기둥이기 때문에","correct":true},{"t":"면이 6개라 육각기둥이기 때문에","mis":"M6-1-u2-X04"}],"mis":"M6-1-u2-X04","explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."],"variant_rule":{"alt":[{"stem":"각기둥의 이름은 옆면의 모양으로 정해요.","answer":"X","reason_options":[{"t":"옆면은 모두 직사각형이고 이름은 밑면의 모양으로 정하기 때문에","correct":true},{"t":"옆면의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]},{"stem":"면과 면이 만나는 선분을 꼭짓점이라고 해요.","answer":"X","reason_options":[{"t":"그 선분은 모서리이고 모서리와 모서리가 만나는 점이 꼭짓점이기 때문에","correct":true},{"t":"선분의 끝이 꼭짓점이기 때문에","mis":"M6-1-u2-X05"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_basic#10','math',6,1,'u2','L03','g6_1_math_u2_L03_basic','lesson_basic','M6-1-u2-C2',3,'mc','auto','두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 10개인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":10,"concept":"M6-1-u2-C2","difficulty":3,"kind":"mc","stem":"두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 10개인 각기둥의 이름은 무엇인가요?","options":[{"t":"오각기둥","correct":true},{"t":"십각기둥","mis":"M6-1-u2-X04"},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"육각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점은 변의 수 × 2예요.","꼭짓점이 10개이니 한 밑면의 변은 5개예요.","밑면이 오각형이라 이름은 오각기둥이에요."],"variant_rule":{"alt":[{"stem":"두 밑면이 서로 평행하고 합동인 다각형이고 모서리가 18개인 각기둥의 이름은 무엇인가요?","options":[{"t":"육각기둥","correct":true},{"t":"십팔각기둥","mis":"M6-1-u2-X04"},{"t":"육각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리는 변의 수 × 3이에요.","모서리가 18개이니 한 밑면의 변은 6개예요.","밑면이 육각형이라 이름은 육각기둥이에요."]},{"stem":"두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 8개인 각기둥의 이름은 무엇인가요?","options":[{"t":"사각기둥","correct":true},{"t":"팔각기둥","mis":"M6-1-u2-X04"},{"t":"사각뿔","mis":"M6-1-u2-X11"},{"t":"오각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점은 변의 수 × 2예요.","꼭짓점이 8개이니 한 밑면의 변은 4개예요.","밑면이 사각형이라 이름은 사각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#1','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',2,'sa','auto','팔각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"팔각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["팔각기둥의 밑면은 팔각형이에요.","모서리를 세는 방법을 떠올려요.","위 밑면 8개, 아래 밑면 8개, 옆 모서리 8개 — 8 × 3 = 24개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"칠각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["칠각기둥의 밑면은 칠각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요."]},{"stem":"구각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["구각기둥의 밑면은 구각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 9개 — 9 + 2 = 11개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#2','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',2,'match','auto','각기둥과 그 꼭짓점 수를 알맞게 이으세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C2","difficulty":2,"kind":"match","stem":"각기둥과 그 꼭짓점 수를 알맞게 이으세요.","pairs":[{"l":"삼각기둥","r":"6개"},{"l":"오각기둥","r":"10개"},{"l":"육각기둥","r":"12개"}],"mis":"M6-1-u2-X05","explanation":["꼭짓점의 수는 변의 수 × 2예요.","삼각기둥 6개, 오각기둥 10개, 육각기둥 12개예요.","밑면의 변의 수부터 보면 바로 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"각기둥과 그 모서리 수를 알맞게 이으세요.","pairs":[{"l":"사각기둥","r":"12개"},{"l":"육각기둥","r":"18개"},{"l":"팔각기둥","r":"24개"}],"explanation":["모서리의 수는 변의 수 × 3이에요.","사각기둥 12개, 육각기둥 18개, 팔각기둥 24개예요.","밑면의 변의 수부터 보면 바로 구할 수 있어요."]},{"stem":"각기둥과 그 면 수를 알맞게 이으세요.","pairs":[{"l":"삼각기둥","r":"5개"},{"l":"사각기둥","r":"6개"},{"l":"칠각기둥","r":"9개"}],"explanation":["면의 수는 변의 수 + 2예요.","삼각기둥 5개, 사각기둥 6개, 칠각기둥 9개예요.","밑면의 변의 수부터 보면 바로 구할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#3','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'error','auto','각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X06','M6-1-u2-X14']::text[],true,'{"seq":3,"concept":"M6-1-u2-C2","difficulty":3,"kind":"error","stem":"각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「각기둥의 높이는 밑면의 가장 긴 변의 길이야.」","correct":true,"mis_target":"M6-1-u2-X06"},{"t":"이현 — 「각기둥의 밑면은 2개야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「각기둥의 밑면은 옆면과 수직으로 만나.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 변은 밑면 안의 선분이라 높이가 될 수 없어요.","준희는 높이를 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"육각기둥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「꼭짓점이 6개야.」","correct":true,"mis_target":"M6-1-u2-X05"},{"t":"수아 — 「모서리가 18개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「면이 8개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요.","위 밑면 6개, 아래 밑면 6개, 옆 모서리 6개 — 6 × 3 = 18개예요.","서호는 한 밑면의 꼭짓점만 세었어요."]},{"stem":"오각기둥을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꼭짓점이 5개야.」","correct":true,"mis_target":"M6-1-u2-X05"},{"t":"나린 — 「모서리가 15개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「면이 7개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요.","위 밑면 5개, 아래 밑면 5개, 옆 모서리 5개 — 5 × 3 = 15개예요.","가온은 한 밑면의 꼭짓점만 세었어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#4','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'ox','auto','각기둥의 높이는 밑면의 가장 긴 변의 길이예요.',ARRAY['M6-1-u2-X06']::text[],true,'{"seq":4,"concept":"M6-1-u2-C2","difficulty":3,"kind":"ox","stem":"각기둥의 높이는 밑면의 가장 긴 변의 길이예요.","answer":"X","reason_options":[{"t":"높이는 두 밑면 사이의 거리이기 때문에","correct":true},{"t":"밑면의 변이 길수록 높아지기 때문에","mis":"M6-1-u2-X06"}],"mis":"M6-1-u2-X06","explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."],"variant_rule":{"alt":[{"stem":"밑면의 변의 수가 늘면 각기둥의 모서리와 꼭짓점도 늘어요.","answer":"O","reason_options":[{"t":"모서리와 꼭짓점의 수가 모두 밑면의 변의 수에서 나오기 때문에","correct":true},{"t":"옆면의 모양이 바뀌기 때문에","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]},{"stem":"꼭짓점이 10개인 각기둥은 십각기둥이에요.","answer":"X","reason_options":[{"t":"꼭짓점은 한 밑면의 꼭짓점의 2배라 밑면이 오각형인 오각기둥이기 때문에","correct":true},{"t":"이름은 꼭짓점의 수로 정하기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#5','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'mc','auto','두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 14개인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":5,"concept":"M6-1-u2-C2","difficulty":3,"kind":"mc","stem":"두 밑면이 서로 평행하고 합동인 다각형이고 꼭짓점이 14개인 각기둥의 이름은 무엇인가요?","options":[{"t":"칠각기둥","correct":true},{"t":"십사각기둥","mis":"M6-1-u2-X04"},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"팔각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점은 변의 수 × 2예요.","꼭짓점이 14개이니 한 밑면의 변은 7개예요.","밑면이 칠각형이라 이름은 칠각기둥이에요."],"variant_rule":{"alt":[{"stem":"두 밑면이 서로 평행하고 합동인 다각형이고 모서리가 24개인 각기둥의 이름은 무엇인가요?","options":[{"t":"팔각기둥","correct":true},{"t":"이십사각기둥","mis":"M6-1-u2-X04"},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리는 변의 수 × 3이에요.","모서리가 24개이니 한 밑면의 변은 8개예요.","밑면이 팔각형이라 이름은 팔각기둥이에요."]},{"stem":"두 밑면이 서로 평행하고 합동인 다각형이고 면이 7개인 각기둥의 이름은 무엇인가요?","options":[{"t":"오각기둥","correct":true},{"t":"칠각기둥","mis":"M6-1-u2-X04"},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"육각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 면은 변의 수 + 2예요.","면이 7개이니 한 밑면의 변은 5개예요.","밑면이 오각형이라 이름은 오각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#6','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'sa','auto','오각기둥의 모서리 수와 꼭짓점 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C2","difficulty":3,"kind":"sa","stem":"오각기둥의 모서리 수와 꼭짓점 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["25"],"explanation":["위 밑면 5개, 아래 밑면 5개, 옆 모서리 5개 — 5 × 3 = 15개예요.","한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요.","두 수를 더하면 15 + 10 = 25개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"육각기둥의 면 수와 꼭짓점 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["밑면 2개와 옆면 6개 — 6 + 2 = 8개예요.","한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요.","두 수를 더하면 8 + 12 = 20개예요."]},{"stem":"사각기둥의 모서리 수와 면 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["위 밑면 4개, 아래 밑면 4개, 옆 모서리 4개 — 4 × 3 = 12개예요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요.","두 수를 더하면 12 + 6 = 18개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#7','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',3,'sa','auto','문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 9 cm, 12 cm, 15 cm이고 옆면과 옆면이 만나는 모서리가 11 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u2-C2","difficulty":3,"kind":"sa","stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 9 cm, 12 cm, 15 cm이고 옆면과 옆면이 만나는 모서리가 11 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 9 cm, 12 cm, 15 cm는 높이가 아니에요 — 높이는 11 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 8 cm, 15 cm, 17 cm이고 옆면과 옆면이 만나는 모서리가 6 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 8 cm, 15 cm, 17 cm는 높이가 아니에요 — 높이는 6 cm예요."]},{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 7 cm, 24 cm, 25 cm이고 옆면과 옆면이 만나는 모서리가 10 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 7 cm, 24 cm, 25 cm는 높이가 아니에요 — 높이는 10 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#8','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',4,'sa','auto','밑면이 한 변이 4 cm인 정삼각형이고 높이가 5 cm인 삼각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C2","difficulty":4,"kind":"sa","stem":"밑면이 한 변이 4 cm인 정삼각형이고 높이가 5 cm인 삼각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["두 밑면의 변은 3개씩 — 3 × 2 = 6개이고 모두 4 cm예요.","옆 모서리는 3개이고 모두 높이와 같은 5 cm예요.","6 × 4 + 3 × 5 = 39 — 모두 39 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"밑면이 한 변이 3 cm인 정사각형이고 높이가 6 cm인 사각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["두 밑면의 변은 4개씩 — 4 × 2 = 8개이고 모두 3 cm예요.","옆 모서리는 4개이고 모두 높이와 같은 6 cm예요.","8 × 3 + 4 × 6 = 48 — 모두 48 cm예요."]},{"stem":"밑면이 한 변이 2 cm인 정오각형이고 높이가 7 cm인 오각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["55"],"explanation":["두 밑면의 변은 5개씩 — 5 × 2 = 10개이고 모두 2 cm예요.","옆 모서리는 5개이고 모두 높이와 같은 7 cm예요.","10 × 2 + 5 × 7 = 55 — 모두 55 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#9','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',4,'sa','auto','밑면이 한 변이 3 cm인 정육각형이고 높이가 5 cm인 육각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C2","difficulty":4,"kind":"sa","stem":"밑면이 한 변이 3 cm인 정육각형이고 높이가 5 cm인 육각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["66"],"explanation":["두 밑면의 변은 6개씩 — 6 × 2 = 12개이고 모두 3 cm예요.","옆 모서리는 6개이고 모두 높이와 같은 5 cm예요.","12 × 3 + 6 × 5 = 66 — 모두 66 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"밑면이 한 변이 5 cm인 정삼각형이고 높이가 9 cm인 삼각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["57"],"explanation":["두 밑면의 변은 3개씩 — 3 × 2 = 6개이고 모두 5 cm예요.","옆 모서리는 3개이고 모두 높이와 같은 9 cm예요.","6 × 5 + 3 × 9 = 57 — 모두 57 cm예요."]},{"stem":"밑면이 한 변이 5 cm인 정사각형이고 높이가 8 cm인 사각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["두 밑면의 변은 4개씩 — 4 × 2 = 8개이고 모두 5 cm예요.","옆 모서리는 4개이고 모두 높이와 같은 8 cm예요.","8 × 5 + 4 × 8 = 72 — 모두 72 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L03_challenge#10','math',6,1,'u2','L03','g6_1_math_u2_L03_challenge','lesson_challenge','M6-1-u2-C2',4,'essay','teacher','삼각기둥 모양 문 고정 받침대의 밑면의 세 변이 3 cm, 4 cm, 5 cm이고 옆면과 옆면이 만나는 모서리가 7 cm예요. 친구가 「높이는 가장 긴 변인 5 cm야」라고 했어요. 잘못된 점을 쓰고 높이를 바르게 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C2","difficulty":4,"kind":"essay","stem":"삼각기둥 모양 문 고정 받침대의 밑면의 세 변이 3 cm, 4 cm, 5 cm이고 옆면과 옆면이 만나는 모서리가 7 cm예요. 친구가 「높이는 가장 긴 변인 5 cm야」라고 했어요. 잘못된 점을 쓰고 높이를 바르게 구해 보세요.","answer_guide":{"answer":"예: 각기둥의 높이는 두 밑면 사이의 거리인데 5 cm는 밑면 안에 있는 변의 길이라 높이가 아니다. 두 밑면이 평행하고 옆면과 옆면이 만나는 모서리는 두 밑면과 수직이므로 그 모서리의 길이 7 cm가 높이이다.","scoring_points":["높이는 두 밑면 사이의 거리라고 썼는가","5 cm는 밑면의 변이라 높이가 아니라고 썼는가","높이를 7 cm로 구했는가"]},"explanation":["높이는 두 밑면 사이의 거리예요.","5 cm는 밑면의 변이에요.","옆 모서리 7 cm가 높이예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#1','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',1,'mc','auto','각기둥의 전개도에서 점선은 무엇을 나타내나요?',ARRAY['M6-1-u2-X07']::text[],true,'{"seq":1,"concept":"M6-1-u2-C3","difficulty":1,"kind":"mc","stem":"각기둥의 전개도에서 점선은 무엇을 나타내나요?","options":[{"t":"잘리지 않고 접히는 모서리","correct":true},{"t":"잘린 모서리","mis":"M6-1-u2-X07"},{"t":"밑면의 둘레","mis":"M6-1-u2-X07"},{"t":"옆면의 넓이","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘리지 않고 접히는 모서리」예요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도에서 실선은 무엇을 나타내나요?","options":[{"t":"잘린 모서리","correct":true},{"t":"잘리지 않고 접히는 모서리","mis":"M6-1-u2-X07"},{"t":"각기둥의 높이","mis":"M6-1-u2-X06"},{"t":"밑면의 대각선","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘린 모서리」예요."]},{"stem":"각기둥의 전개도는 어떤 그림인가요?","options":[{"t":"모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림","correct":true},{"t":"면을 하나씩 모두 떼어 늘어놓은 그림","mis":"M6-1-u2-X07"},{"t":"각기둥을 위에서 내려다본 그림","mis":"M6-1-u2-X07"},{"t":"밑면만 따라 그린 그림","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#2','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',1,'sa','auto','육각기둥의 전개도에서 옆면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C3","difficulty":1,"kind":"sa","stem":"육각기둥의 전개도에서 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 6개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면의 변 하나마다 옆면이 하나 — 6개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"오각기둥의 전개도에서 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 5개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면의 변 하나마다 옆면이 하나 — 5개예요."]},{"stem":"팔각기둥의 전개도에서 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 8개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면의 변 하나마다 옆면이 하나 — 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#3','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',1,'mc','auto','삼각형 2개와 직사각형 3개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":3,"concept":"M6-1-u2-C3","difficulty":1,"kind":"mc","stem":"삼각형 2개와 직사각형 3개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"삼각기둥","correct":true},{"t":"삼각뿔","mis":"M6-1-u2-X11"},{"t":"오각기둥","mis":"M6-1-u2-X08"},{"t":"육각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 삼각형 2개가 밑면이 돼요.","직사각형 3개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 삼각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"오각형 2개와 직사각형 5개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X08"},{"t":"십각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 오각형 2개가 밑면이 돼요.","직사각형 5개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 오각기둥이 돼요."]},{"stem":"육각형 2개와 직사각형 6개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"육각기둥","correct":true},{"t":"육각뿔","mis":"M6-1-u2-X11"},{"t":"팔각기둥","mis":"M6-1-u2-X08"},{"t":"십이각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 육각형 2개가 밑면이 돼요.","직사각형 6개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 육각기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#4','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',1,'sa','auto','삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 삼각형은 몇 개 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C3","difficulty":1,"kind":"sa","stem":"삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 삼각형은 몇 개 있나요? 숫자로 쓰세요.","answer":["2"],"explanation":["삼각기둥의 밑면은 삼각형 2개예요.","옆면은 밑면의 변의 수만큼 — 직사각형 3개예요.","펼친 그림에는 삼각형 2개와 직사각형 3개, 모두 2 + 3 = 5개가 이어져 있어요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 직사각형은 몇 개 있나요? 숫자로 쓰세요.","answer":["3"],"explanation":["삼각기둥의 밑면은 삼각형 2개예요.","옆면은 밑면의 변의 수만큼 — 직사각형 3개예요.","펼친 그림에는 삼각형 2개와 직사각형 3개, 모두 2 + 3 = 5개가 이어져 있어요."]},{"stem":"삼각기둥 모양 집 모형을 모서리를 따라 잘라 펼쳤어요. 펼친 그림에 면은 모두 몇 개 있나요? 숫자로 쓰세요.","answer":["5"],"explanation":["삼각기둥의 밑면은 삼각형 2개예요.","옆면은 밑면의 변의 수만큼 — 직사각형 3개예요.","펼친 그림에는 삼각형 2개와 직사각형 3개, 모두 2 + 3 = 5개가 이어져 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#5','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'sa','auto','사각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C3","difficulty":2,"kind":"sa","stem":"사각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["6"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 4개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"육각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["8"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 6개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요."]},{"stem":"오각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["7"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 5개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 5개 — 5 + 2 = 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#6','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'mc','auto','각기둥의 전개도를 접었을 때 서로 맞닿는 두 선분에 대한 설명으로 옳은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":6,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"각기둥의 전개도를 접었을 때 서로 맞닿는 두 선분에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"길이가 항상 같아요","correct":true},{"t":"길이가 항상 달라요","mis":"M6-1-u2-X09"},{"t":"긴 쪽이 밑면이 돼요","mis":"M6-1-u2-X09"},{"t":"길이는 상관없어요","mis":"M6-1-u2-X09"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."],"variant_rule":{"alt":[{"stem":"전개도의 양쪽 끝에 있는 두 선분은 접었을 때 어떻게 되나요?","options":[{"t":"서로 맞닿아 하나의 모서리가 돼요","correct":true},{"t":"서로 떨어져 있어요","mis":"M6-1-u2-X07"},{"t":"밑면이 돼요","mis":"M6-1-u2-X01"},{"t":"잘라서 버려요","mis":"M6-1-u2-X07"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."]},{"stem":"전개도에서 맞닿는 두 선분의 길이가 다르면 어떻게 되나요?","options":[{"t":"접었을 때 틈이 생기거나 남는 곳이 생겨요","correct":true},{"t":"그대로 각기둥이 돼요","mis":"M6-1-u2-X09"},{"t":"각뿔이 돼요","mis":"M6-1-u2-X11"},{"t":"면의 수가 늘어나요","mis":"M6-1-u2-X08"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#7','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'ox','auto','전개도에서 잘린 모서리는 점선으로 나타내요.',ARRAY['M6-1-u2-X07']::text[],true,'{"seq":7,"concept":"M6-1-u2-C3","difficulty":2,"kind":"ox","stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 접히는 모서리가 점선이기 때문에","correct":true},{"t":"잘린 곳은 끊어져 보이게 점선으로 그리기 때문에","mis":"M6-1-u2-X07"}],"mis":"M6-1-u2-X07","explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","answer":"O","reason_options":[{"t":"밑면의 변 하나마다 옆면이 하나씩 세워지기 때문에","correct":true},{"t":"옆면은 언제나 4개이기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]},{"stem":"면들이 서로 떨어져 있는 그림도 전개도예요.","answer":"X","reason_options":[{"t":"전개도는 모든 면이 이어지도록 펼친 그림이기 때문에","correct":true},{"t":"면의 수만 맞으면 되기 때문에","mis":"M6-1-u2-X07"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#8','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'mc','auto','사각형 2개와 직사각형 4개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":8,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"사각형 2개와 직사각형 4개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"사각기둥","correct":true},{"t":"사각뿔","mis":"M6-1-u2-X11"},{"t":"육각기둥","mis":"M6-1-u2-X08"},{"t":"팔각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 사각형 2개가 밑면이 돼요.","직사각형 4개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 사각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"칠각형 2개와 직사각형 7개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"칠각기둥","correct":true},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X08"},{"t":"십사각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 칠각형 2개가 밑면이 돼요.","직사각형 7개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 칠각기둥이 돼요."]},{"stem":"팔각형 2개와 직사각형 8개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"팔각기둥","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X08"},{"t":"십육각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 팔각형 2개가 밑면이 돼요.","직사각형 8개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 팔각기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#9','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',2,'mc','auto','「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X08']::text[],true,'{"seq":9,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","correct":true},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 옆면의 수가 한 밑면의 변의 수와 다르기 때문에 전개도가 아니에요."],"variant_rule":{"alt":[{"stem":"「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 1개뿐이기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 밑면이 1개뿐이기 때문에 전개도가 아니에요."]},{"stem":"「크기가 다른 사각형 2개와 직사각형 4개가 이어진 그림」은 사각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X02"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 두 밑면이 서로 합동이 아니기 때문에 전개도가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_basic#10','math',6,1,'u2','L04','g6_1_math_u2_L04_basic','lesson_basic','M6-1-u2-C3',3,'sa','auto','어떤 각기둥의 전개도에 옆면이 5개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u2-C3","difficulty":3,"kind":"sa","stem":"어떤 각기둥의 전개도에 옆면이 5개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["옆면의 수는 한 밑면의 변의 수와 같아요 — 밑면은 오각형이에요.","그래서 이 입체도형은 오각기둥이에요.","위 밑면 5개, 아래 밑면 5개, 옆 모서리 5개 — 5 × 3 = 15개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"어떤 각기둥의 전개도에 옆면이 6개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["옆면의 수는 한 밑면의 변의 수와 같아요 — 밑면은 육각형이에요.","그래서 이 입체도형은 육각기둥이에요.","위 밑면 6개, 아래 밑면 6개, 옆 모서리 6개 — 6 × 3 = 18개예요."]},{"stem":"어떤 각기둥의 전개도에 옆면이 4개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면의 수는 한 밑면의 변의 수와 같아요 — 밑면은 사각형이에요.","그래서 이 입체도형은 사각기둥이에요.","위 밑면 4개, 아래 밑면 4개, 옆 모서리 4개 — 4 × 3 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#1','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',2,'sa','auto','팔각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C3","difficulty":2,"kind":"sa","stem":"팔각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["10"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 8개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 8개 — 8 + 2 = 10개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"칠각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["9"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 7개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 7개 — 7 + 2 = 9개예요."]},{"stem":"구각기둥의 전개도에는 면이 모두 몇 개 그려져 있나요? 숫자로 쓰세요.","answer":["11"],"explanation":["밑면의 변 하나마다 옆면이 하나씩 세워져요 — 옆면은 9개예요.","전개도에는 밑면 2개도 함께 그려져요.","밑면 2개와 옆면 9개 — 9 + 2 = 11개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#2','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',2,'ox','auto','전개도를 접을 때 맞닿는 두 선분의 길이는 같아야 해요.',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":2,"concept":"M6-1-u2-C3","difficulty":2,"kind":"ox","stem":"전개도를 접을 때 맞닿는 두 선분의 길이는 같아야 해요.","answer":"O","reason_options":[{"t":"두 선분이 맞닿아 하나의 모서리가 되기 때문에","correct":true},{"t":"긴 선분이 짧은 선분을 덮기 때문에","mis":"M6-1-u2-X09"}],"mis":"M6-1-u2-X09","explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."],"variant_rule":{"alt":[{"stem":"육각기둥의 전개도에는 면이 6개 그려져요.","answer":"X","reason_options":[{"t":"밑면 2개와 옆면 6개 — 면이 8개 그려지기 때문에","correct":true},{"t":"육각기둥이니 면도 6개이기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]},{"stem":"전개도에는 밑면이 1개만 그려져 있어도 돼요.","answer":"X","reason_options":[{"t":"각기둥은 밑면이 2개라 전개도에도 2개가 있어야 하기 때문에","correct":true},{"t":"접으면 밑면이 저절로 생기기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#3','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',3,'mc','auto','「오각형 2개와 직사각형 5개가 이어졌는데, 두 오각형이 같은 쪽에 붙어 접으면 겹치는 그림」은 오각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X13']::text[],true,'{"seq":3,"concept":"M6-1-u2-C3","difficulty":3,"kind":"mc","stem":"「오각형 2개와 직사각형 5개가 이어졌는데, 두 오각형이 같은 쪽에 붙어 접으면 겹치는 그림」은 오각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X13"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X13"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X13"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 접으면 두 밑면이 겹쳐 맞닿지 않기 때문에 전개도가 아니에요."],"variant_rule":{"alt":[{"stem":"「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","correct":true},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 옆면의 수가 한 밑면의 변의 수와 다르기 때문에 전개도가 아니에요."]},{"stem":"「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 1개뿐이기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 밑면이 1개뿐이기 때문에 전개도가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED