INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#4','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',3,'error','auto','오각기둥의 전개도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X08','M6-1-u2-X14']::text[],true,'{"seq":4,"concept":"M6-1-u2-C3","difficulty":3,"kind":"error","stem":"오각기둥의 전개도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「옆면이 7개 그려져 있어.」","correct":true,"mis_target":"M6-1-u2-X08"},{"t":"이현 — 「밑면이 2개 그려져 있어.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「접히는 모서리는 점선이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","오각기둥의 옆면은 5개, 밑면은 2개예요.","준희는 면 전체의 수를 옆면의 수로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"육각기둥의 전개도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「옆면이 8개 그려져 있어.」","correct":true,"mis_target":"M6-1-u2-X08"},{"t":"수아 — 「밑면이 2개 그려져 있어.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「접히는 모서리는 점선이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","육각기둥의 옆면은 6개, 밑면은 2개예요.","서호는 면 전체의 수를 옆면의 수로 잘못 말했어요."]},{"stem":"사각기둥의 전개도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「옆면이 6개 그려져 있어.」","correct":true,"mis_target":"M6-1-u2-X08"},{"t":"나린 — 「밑면이 2개 그려져 있어.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「접히는 모서리는 점선이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","사각기둥의 옆면은 4개, 밑면은 2개예요.","가온은 면 전체의 수를 옆면의 수로 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#5','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',3,'sa','auto','어떤 각기둥의 전개도에 옆면이 7개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C3","difficulty":3,"kind":"sa","stem":"어떤 각기둥의 전개도에 옆면이 7개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["옆면의 수는 한 밑면의 변의 수와 같아요 — 밑면은 칠각형이에요.","그래서 이 입체도형은 칠각기둥이에요.","위 밑면 7개, 아래 밑면 7개, 옆 모서리 7개 — 7 × 3 = 21개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"어떤 각기둥의 전개도에 옆면이 8개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면의 수는 한 밑면의 변의 수와 같아요 — 밑면은 팔각형이에요.","그래서 이 입체도형은 팔각기둥이에요.","위 밑면 8개, 아래 밑면 8개, 옆 모서리 8개 — 8 × 3 = 24개예요."]},{"stem":"어떤 각기둥의 전개도에 옆면이 9개 그려져 있어요. 이 각기둥의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["27"],"explanation":["옆면의 수는 한 밑면의 변의 수와 같아요 — 밑면은 구각형이에요.","그래서 이 입체도형은 구각기둥이에요.","위 밑면 9개, 아래 밑면 9개, 옆 모서리 9개 — 9 × 3 = 27개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#6','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',3,'mc','auto','전개도에서 맞닿는 두 선분의 길이가 다르면 어떻게 되나요?',ARRAY['M6-1-u2-X09','M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":6,"concept":"M6-1-u2-C3","difficulty":3,"kind":"mc","stem":"전개도에서 맞닿는 두 선분의 길이가 다르면 어떻게 되나요?","options":[{"t":"접었을 때 틈이 생기거나 남는 곳이 생겨요","correct":true},{"t":"그대로 각기둥이 돼요","mis":"M6-1-u2-X09"},{"t":"각뿔이 돼요","mis":"M6-1-u2-X11"},{"t":"면의 수가 늘어나요","mis":"M6-1-u2-X08"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도를 접었을 때 서로 맞닿는 두 선분에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"길이가 항상 같아요","correct":true},{"t":"길이가 항상 달라요","mis":"M6-1-u2-X09"},{"t":"긴 쪽이 밑면이 돼요","mis":"M6-1-u2-X09"},{"t":"길이는 상관없어요","mis":"M6-1-u2-X09"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."]},{"stem":"전개도의 양쪽 끝에 있는 두 선분은 접었을 때 어떻게 되나요?","options":[{"t":"서로 맞닿아 하나의 모서리가 돼요","correct":true},{"t":"서로 떨어져 있어요","mis":"M6-1-u2-X07"},{"t":"밑면이 돼요","mis":"M6-1-u2-X01"},{"t":"잘라서 버려요","mis":"M6-1-u2-X07"}],"explanation":["전개도를 접으면 떨어져 있던 두 선분이 서로 맞닿아 모서리 하나가 돼요.","그래서 맞닿는 두 선분의 길이는 같아야 해요.","길이가 다르면 접었을 때 딱 맞물리지 않아요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#7','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',3,'mc','auto','구각형 2개와 직사각형 9개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":7,"concept":"M6-1-u2-C3","difficulty":3,"kind":"mc","stem":"구각형 2개와 직사각형 9개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X08"},{"t":"십팔각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 구각형 2개가 밑면이 돼요.","직사각형 9개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 구각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"십각형 2개와 직사각형 10개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"십각기둥","correct":true},{"t":"십각뿔","mis":"M6-1-u2-X11"},{"t":"십이각기둥","mis":"M6-1-u2-X08"},{"t":"이십각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 십각형 2개가 밑면이 돼요.","직사각형 10개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 십각기둥이 돼요."]},{"stem":"십이각형 2개와 직사각형 12개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"십이각기둥","correct":true},{"t":"십이각뿔","mis":"M6-1-u2-X11"},{"t":"십사각기둥","mis":"M6-1-u2-X08"},{"t":"이십사각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 십이각형 2개가 밑면이 돼요.","직사각형 12개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 십이각기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#8','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',4,'sa','auto','삼각기둥의 모서리를 잘라 전개도를 만들었어요. 면 5개가 하나로 이어져 있으려면 잘리지 않고 접히는 모서리가 면의 수보다 1 적어요. 접히는 모서리(점선)는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C3","difficulty":4,"kind":"sa","stem":"삼각기둥의 모서리를 잘라 전개도를 만들었어요. 면 5개가 하나로 이어져 있으려면 잘리지 않고 접히는 모서리가 면의 수보다 1 적어요. 접히는 모서리(점선)는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["면 5개를 하나로 이으려면 이음선이 5 − 1 = 4개 필요해요 — 접히는 모서리예요.","삼각기둥의 모서리는 모두 3 × 3 = 9개예요.","그래서 점선은 4개예요."],"mis":"M6-1-u2-X07","variant_rule":{"alt":[{"stem":"오각기둥의 모서리를 잘라 전개도를 만들었어요. 면 7개가 하나로 이어져 있으려면 잘리지 않고 접히는 모서리가 면의 수보다 1 적어요. 접히는 모서리(점선)는 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["면 7개를 하나로 이으려면 이음선이 7 − 1 = 6개 필요해요 — 접히는 모서리예요.","오각기둥의 모서리는 모두 5 × 3 = 15개예요.","그래서 점선은 6개예요."]},{"stem":"육각기둥의 모서리를 잘라 전개도를 만들었어요. 면 8개가 하나로 이어져 있으려면 잘리지 않고 접히는 모서리가 면의 수보다 1 적어요. 접히는 모서리(점선)는 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["면 8개를 하나로 이으려면 이음선이 8 − 1 = 7개 필요해요 — 접히는 모서리예요.","육각기둥의 모서리는 모두 6 × 3 = 18개예요.","그래서 점선은 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#9','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',4,'sa','auto','사각기둥의 모서리를 잘라 전개도를 만들었어요. 면 6개가 하나로 이어져 있으려면 잘리지 않고 접히는 모서리가 면의 수보다 1 적어요. 잘린 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C3","difficulty":4,"kind":"sa","stem":"사각기둥의 모서리를 잘라 전개도를 만들었어요. 면 6개가 하나로 이어져 있으려면 잘리지 않고 접히는 모서리가 면의 수보다 1 적어요. 잘린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["면 6개를 하나로 이으려면 이음선이 6 − 1 = 5개 필요해요 — 접히는 모서리예요.","사각기둥의 모서리는 모두 4 × 3 = 12개예요.","잘린 모서리는 12 − 5 = 7개예요."],"mis":"M6-1-u2-X07","variant_rule":{"alt":[{"stem":"삼각기둥의 모서리를 잘라 전개도를 만들었어요. 면 5개가 하나로 이어져 있으려면 잘리지 않고 접히는 모서리가 면의 수보다 1 적어요. 잘린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["면 5개를 하나로 이으려면 이음선이 5 − 1 = 4개 필요해요 — 접히는 모서리예요.","삼각기둥의 모서리는 모두 3 × 3 = 9개예요.","잘린 모서리는 9 − 4 = 5개예요."]},{"stem":"오각기둥의 모서리를 잘라 전개도를 만들었어요. 면 7개가 하나로 이어져 있으려면 잘리지 않고 접히는 모서리가 면의 수보다 1 적어요. 잘린 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["면 7개를 하나로 이으려면 이음선이 7 − 1 = 6개 필요해요 — 접히는 모서리예요.","오각기둥의 모서리는 모두 5 × 3 = 15개예요.","잘린 모서리는 15 − 6 = 9개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L04_challenge#10','math',6,1,'u2','L04','g6_1_math_u2_L04_challenge','lesson_challenge','M6-1-u2-C3',4,'essay','teacher','어떤 각기둥의 전개도에 옆면이 7개 그려져 있어요. 이 각기둥의 이름을 쓰고, 전개도에 그려진 면의 수와 각기둥의 모서리의 수를 구하는 과정을 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C3","difficulty":4,"kind":"essay","stem":"어떤 각기둥의 전개도에 옆면이 7개 그려져 있어요. 이 각기둥의 이름을 쓰고, 전개도에 그려진 면의 수와 각기둥의 모서리의 수를 구하는 과정을 설명해 보세요.","answer_guide":{"answer":"예: 옆면의 수는 한 밑면의 변의 수와 같으므로 밑면은 칠각형이고 이름은 칠각기둥이다. 전개도에는 밑면 2개와 옆면 7개가 있어 면은 7 + 2 = 9개이다. 모서리는 위 밑면 7개, 아래 밑면 7개, 옆 모서리 7개로 7 × 3 = 21개이다.","scoring_points":["옆면의 수 = 밑면의 변의 수로 칠각기둥을 찾았는가","면 9개를 구했는가","모서리 21개를 구했는가"]},"explanation":["옆면 7개 — 밑면은 칠각형이에요.","면은 7 + 2 = 9개예요.","모서리는 7 × 3 = 21개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#1','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',1,'sa','auto','높이가 7 cm인 사각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C4","difficulty":1,"kind":"sa","stem":"높이가 7 cm인 사각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["7"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 7 cm로 그려요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"높이가 9 cm인 삼각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["9"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 9 cm로 그려요."]},{"stem":"높이가 6 cm인 오각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["6"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 6 cm로 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#2','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',1,'mc','auto','오각기둥의 전개도를 그릴 때 그려야 할 밑면과 옆면의 수로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X08']::text[],true,'{"seq":2,"concept":"M6-1-u2-C4","difficulty":1,"kind":"mc","stem":"오각기둥의 전개도를 그릴 때 그려야 할 밑면과 옆면의 수로 알맞은 것은 어느 것인가요?","options":[{"t":"밑면 2개, 옆면 5개","correct":true},{"t":"밑면 1개, 옆면 5개","mis":"M6-1-u2-X08"},{"t":"밑면 2개, 옆면 4개","mis":"M6-1-u2-X08"},{"t":"밑면 5개, 옆면 2개","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 2개예요.","옆면은 한 밑면의 변의 수만큼 — 5개예요.","그래서 「밑면 2개, 옆면 5개」를 그려요."],"variant_rule":{"alt":[{"stem":"육각기둥의 전개도를 그릴 때 그려야 할 밑면과 옆면의 수로 알맞은 것은 어느 것인가요?","options":[{"t":"밑면 2개, 옆면 6개","correct":true},{"t":"밑면 1개, 옆면 6개","mis":"M6-1-u2-X08"},{"t":"밑면 2개, 옆면 5개","mis":"M6-1-u2-X08"},{"t":"밑면 6개, 옆면 2개","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 2개예요.","옆면은 한 밑면의 변의 수만큼 — 6개예요.","그래서 「밑면 2개, 옆면 6개」를 그려요."]},{"stem":"사각기둥의 전개도를 그릴 때 그려야 할 밑면과 옆면의 수로 알맞은 것은 어느 것인가요?","options":[{"t":"밑면 2개, 옆면 4개","correct":true},{"t":"밑면 1개, 옆면 4개","mis":"M6-1-u2-X08"},{"t":"밑면 2개, 옆면 3개","mis":"M6-1-u2-X08"},{"t":"밑면 4개, 옆면 2개","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 밑면은 서로 평행하고 합동인 2개예요.","옆면은 한 밑면의 변의 수만큼 — 4개예요.","그래서 「밑면 2개, 옆면 4개」를 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#3','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',1,'ox','auto','전개도를 그릴 때 접히는 부분은 점선으로 그려요.',ARRAY['M6-1-u2-X07']::text[],true,'{"seq":3,"concept":"M6-1-u2-C4","difficulty":1,"kind":"ox","stem":"전개도를 그릴 때 접히는 부분은 점선으로 그려요.","answer":"O","reason_options":[{"t":"점선은 잘리지 않고 접히는 모서리를 나타내기 때문에","correct":true},{"t":"점선이 실선보다 그리기 쉽기 때문에","mis":"M6-1-u2-X07"}],"mis":"M6-1-u2-X07","explanation":["전개도는 밑면 2개와 변의 수만큼의 옆면을 그려요.","옆면의 가로는 밑면의 변, 세로는 높이와 같아요.","자르는 모서리를 바꾸면 모양이 다른 전개도가 여럿 나와요."],"variant_rule":{"alt":[{"stem":"전개도에서 두 밑면은 서로 합동으로 그려야 해요.","answer":"O","reason_options":[{"t":"각기둥의 두 밑면은 서로 합동이기 때문에","correct":true},{"t":"밑면은 크게 그릴수록 좋기 때문에","mis":"M6-1-u2-X02"}],"explanation":["전개도는 밑면 2개와 변의 수만큼의 옆면을 그려요.","옆면의 가로는 밑면의 변, 세로는 높이와 같아요.","자르는 모서리를 바꾸면 모양이 다른 전개도가 여럿 나와요."]},{"stem":"오각기둥의 전개도에는 옆면을 4개 그려요.","answer":"X","reason_options":[{"t":"옆면은 한 밑면의 변의 수만큼, 5개를 그려야 하기 때문에","correct":true},{"t":"옆면은 언제나 4개이기 때문에","mis":"M6-1-u2-X08"}],"explanation":["전개도는 밑면 2개와 변의 수만큼의 옆면을 그려요.","옆면의 가로는 밑면의 변, 세로는 높이와 같아요.","자르는 모서리를 바꾸면 모양이 다른 전개도가 여럿 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#4','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',1,'sa','auto','밑면이 한 변이 3 cm인 정삼각형이고 높이가 5 cm인 삼각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C4","difficulty":1,"kind":"sa","stem":"밑면이 한 변이 3 cm인 정삼각형이고 높이가 5 cm인 삼각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["옆면 하나의 가로는 밑면의 한 변 3 cm와 같아요.","옆면은 3개라 가로는 3 cm가 3번이에요.","3 × 3 = 9 — 가로는 9 cm예요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면이 한 변이 2 cm인 정사각형이고 높이가 7 cm인 사각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["옆면 하나의 가로는 밑면의 한 변 2 cm와 같아요.","옆면은 4개라 가로는 2 cm가 4번이에요.","2 × 4 = 8 — 가로는 8 cm예요."]},{"stem":"밑면이 한 변이 3 cm인 정오각형이고 높이가 4 cm인 오각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["옆면 하나의 가로는 밑면의 한 변 3 cm와 같아요.","옆면은 5개라 가로는 3 cm가 5번이에요.","3 × 5 = 15 — 가로는 15 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#5','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',2,'sa','auto','밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 6 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C4","difficulty":2,"kind":"sa","stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 6 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","3 + 4 + 5 = 12 — 가로는 12 cm예요(높이 6 cm는 세로예요)."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면의 변이 5 cm, 12 cm, 13 cm인 삼각기둥의 높이가 8 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","5 + 12 + 13 = 30 — 가로는 30 cm예요(높이 8 cm는 세로예요)."]},{"stem":"밑면의 변이 6 cm, 8 cm, 10 cm인 삼각기둥의 높이가 4 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","6 + 8 + 10 = 24 — 가로는 24 cm예요(높이 4 cm는 세로예요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#6','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',2,'mc','auto','밑면이 한 변이 4 cm인 정사각형이고 높이가 9 cm인 사각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":6,"concept":"M6-1-u2-C4","difficulty":2,"kind":"mc","stem":"밑면이 한 변이 4 cm인 정사각형이고 높이가 9 cm인 사각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 4 cm, 세로 9 cm","correct":true},{"t":"가로 9 cm, 세로 16 cm","mis":"M6-1-u2-X09"},{"t":"가로 16 cm, 세로 9 cm","mis":"M6-1-u2-X09"},{"t":"가로 4 cm, 세로 4 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 4 cm예요.","옆면의 세로는 각기둥의 높이와 같아 9 cm예요.","그래서 옆면 하나는 「가로 4 cm, 세로 9 cm」예요."],"variant_rule":{"alt":[{"stem":"밑면이 한 변이 3 cm인 정삼각형이고 높이가 8 cm인 삼각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 3 cm, 세로 8 cm","correct":true},{"t":"가로 8 cm, 세로 9 cm","mis":"M6-1-u2-X09"},{"t":"가로 9 cm, 세로 8 cm","mis":"M6-1-u2-X09"},{"t":"가로 3 cm, 세로 3 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 3 cm예요.","옆면의 세로는 각기둥의 높이와 같아 8 cm예요.","그래서 옆면 하나는 「가로 3 cm, 세로 8 cm」예요."]},{"stem":"밑면이 한 변이 5 cm인 정육각형이고 높이가 7 cm인 육각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 5 cm, 세로 7 cm","correct":true},{"t":"가로 7 cm, 세로 30 cm","mis":"M6-1-u2-X09"},{"t":"가로 30 cm, 세로 7 cm","mis":"M6-1-u2-X09"},{"t":"가로 5 cm, 세로 5 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 5 cm예요.","옆면의 세로는 각기둥의 높이와 같아 7 cm예요.","그래서 옆면 하나는 「가로 5 cm, 세로 7 cm」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#7','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',2,'mc','auto','같은 사각기둥인데 전개도의 모양이 서로 다르게 나오는 까닭은 무엇인가요?',ARRAY['M6-1-u2-X13','M6-1-u2-X08']::text[],true,'{"seq":7,"concept":"M6-1-u2-C4","difficulty":2,"kind":"mc","stem":"같은 사각기둥인데 전개도의 모양이 서로 다르게 나오는 까닭은 무엇인가요?","options":[{"t":"자르는 모서리가 달라져서","correct":true},{"t":"밑면의 크기가 달라져서","mis":"M6-1-u2-X13"},{"t":"높이가 달라져서","mis":"M6-1-u2-X13"},{"t":"옆면의 수가 달라져서","mis":"M6-1-u2-X08"}],"explanation":["전개도는 각기둥의 모서리를 잘라서 펼친 그림이에요.","어느 모서리를 자르느냐가 달라지면 펼쳐진 모양도 달라져요.","자른 자리가 다를 뿐 접으면 같은 각기둥이에요."],"variant_rule":{"alt":[{"stem":"선물 상자 전개도를 친구와 다르게 그렸는데 둘 다 접으니 같은 삼각기둥이 되었어요. 왜 그럴까요?","options":[{"t":"자른 모서리의 자리만 다르고 면의 모양과 수는 같아서","correct":true},{"t":"우연히 맞은 것이라서","mis":"M6-1-u2-X13"},{"t":"삼각기둥은 전개도가 하나뿐이라서","mis":"M6-1-u2-X13"},{"t":"높이를 서로 다르게 그려서","mis":"M6-1-u2-X09"}],"explanation":["전개도는 각기둥의 모서리를 잘라서 펼친 그림이에요.","어느 모서리를 자르느냐가 달라지면 펼쳐진 모양도 달라져요.","자른 자리가 다를 뿐 접으면 같은 각기둥이에요."]},{"stem":"한 각기둥의 전개도에 대한 설명으로 옳은 것은 어느 것인가요?","options":[{"t":"자르는 모서리에 따라 여러 가지가 나올 수 있어요","correct":true},{"t":"한 가지만 나와요","mis":"M6-1-u2-X13"},{"t":"밑면을 옆면 위에만 붙여야 해요","mis":"M6-1-u2-X13"},{"t":"옆면의 수에 따라 하나로 정해져요","mis":"M6-1-u2-X13"}],"explanation":["전개도는 각기둥의 모서리를 잘라서 펼친 그림이에요.","어느 모서리를 자르느냐가 달라지면 펼쳐진 모양도 달라져요.","자른 자리가 다를 뿐 접으면 같은 각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#8','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',2,'mc','auto','전개도를 접었더니 옆면 한 곳에 틈이 생겼어요. 무엇이 잘못되었을까요?',ARRAY['M6-1-u2-X14','M6-1-u2-X07','M6-1-u2-X13']::text[],true,'{"seq":8,"concept":"M6-1-u2-C4","difficulty":2,"kind":"mc","stem":"전개도를 접었더니 옆면 한 곳에 틈이 생겼어요. 무엇이 잘못되었을까요?","options":[{"t":"맞닿는 두 선분의 길이가 서로 달라요","correct":true},{"t":"밑면을 색칠하지 않았어요","mis":"M6-1-u2-X14"},{"t":"점선을 너무 많이 그렸어요","mis":"M6-1-u2-X07"},{"t":"옆면을 가로로 이어 그렸어요","mis":"M6-1-u2-X13"}],"explanation":["옆면의 가로는 밑면의 변의 길이, 세로는 높이와 같아야 해요.","접으면 맞닿는 두 선분의 길이도 같아야 해요.","그래서 「맞닿는 두 선분의 길이가 서로 달라요」가 잘못이에요."],"variant_rule":{"alt":[{"stem":"전개도를 접었더니 밑면이 옆면보다 커서 삐져나왔어요. 무엇이 잘못되었을까요?","options":[{"t":"밑면의 변의 길이와 옆면의 가로가 서로 달라요","correct":true},{"t":"밑면을 2개 그렸어요","mis":"M6-1-u2-X08"},{"t":"점선으로 접었어요","mis":"M6-1-u2-X07"},{"t":"옆면이 직사각형이에요","mis":"M6-1-u2-X03"}],"explanation":["옆면의 가로는 밑면의 변의 길이, 세로는 높이와 같아야 해요.","접으면 맞닿는 두 선분의 길이도 같아야 해요.","그래서 「밑면의 변의 길이와 옆면의 가로가 서로 달라요」가 잘못이에요."]},{"stem":"전개도를 접었더니 옆면의 위쪽이 밑면에 닿지 않았어요. 무엇이 잘못되었을까요?","options":[{"t":"옆면의 세로가 각기둥의 높이와 달라요","correct":true},{"t":"밑면이 2개예요","mis":"M6-1-u2-X08"},{"t":"옆면을 이어 그렸어요","mis":"M6-1-u2-X13"},{"t":"실선으로 잘랐어요","mis":"M6-1-u2-X07"}],"explanation":["옆면의 가로는 밑면의 변의 길이, 세로는 높이와 같아야 해요.","접으면 맞닿는 두 선분의 길이도 같아야 해요.","그래서 「옆면의 세로가 각기둥의 높이와 달라요」가 잘못이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#9','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',2,'sa','auto','밑면이 한 변이 4 cm인 정육각형이고 높이가 9 cm인 육각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C4","difficulty":2,"kind":"sa","stem":"밑면이 한 변이 4 cm인 정육각형이고 높이가 9 cm인 육각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 하나의 가로는 밑면의 한 변 4 cm와 같아요.","옆면은 6개라 가로는 4 cm가 6번이에요.","4 × 6 = 24 — 가로는 24 cm예요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면이 한 변이 3 cm인 정팔각형이고 높이가 5 cm인 팔각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 하나의 가로는 밑면의 한 변 3 cm와 같아요.","옆면은 8개라 가로는 3 cm가 8번이에요.","3 × 8 = 24 — 가로는 24 cm예요."]},{"stem":"밑면이 한 변이 2 cm인 정칠각형이고 높이가 6 cm인 칠각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["옆면 하나의 가로는 밑면의 한 변 2 cm와 같아요.","옆면은 7개라 가로는 2 cm가 7번이에요.","2 × 7 = 14 — 가로는 14 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_basic#10','math',6,1,'u2','L05','g6_1_math_u2_L05_basic','lesson_basic','M6-1-u2-C4',3,'match','auto','밑면이 한 변이 3 cm인 정사각형이고 높이가 8 cm인 사각기둥의 전개도예요. 알맞은 길이끼리 이으세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u2-C4","difficulty":3,"kind":"match","stem":"밑면이 한 변이 3 cm인 정사각형이고 높이가 8 cm인 사각기둥의 전개도예요. 알맞은 길이끼리 이으세요.","pairs":[{"l":"옆면의 세로","r":"8 cm"},{"l":"옆면 하나의 가로","r":"3 cm"},{"l":"옆면을 이은 직사각형의 가로","r":"12 cm"}],"mis":"M6-1-u2-X09","explanation":["옆면의 세로는 높이 8 cm예요.","옆면 하나의 가로는 밑면의 한 변 3 cm예요.","이은 직사각형의 가로는 3 × 4 = 12 cm예요."],"variant_rule":{"alt":[{"stem":"밑면이 한 변이 4 cm인 정오각형이고 높이가 6 cm인 오각기둥의 전개도예요. 알맞은 길이끼리 이으세요.","pairs":[{"l":"옆면의 세로","r":"6 cm"},{"l":"옆면 하나의 가로","r":"4 cm"},{"l":"옆면을 이은 직사각형의 가로","r":"20 cm"}],"explanation":["옆면의 세로는 높이 6 cm예요.","옆면 하나의 가로는 밑면의 한 변 4 cm예요.","이은 직사각형의 가로는 4 × 5 = 20 cm예요."]},{"stem":"밑면이 한 변이 2 cm인 정육각형이고 높이가 9 cm인 육각기둥의 전개도예요. 알맞은 길이끼리 이으세요.","pairs":[{"l":"옆면의 세로","r":"9 cm"},{"l":"옆면 하나의 가로","r":"2 cm"},{"l":"옆면을 이은 직사각형의 가로","r":"12 cm"}],"explanation":["옆면의 세로는 높이 9 cm예요.","옆면 하나의 가로는 밑면의 한 변 2 cm예요.","이은 직사각형의 가로는 2 × 6 = 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#1','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',2,'sa','auto','밑면의 변이 4 cm, 4 cm, 5 cm, 7 cm인 사각기둥의 높이가 9 cm예요. 전개도에서 옆면 4개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C4","difficulty":2,"kind":"sa","stem":"밑면의 변이 4 cm, 4 cm, 5 cm, 7 cm인 사각기둥의 높이가 9 cm예요. 전개도에서 옆면 4개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","4 + 4 + 5 + 7 = 20 — 가로는 20 cm예요(높이 9 cm는 세로예요)."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면의 변이 2 cm, 3 cm, 4 cm, 5 cm, 6 cm인 오각기둥의 높이가 7 cm예요. 전개도에서 옆면 5개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","2 + 3 + 4 + 5 + 6 = 20 — 가로는 20 cm예요(높이 7 cm는 세로예요)."]},{"stem":"밑면의 변이 7 cm, 24 cm, 25 cm인 삼각기둥의 높이가 3 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","7 + 24 + 25 = 56 — 가로는 56 cm예요(높이 3 cm는 세로예요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#2','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',2,'ox','auto','각기둥의 전개도에서 옆면의 가로는 각기둥의 높이와 같아요.',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":2,"concept":"M6-1-u2-C4","difficulty":2,"kind":"ox","stem":"각기둥의 전개도에서 옆면의 가로는 각기둥의 높이와 같아요.","answer":"X","reason_options":[{"t":"옆면의 가로는 밑면의 변의 길이, 세로가 높이와 같기 때문에","correct":true},{"t":"옆면은 가로와 세로가 같기 때문에","mis":"M6-1-u2-X09"}],"mis":"M6-1-u2-X09","explanation":["전개도는 밑면 2개와 변의 수만큼의 옆면을 그려요.","옆면의 가로는 밑면의 변, 세로는 높이와 같아요.","자르는 모서리를 바꾸면 모양이 다른 전개도가 여럿 나와요."],"variant_rule":{"alt":[{"stem":"한 각기둥의 전개도는 한 가지뿐이에요.","answer":"X","reason_options":[{"t":"자르는 모서리에 따라 모양이 다른 전개도가 여럿 나오기 때문에","correct":true},{"t":"각기둥은 모양이 하나이기 때문에","mis":"M6-1-u2-X13"}],"explanation":["전개도는 밑면 2개와 변의 수만큼의 옆면을 그려요.","옆면의 가로는 밑면의 변, 세로는 높이와 같아요.","자르는 모서리를 바꾸면 모양이 다른 전개도가 여럿 나와요."]},{"stem":"옆면을 이어 붙인 직사각형의 가로는 밑면의 둘레와 같아요.","answer":"O","reason_options":[{"t":"옆면 하나의 가로가 밑면의 변 하나와 같아 모두 더하면 둘레이기 때문에","correct":true},{"t":"가로는 언제나 높이의 2배이기 때문에","mis":"M6-1-u2-X09"}],"explanation":["전개도는 밑면 2개와 변의 수만큼의 옆면을 그려요.","옆면의 가로는 밑면의 변, 세로는 높이와 같아요.","자르는 모서리를 바꾸면 모양이 다른 전개도가 여럿 나와요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#3','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',3,'error','auto','밑면의 한 변이 4 cm인 정삼각형이고 높이가 9 cm인 삼각기둥의 전개도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X09','M6-1-u2-X14']::text[],true,'{"seq":3,"concept":"M6-1-u2-C4","difficulty":3,"kind":"error","stem":"밑면의 한 변이 4 cm인 정삼각형이고 높이가 9 cm인 삼각기둥의 전개도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「옆면 하나는 가로 9 cm, 세로 4 cm야.」","correct":true,"mis_target":"M6-1-u2-X09"},{"t":"이현 — 「옆면 셋을 이은 직사각형의 가로는 12 cm야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「삼각형 밑면을 2개 그려야 해.」","mis":"M6-1-u2-X14"}],"explanation":["옆면의 가로는 밑면의 변 4 cm, 세로는 높이 9 cm예요.","옆면 셋을 이으면 가로는 4 × 3 = 12 cm예요.","준희는 가로와 세로를 바꾸어 말했어요."],"variant_rule":{"alt":[{"stem":"밑면의 한 변이 5 cm인 정삼각형이고 높이가 8 cm인 삼각기둥의 전개도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「옆면 하나는 가로 8 cm, 세로 5 cm야.」","correct":true,"mis_target":"M6-1-u2-X09"},{"t":"수아 — 「옆면 셋을 이은 직사각형의 가로는 15 cm야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「삼각형 밑면을 2개 그려야 해.」","mis":"M6-1-u2-X14"}],"explanation":["옆면의 가로는 밑면의 변 5 cm, 세로는 높이 8 cm예요.","옆면 셋을 이으면 가로는 5 × 3 = 15 cm예요.","서호는 가로와 세로를 바꾸어 말했어요."]},{"stem":"밑면의 한 변이 3 cm인 정삼각형이고 높이가 7 cm인 삼각기둥의 전개도를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「옆면 하나는 가로 7 cm, 세로 3 cm야.」","correct":true,"mis_target":"M6-1-u2-X09"},{"t":"나린 — 「옆면 셋을 이은 직사각형의 가로는 9 cm야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「삼각형 밑면을 2개 그려야 해.」","mis":"M6-1-u2-X14"}],"explanation":["옆면의 가로는 밑면의 변 3 cm, 세로는 높이 7 cm예요.","옆면 셋을 이으면 가로는 3 × 3 = 9 cm예요.","가온은 가로와 세로를 바꾸어 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#4','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',3,'mc','auto','밑면이 한 변이 6 cm인 정오각형이고 높이가 10 cm인 오각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":4,"concept":"M6-1-u2-C4","difficulty":3,"kind":"mc","stem":"밑면이 한 변이 6 cm인 정오각형이고 높이가 10 cm인 오각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 6 cm, 세로 10 cm","correct":true},{"t":"가로 10 cm, 세로 30 cm","mis":"M6-1-u2-X09"},{"t":"가로 30 cm, 세로 10 cm","mis":"M6-1-u2-X09"},{"t":"가로 6 cm, 세로 6 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 6 cm예요.","옆면의 세로는 각기둥의 높이와 같아 10 cm예요.","그래서 옆면 하나는 「가로 6 cm, 세로 10 cm」예요."],"variant_rule":{"alt":[{"stem":"밑면이 한 변이 2 cm인 정팔각형이고 높이가 11 cm인 팔각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 2 cm, 세로 11 cm","correct":true},{"t":"가로 11 cm, 세로 16 cm","mis":"M6-1-u2-X09"},{"t":"가로 16 cm, 세로 11 cm","mis":"M6-1-u2-X09"},{"t":"가로 2 cm, 세로 2 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 2 cm예요.","옆면의 세로는 각기둥의 높이와 같아 11 cm예요.","그래서 옆면 하나는 「가로 2 cm, 세로 11 cm」예요."]},{"stem":"밑면이 한 변이 7 cm인 정삼각형이고 높이가 4 cm인 삼각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 7 cm, 세로 4 cm","correct":true},{"t":"가로 4 cm, 세로 21 cm","mis":"M6-1-u2-X09"},{"t":"가로 21 cm, 세로 4 cm","mis":"M6-1-u2-X09"},{"t":"가로 7 cm, 세로 7 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 7 cm예요.","옆면의 세로는 각기둥의 높이와 같아 4 cm예요.","그래서 옆면 하나는 「가로 7 cm, 세로 4 cm」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#5','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',3,'mc','auto','전개도를 접었더니 밑면이 옆면보다 커서 삐져나왔어요. 무엇이 잘못되었을까요?',ARRAY['M6-1-u2-X08','M6-1-u2-X07','M6-1-u2-X03']::text[],true,'{"seq":5,"concept":"M6-1-u2-C4","difficulty":3,"kind":"mc","stem":"전개도를 접었더니 밑면이 옆면보다 커서 삐져나왔어요. 무엇이 잘못되었을까요?","options":[{"t":"밑면의 변의 길이와 옆면의 가로가 서로 달라요","correct":true},{"t":"밑면을 2개 그렸어요","mis":"M6-1-u2-X08"},{"t":"점선으로 접었어요","mis":"M6-1-u2-X07"},{"t":"옆면이 직사각형이에요","mis":"M6-1-u2-X03"}],"explanation":["옆면의 가로는 밑면의 변의 길이, 세로는 높이와 같아야 해요.","접으면 맞닿는 두 선분의 길이도 같아야 해요.","그래서 「밑면의 변의 길이와 옆면의 가로가 서로 달라요」가 잘못이에요."],"variant_rule":{"alt":[{"stem":"전개도를 접었더니 옆면의 위쪽이 밑면에 닿지 않았어요. 무엇이 잘못되었을까요?","options":[{"t":"옆면의 세로가 각기둥의 높이와 달라요","correct":true},{"t":"밑면이 2개예요","mis":"M6-1-u2-X08"},{"t":"옆면을 이어 그렸어요","mis":"M6-1-u2-X13"},{"t":"실선으로 잘랐어요","mis":"M6-1-u2-X07"}],"explanation":["옆면의 가로는 밑면의 변의 길이, 세로는 높이와 같아야 해요.","접으면 맞닿는 두 선분의 길이도 같아야 해요.","그래서 「옆면의 세로가 각기둥의 높이와 달라요」가 잘못이에요."]},{"stem":"전개도를 접었더니 옆면 한 곳에 틈이 생겼어요. 무엇이 잘못되었을까요?","options":[{"t":"맞닿는 두 선분의 길이가 서로 달라요","correct":true},{"t":"밑면을 색칠하지 않았어요","mis":"M6-1-u2-X14"},{"t":"점선을 너무 많이 그렸어요","mis":"M6-1-u2-X07"},{"t":"옆면을 가로로 이어 그렸어요","mis":"M6-1-u2-X13"}],"explanation":["옆면의 가로는 밑면의 변의 길이, 세로는 높이와 같아야 해요.","접으면 맞닿는 두 선분의 길이도 같아야 해요.","그래서 「맞닿는 두 선분의 길이가 서로 달라요」가 잘못이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#6','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',3,'match','auto','밑면이 한 변이 7 cm인 정삼각형이고 높이가 4 cm인 삼각기둥의 전개도예요. 알맞은 길이끼리 이으세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C4","difficulty":3,"kind":"match","stem":"밑면이 한 변이 7 cm인 정삼각형이고 높이가 4 cm인 삼각기둥의 전개도예요. 알맞은 길이끼리 이으세요.","pairs":[{"l":"옆면의 세로","r":"4 cm"},{"l":"옆면 하나의 가로","r":"7 cm"},{"l":"옆면을 이은 직사각형의 가로","r":"21 cm"}],"mis":"M6-1-u2-X09","explanation":["옆면의 세로는 높이 4 cm예요.","옆면 하나의 가로는 밑면의 한 변 7 cm예요.","이은 직사각형의 가로는 7 × 3 = 21 cm예요."],"variant_rule":{"alt":[{"stem":"밑면이 한 변이 2 cm인 정팔각형이고 높이가 5 cm인 팔각기둥의 전개도예요. 알맞은 길이끼리 이으세요.","pairs":[{"l":"옆면의 세로","r":"5 cm"},{"l":"옆면 하나의 가로","r":"2 cm"},{"l":"옆면을 이은 직사각형의 가로","r":"16 cm"}],"explanation":["옆면의 세로는 높이 5 cm예요.","옆면 하나의 가로는 밑면의 한 변 2 cm예요.","이은 직사각형의 가로는 2 × 8 = 16 cm예요."]},{"stem":"밑면이 한 변이 6 cm인 정사각형이고 높이가 9 cm인 사각기둥의 전개도예요. 알맞은 길이끼리 이으세요.","pairs":[{"l":"옆면의 세로","r":"9 cm"},{"l":"옆면 하나의 가로","r":"6 cm"},{"l":"옆면을 이은 직사각형의 가로","r":"24 cm"}],"explanation":["옆면의 세로는 높이 9 cm예요.","옆면 하나의 가로는 밑면의 한 변 6 cm예요.","이은 직사각형의 가로는 6 × 4 = 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#7','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',3,'sa','auto','밑면이 한 변이 5 cm인 정구각형이고 높이가 4 cm인 구각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u2-C4","difficulty":3,"kind":"sa","stem":"밑면이 한 변이 5 cm인 정구각형이고 높이가 4 cm인 구각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["옆면 하나의 가로는 밑면의 한 변 5 cm와 같아요.","옆면은 9개라 가로는 5 cm가 9번이에요.","5 × 9 = 45 — 가로는 45 cm예요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면이 한 변이 3 cm인 정십이각형이고 높이가 6 cm인 십이각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["옆면 하나의 가로는 밑면의 한 변 3 cm와 같아요.","옆면은 12개라 가로는 3 cm가 12번이에요.","3 × 12 = 36 — 가로는 36 cm예요."]},{"stem":"밑면이 한 변이 4 cm인 정십각형이고 높이가 7 cm인 십각기둥이 있어요. 전개도에서 옆면을 모두 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["옆면 하나의 가로는 밑면의 한 변 4 cm와 같아요.","옆면은 10개라 가로는 4 cm가 10번이에요.","4 × 10 = 40 — 가로는 40 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#8','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',4,'sa','auto','밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 6 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C4","difficulty":4,"kind":"sa","stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 6 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 3 + 4 + 5 = 12 cm예요.","세로는 높이 6 cm예요.","넓이는 12 × 6 = 72 cm²예요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면의 변이 2 cm, 3 cm, 4 cm인 삼각기둥의 높이가 9 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["81"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 2 + 3 + 4 = 9 cm예요.","세로는 높이 9 cm예요.","넓이는 9 × 9 = 81 cm²예요."]},{"stem":"밑면의 변이 5 cm, 5 cm, 6 cm인 삼각기둥의 높이가 4 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["64"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 5 + 5 + 6 = 16 cm예요.","세로는 높이 4 cm예요.","넓이는 16 × 4 = 64 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#9','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',4,'sa','auto','밑면의 변이 2 cm, 2 cm, 3 cm, 3 cm인 사각기둥의 높이가 8 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C4","difficulty":4,"kind":"sa","stem":"밑면의 변이 2 cm, 2 cm, 3 cm, 3 cm인 사각기둥의 높이가 8 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["80"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 2 + 2 + 3 + 3 = 10 cm예요.","세로는 높이 8 cm예요.","넓이는 10 × 8 = 80 cm²예요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면의 변이 3 cm, 3 cm, 3 cm, 3 cm, 3 cm인 오각기둥의 높이가 6 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["90"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 3 + 3 + 3 + 3 + 3 = 15 cm예요.","세로는 높이 6 cm예요.","넓이는 15 × 6 = 90 cm²예요."]},{"stem":"밑면의 변이 6 cm, 8 cm, 10 cm인 삼각기둥의 높이가 3 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["72"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 6 + 8 + 10 = 24 cm예요.","세로는 높이 3 cm예요.","넓이는 24 × 3 = 72 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L05_challenge#10','math',6,1,'u2','L05','g6_1_math_u2_L05_challenge','lesson_challenge','M6-1-u2-C4',4,'essay','teacher','밑면의 세 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 6 cm예요. 전개도를 그리는 순서를 쓰고, 옆면 3개를 이어 붙인 직사각형의 가로와 세로를 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C4","difficulty":4,"kind":"essay","stem":"밑면의 세 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 6 cm예요. 전개도를 그리는 순서를 쓰고, 옆면 3개를 이어 붙인 직사각형의 가로와 세로를 구해 보세요.","answer_guide":{"answer":"예: 먼저 옆면 3개를 옆으로 나란히 이어 그린다. 옆면의 가로는 밑면의 변의 길이 3 cm, 4 cm, 5 cm이고 세로는 높이 6 cm이다. 그다음 이어 붙인 옆면의 위와 아래에 합동인 삼각형 밑면을 하나씩 붙인다. 이어 붙인 직사각형의 가로는 3 + 4 + 5 = 12 cm, 세로는 6 cm이다.","scoring_points":["옆면을 먼저 잇고 밑면 2개를 붙이는 순서를 썼는가","가로 12 cm(밑면의 둘레)를 구했는가","세로 6 cm(높이)를 구했는가"]},"explanation":["옆면 셋을 이어 그린 뒤 밑면 2개를 붙여요.","가로는 3 + 4 + 5 = 12 cm예요.","세로는 높이 6 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#1','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',1,'mc','auto','한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형을 무엇이라고 하나요?',ARRAY['M6-1-u2-X01','M6-1-u2-X11']::text[],true,'{"seq":1,"concept":"M6-1-u2-C5","difficulty":1,"kind":"mc","stem":"한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형을 무엇이라고 하나요?","options":[{"t":"각뿔","correct":true},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각기둥","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면이 밑면, 밑면과 만나는 삼각형이 옆면이에요.","그래서 답은 「각뿔」이에요."],"variant_rule":{"alt":[{"stem":"각뿔에서 다각형인 면을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"각뿔","mis":"M6-1-u2-X11"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각기둥","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면이 밑면, 밑면과 만나는 삼각형이 옆면이에요.","그래서 답은 「밑면」이에요."]},{"stem":"각뿔에서 밑면과 만나는 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"각뿔","mis":"M6-1-u2-X11"},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"각기둥","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면이 밑면, 밑면과 만나는 삼각형이 옆면이에요.","그래서 답은 「옆면」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#2','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',1,'sa','auto','각뿔의 밑면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C5","difficulty":1,"kind":"sa","stem":"각뿔의 밑면은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","다각형인 면은 하나 — 1개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"밑면이 육각형인 각뿔의 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면의 변 하나마다 삼각형 옆면이 하나 — 6개예요."]},{"stem":"밑면이 사각형인 각뿔의 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면의 변 하나마다 삼각형 옆면이 하나 — 4개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#3','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',1,'mc','auto','각뿔의 옆면은 모두 어떤 도형인가요?',ARRAY['M6-1-u2-X03']::text[],true,'{"seq":3,"concept":"M6-1-u2-C5","difficulty":1,"kind":"mc","stem":"각뿔의 옆면은 모두 어떤 도형인가요?","options":[{"t":"삼각형","correct":true},{"t":"직사각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X03"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."],"variant_rule":{"alt":[{"stem":"각뿔의 옆면은 모두 어디에서 만나나요?","options":[{"t":"한 점에서 모두 만나요","correct":true},{"t":"만나지 않아요","mis":"M6-1-u2-X11"},{"t":"밑면과 수직으로 만나요","mis":"M6-1-u2-X11"},{"t":"위쪽 밑면에서 만나요","mis":"M6-1-u2-X10"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."]},{"stem":"각뿔에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"밑면은 1개이고 옆면은 모두 삼각형이에요","correct":true},{"t":"밑면이 옆면과 모두 수직으로 만나요","mis":"M6-1-u2-X11"},{"t":"옆면은 모두 직사각형이에요","mis":"M6-1-u2-X03"},{"t":"밑면은 2개예요","mis":"M6-1-u2-X10"}],"explanation":["각기둥은 밑면이 2개, 옆면이 직사각형이고 밑면과 수직으로 만나요.","각뿔은 밑면이 1개, 옆면이 삼각형이고 한 점에서 모두 만나요.","같은 말을 옮겨 쓰면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#4','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',1,'mc','auto','다음 가운데 각뿔 모양인 것은 어느 것인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X02']::text[],true,'{"seq":4,"concept":"M6-1-u2-C5","difficulty":1,"kind":"mc","stem":"다음 가운데 각뿔 모양인 것은 어느 것인가요?","options":[{"t":"한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통","correct":true},{"t":"서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통","mis":"M6-1-u2-X11"},{"t":"위아래 면이 서로 평행하고 합동인 원인 저금통","mis":"M6-1-u2-X02"},{"t":"한 원과 뾰족한 점이 있는 고깔","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","보기를 하나씩 이 뜻에 대어 봐요 — 크기가 다르거나 굽은 면이 있으면 안 돼요.","「한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통」이 각뿔이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 다음 가운데 각뿔 모양인 것은 어느 것인가요?","options":[{"t":"한 면이 오각형이고 나머지 면이 모두 삼각형인 탑 지붕","correct":true},{"t":"서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자","mis":"M6-1-u2-X11"},{"t":"굽은 면 하나로만 둘러싸인 공 모양 저금통","mis":"M6-1-u2-X02"},{"t":"한 원과 뾰족한 점이 있는 고깔","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","보기를 하나씩 이 뜻에 대어 봐요 — 크기가 다르거나 굽은 면이 있으면 안 돼요.","「한 면이 오각형이고 나머지 면이 모두 삼각형인 탑 지붕」이 각뿔이에요."]},{"stem":"이번에는 다른 보기예요. 다음 가운데 각뿔 모양인 것은 어느 것인가요?","options":[{"t":"한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통","correct":true},{"t":"서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필","mis":"M6-1-u2-X11"},{"t":"한 원과 뾰족한 점이 있는 고깔","mis":"M6-1-u2-X11"},{"t":"서로 평행한 두 사각형의 크기가 서로 다른 저금통","mis":"M6-1-u2-X02"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","보기를 하나씩 이 뜻에 대어 봐요 — 크기가 다르거나 굽은 면이 있으면 안 돼요.","「한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통」이 각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#5','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',2,'sa','auto','밑면이 칠각형인 각뿔에서 밑면과 만나는 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C5","difficulty":2,"kind":"sa","stem":"밑면이 칠각형인 각뿔에서 밑면과 만나는 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면의 변 하나마다 삼각형 옆면이 하나 — 7개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"밑면이 오각형인 각뿔의 면은 밑면과 옆면을 합해 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면 1개와 옆면 5개 — 5 + 1 = 6개예요."]},{"stem":"밑면이 팔각형인 각뿔의 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면의 변 하나마다 삼각형 옆면이 하나 — 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#6','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',2,'mc','auto','각기둥과 각뿔을 바르게 견준 것은 어느 것인가요?',ARRAY['M6-1-u2-X03','M6-1-u2-X10','M6-1-u2-X11']::text[],true,'{"seq":6,"concept":"M6-1-u2-C5","difficulty":2,"kind":"mc","stem":"각기둥과 각뿔을 바르게 견준 것은 어느 것인가요?","options":[{"t":"밑면이 각기둥은 2개, 각뿔은 1개예요","correct":true},{"t":"옆면이 각기둥은 삼각형, 각뿔은 직사각형이에요","mis":"M6-1-u2-X03"},{"t":"밑면의 수가 같아요","mis":"M6-1-u2-X10"},{"t":"각뿔의 옆면도 밑면과 수직으로 만나요","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 밑면이 2개, 옆면이 직사각형이고 밑면과 수직으로 만나요.","각뿔은 밑면이 1개, 옆면이 삼각형이고 한 점에서 모두 만나요.","같은 말을 옮겨 쓰면 안 돼요."],"variant_rule":{"alt":[{"stem":"각뿔에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"밑면은 1개이고 옆면은 모두 삼각형이에요","correct":true},{"t":"밑면이 옆면과 모두 수직으로 만나요","mis":"M6-1-u2-X11"},{"t":"옆면은 모두 직사각형이에요","mis":"M6-1-u2-X03"},{"t":"밑면은 2개예요","mis":"M6-1-u2-X10"}],"explanation":["각기둥은 밑면이 2개, 옆면이 직사각형이고 밑면과 수직으로 만나요.","각뿔은 밑면이 1개, 옆면이 삼각형이고 한 점에서 모두 만나요.","같은 말을 옮겨 쓰면 안 돼요."]},{"stem":"각기둥에는 있지만 각뿔에는 없는 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면","correct":true},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"꼭짓점","mis":"M6-1-u2-X05"},{"t":"다각형인 밑면","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 밑면이 2개, 옆면이 직사각형이고 밑면과 수직으로 만나요.","각뿔은 밑면이 1개, 옆면이 삼각형이고 한 점에서 모두 만나요.","같은 말을 옮겨 쓰면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#7','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',2,'ox','auto','각뿔의 옆면은 모두 직사각형이에요.',ARRAY['M6-1-u2-X03']::text[],true,'{"seq":7,"concept":"M6-1-u2-C5","difficulty":2,"kind":"ox","stem":"각뿔의 옆면은 모두 직사각형이에요.","answer":"X","reason_options":[{"t":"옆면은 밑면의 변과 한 점을 이은 삼각형이기 때문에","correct":true},{"t":"각기둥처럼 옆면이 밑면과 수직이기 때문에","mis":"M6-1-u2-X03"}],"mis":"M6-1-u2-X03","explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면 하나가 밑면, 삼각형들이 옆면이에요.","원뿔은 밑면이 원이라 각뿔이 아니에요."],"variant_rule":{"alt":[{"stem":"각뿔의 밑면은 1개예요.","answer":"O","reason_options":[{"t":"다각형인 면은 하나이고 나머지는 모두 삼각형이기 때문에","correct":true},{"t":"위아래에 밑면이 하나씩 있기 때문에","mis":"M6-1-u2-X10"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면 하나가 밑면, 삼각형들이 옆면이에요.","원뿔은 밑면이 원이라 각뿔이 아니에요."]},{"stem":"원뿔도 뾰족하니 각뿔이에요.","answer":"X","reason_options":[{"t":"원뿔은 밑면이 원이라 다각형이 아니기 때문에","correct":true},{"t":"뿔 모양은 모두 각뿔이기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면 하나가 밑면, 삼각형들이 옆면이에요.","원뿔은 밑면이 원이라 각뿔이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#8','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',2,'mc','auto','「밑면이 원이고 뾰족한 점이 있는 고깔」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X11']::text[],true,'{"seq":8,"concept":"M6-1-u2-C5","difficulty":2,"kind":"mc","stem":"「밑면이 원이고 뾰족한 점이 있는 고깔」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 다각형이 아니기 때문에","correct":true},{"t":"옆면이 삼각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「밑면이 원이고 뾰족한 점이 있는 고깔」을 이 조건에 대어 봐요.","밑면이 다각형이 아니기 때문에 각뿔이 아니에요."],"variant_rule":{"alt":[{"stem":"「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 삼각형이 아니기 때문에","correct":true},{"t":"밑면이 다각형이 아니기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」을 이 조건에 대어 봐요.","옆면이 삼각형이 아니기 때문에 각뿔이 아니에요."]},{"stem":"「서로 평행하고 합동인 두 오각형과 직사각형 5개로 된 상자」는 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","correct":true},{"t":"밑면이 다각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"옆면이 삼각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「서로 평행하고 합동인 두 오각형과 직사각형 5개로 된 상자」를 이 조건에 대어 봐요.","다각형인 면이 2개이고 옆면이 직사각형이기 때문에 각뿔이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#9','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',2,'sa','auto','밑면이 육각형인 각뿔의 면은 밑면과 옆면을 합해 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C5","difficulty":2,"kind":"sa","stem":"밑면이 육각형인 각뿔의 면은 밑면과 옆면을 합해 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면 1개와 옆면 6개 — 6 + 1 = 7개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"밑면이 사각형인 각뿔의 면은 밑면과 옆면을 합해 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면 1개와 옆면 4개 — 4 + 1 = 5개예요."]},{"stem":"밑면이 구각형인 각뿔에서 밑면과 만나는 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면의 변 하나마다 삼각형 옆면이 하나 — 9개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_basic#10','math',6,1,'u2','L06','g6_1_math_u2_L06_basic','lesson_basic','M6-1-u2-C5',3,'mc','auto','각뿔의 옆면이 언제나 삼각형인 까닭은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X03','M6-1-u2-X12']::text[],true,'{"seq":10,"concept":"M6-1-u2-C5","difficulty":3,"kind":"mc","stem":"각뿔의 옆면이 언제나 삼각형인 까닭은 무엇인가요?","options":[{"t":"밑면의 변 하나와 위쪽 한 점을 이어 만들어지기 때문에","correct":true},{"t":"밑면이 삼각형이기 때문에","mis":"M6-1-u2-X04"},{"t":"옆면이 직사각형을 반으로 자른 것이기 때문에","mis":"M6-1-u2-X03"},{"t":"각뿔은 면이 3개이기 때문에","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."],"variant_rule":{"alt":[{"stem":"각뿔의 옆면은 모두 어떤 도형인가요?","options":[{"t":"삼각형","correct":true},{"t":"직사각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X03"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."]},{"stem":"각뿔의 옆면은 모두 어디에서 만나나요?","options":[{"t":"한 점에서 모두 만나요","correct":true},{"t":"만나지 않아요","mis":"M6-1-u2-X11"},{"t":"밑면과 수직으로 만나요","mis":"M6-1-u2-X11"},{"t":"위쪽 밑면에서 만나요","mis":"M6-1-u2-X10"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#1','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',2,'match','auto','알맞은 것끼리 이으세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C5","difficulty":2,"kind":"match","stem":"알맞은 것끼리 이으세요.","pairs":[{"l":"각기둥의 옆면","r":"직사각형"},{"l":"각뿔의 옆면","r":"삼각형"},{"l":"각뿔의 밑면","r":"다각형 1개"}],"mis":"M6-1-u2-X03","explanation":["각기둥은 밑면 2개·옆면 직사각형이에요.","각뿔은 밑면 1개·옆면 삼각형이에요.","밑면이 원이면 원기둥·원뿔이에요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"각기둥의 밑면 수","r":"2개"},{"l":"각뿔의 밑면 수","r":"1개"},{"l":"사각뿔의 옆면 수","r":"4개"}],"explanation":["각기둥은 밑면 2개·옆면 직사각형이에요.","각뿔은 밑면 1개·옆면 삼각형이에요.","밑면이 원이면 원기둥·원뿔이에요."]},{"stem":"이번에는 다른 보기예요. 알맞은 것끼리 이으세요.","pairs":[{"l":"밑면이 원인 뿔","r":"원뿔"},{"l":"밑면이 다각형인 뿔","r":"각뿔"},{"l":"밑면이 다각형인 기둥","r":"각기둥"}],"explanation":["각기둥은 밑면 2개·옆면 직사각형이에요.","각뿔은 밑면 1개·옆면 삼각형이에요.","밑면이 원이면 원기둥·원뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#2','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',2,'sa','auto','밑면이 십각형인 각뿔의 면은 밑면과 옆면을 합해 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C5","difficulty":2,"kind":"sa","stem":"밑면이 십각형인 각뿔의 면은 밑면과 옆면을 합해 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"밑면이 구각형인 각뿔의 옆면은 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면의 변 하나마다 삼각형 옆면이 하나 — 9개예요."]},{"stem":"밑면이 십이각형인 각뿔의 면은 밑면과 옆면을 합해 모두 몇 개인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["각뿔의 밑면은 다각형인 면 1개예요.","밑면과 만나는 면이 옆면이고, 밑면의 변 하나마다 하나씩이에요.","밑면 1개와 옆면 12개 — 12 + 1 = 13개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#3','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',3,'error','auto','캠핑장의 뾰족한 텐트(사각뿔 모양)를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X10','M6-1-u2-X14']::text[],true,'{"seq":3,"concept":"M6-1-u2-C5","difficulty":3,"kind":"error","stem":"캠핑장의 뾰족한 텐트(사각뿔 모양)를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「밑면이 위에도 하나 있어 밑면은 2개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"이현 — 「옆면은 모두 삼각형이야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「옆면은 4개야.」","mis":"M6-1-u2-X14"}],"explanation":["사각뿔의 밑면은 사각형 1개예요.","위쪽은 면이 아니라 옆면이 모두 만나는 한 점이에요.","준희는 밑면을 2개로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 캠핑장의 뾰족한 텐트(사각뿔 모양)를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「밑면이 위에도 하나 있어 밑면은 2개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"수아 — 「옆면은 모두 삼각형이야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「옆면은 4개야.」","mis":"M6-1-u2-X14"}],"explanation":["사각뿔의 밑면은 사각형 1개예요.","위쪽은 면이 아니라 옆면이 모두 만나는 한 점이에요.","서호는 밑면을 2개로 잘못 말했어요."]},{"stem":"이번에는 다른 보기예요. 캠핑장의 뾰족한 텐트(사각뿔 모양)를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「밑면이 위에도 하나 있어 밑면은 2개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"나린 — 「옆면은 모두 삼각형이야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「옆면은 4개야.」","mis":"M6-1-u2-X14"}],"explanation":["사각뿔의 밑면은 사각형 1개예요.","위쪽은 면이 아니라 옆면이 모두 만나는 한 점이에요.","가온은 밑면을 2개로 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#4','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',3,'ox','auto','각뿔의 옆면은 모두 한 점에서 만나요.',ARRAY['M6-1-u2-X11']::text[],true,'{"seq":4,"concept":"M6-1-u2-C5","difficulty":3,"kind":"ox","stem":"각뿔의 옆면은 모두 한 점에서 만나요.","answer":"O","reason_options":[{"t":"옆면이 모두 밑면의 변과 위쪽 한 점을 이어 만들어지기 때문에","correct":true},{"t":"옆면이 밑면과 수직이기 때문에","mis":"M6-1-u2-X11"}],"mis":"M6-1-u2-X11","explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면 하나가 밑면, 삼각형들이 옆면이에요.","원뿔은 밑면이 원이라 각뿔이 아니에요."],"variant_rule":{"alt":[{"stem":"삼각뿔은 어느 면이든 밑면이 될 수 있어요.","answer":"O","reason_options":[{"t":"네 면이 모두 삼각형이라 어느 면을 밑면으로 보아도 나머지가 삼각형이기 때문에","correct":true},{"t":"삼각뿔은 밑면이 2개이기 때문에","mis":"M6-1-u2-X10"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면 하나가 밑면, 삼각형들이 옆면이에요.","원뿔은 밑면이 원이라 각뿔이 아니에요."]},{"stem":"밑면이 육각형인 각뿔의 옆면은 2개예요.","answer":"X","reason_options":[{"t":"옆면은 밑면의 변의 수만큼, 6개이기 때문에","correct":true},{"t":"옆면은 위아래 2개뿐이기 때문에","mis":"M6-1-u2-X10"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면 하나가 밑면, 삼각형들이 옆면이에요.","원뿔은 밑면이 원이라 각뿔이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#5','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',3,'mc','auto','「굽은 면으로만 둘러싸인 공」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X11']::text[],true,'{"seq":5,"concept":"M6-1-u2-C5","difficulty":3,"kind":"mc","stem":"「굽은 면으로만 둘러싸인 공」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다각형인 면이 하나도 없기 때문에","correct":true},{"t":"밑면이 다각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"옆면이 삼각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「굽은 면으로만 둘러싸인 공」을 이 조건에 대어 봐요.","다각형인 면이 하나도 없기 때문에 각뿔이 아니에요."],"variant_rule":{"alt":[{"stem":"「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 삼각형이 아니기 때문에","correct":true},{"t":"밑면이 다각형이 아니기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」을 이 조건에 대어 봐요.","옆면이 삼각형이 아니기 때문에 각뿔이 아니에요."]},{"stem":"「서로 평행하고 합동인 두 오각형과 직사각형 5개로 된 상자」는 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","correct":true},{"t":"밑면이 다각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"옆면이 삼각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「서로 평행하고 합동인 두 오각형과 직사각형 5개로 된 상자」를 이 조건에 대어 봐요.","다각형인 면이 2개이고 옆면이 직사각형이기 때문에 각뿔이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#6','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',3,'sa','auto','가 한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통 · 나 서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통 · 다 한 면이 오각형이고 나머지 면이 모두 삼각형인 탑 지붕 · 라 한 원과 뾰족한 점이 있는 고깔 · 마 위아래 면이 서로 평행하고 합동인 원인 저금통 — 이 가운데 각뿔 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C5","difficulty":3,"kind":"sa","stem":"가 한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통 · 나 서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통 · 다 한 면이 오각형이고 나머지 면이 모두 삼각형인 탑 지붕 · 라 한 원과 뾰족한 점이 있는 고깔 · 마 위아래 면이 서로 평행하고 합동인 원인 저금통 — 이 가운데 각뿔 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각뿔의 뜻에 하나씩 대어 봐요.","각뿔인 것은 가, 다예요.","모두 2개예요."],"mis":"M6-1-u2-X11","variant_rule":{"alt":[{"stem":"가 한 면이 오각형이고 나머지 면이 모두 삼각형인 탑 지붕 · 나 서로 평행하고 합동인 두 육각형과 직사각형 6개로 둘러싸인 연필 · 다 한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통 · 라 서로 평행하고 합동인 두 삼각형과 직사각형 3개로 둘러싸인 상자 · 마 굽은 면 하나로만 둘러싸인 공 모양 저금통 — 이 가운데 각뿔 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["각뿔의 뜻에 하나씩 대어 봐요.","각뿔인 것은 가, 다예요.","모두 2개예요."]},{"stem":"가 한 원과 뾰족한 점이 있는 고깔 · 나 한 면이 사각형이고 나머지 면이 모두 삼각형인 저금통 · 다 서로 평행한 두 사각형의 크기가 서로 다른 저금통 · 라 위아래 면이 서로 평행하고 합동인 원인 저금통 · 마 서로 평행하고 합동인 두 오각형과 직사각형 5개로 둘러싸인 저금통 — 이 가운데 각뿔 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["각뿔의 뜻에 하나씩 대어 봐요.","각뿔인 것은 나예요.","모두 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#7','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',3,'sa','auto','밑면이 오각형인 각기둥과 각뿔이 있어요. 각기둥의 면의 수는 각뿔의 면의 수보다 몇 개 더 많나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u2-C5","difficulty":3,"kind":"sa","stem":"밑면이 오각형인 각기둥과 각뿔이 있어요. 각기둥의 면의 수는 각뿔의 면의 수보다 몇 개 더 많나요? 숫자로 쓰세요.","answer":["1"],"explanation":["밑면 2개와 옆면 5개 — 5 + 2 = 7개예요.","밑면 1개와 옆면 5개 — 5 + 1 = 6개예요.","차는 7 − 6 = 1개예요 — 각기둥이 밑면이 하나 더 있어서예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"밑면이 팔각형인 각기둥과 각뿔이 있어요. 각기둥의 면의 수는 각뿔의 면의 수보다 몇 개 더 많나요? 숫자로 쓰세요.","answer":["1"],"explanation":["밑면 2개와 옆면 8개 — 8 + 2 = 10개예요.","밑면 1개와 옆면 8개 — 8 + 1 = 9개예요.","차는 10 − 9 = 1개예요 — 각기둥이 밑면이 하나 더 있어서예요."]},{"stem":"밑면이 육각형인 각기둥과 각뿔이 있어요. 각기둥의 면의 수는 각뿔의 면의 수보다 몇 개 더 많나요? 숫자로 쓰세요.","answer":["1"],"explanation":["밑면 2개와 옆면 6개 — 6 + 2 = 8개예요.","밑면 1개와 옆면 6개 — 6 + 1 = 7개예요.","차는 8 − 7 = 1개예요 — 각기둥이 밑면이 하나 더 있어서예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#8','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',4,'sa','auto','밑면이 사각형인 똑같은 각뿔 두 개의 밑면끼리 꼭 맞게 붙여 새 입체도형을 만들었어요. 새 입체도형의 겉에 보이는 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C5","difficulty":4,"kind":"sa","stem":"밑면이 사각형인 똑같은 각뿔 두 개의 밑면끼리 꼭 맞게 붙여 새 입체도형을 만들었어요. 새 입체도형의 겉에 보이는 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["두 밑면은 서로 맞붙어 안으로 숨어요 — 겉에는 보이지 않아요.","각 각뿔의 옆면은 4개씩, 모두 삼각형이에요.","두 각뿔의 옆면만 겉에 남아요 — 4 + 4 = 8개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"밑면이 오각형인 똑같은 각뿔 두 개의 밑면끼리 꼭 맞게 붙여 새 입체도형을 만들었어요. 새 입체도형의 겉에 보이는 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["두 밑면은 서로 맞붙어 안으로 숨어요 — 겉에는 보이지 않아요.","각 각뿔의 옆면은 5개씩, 모두 삼각형이에요.","맞붙은 밑면의 꼭짓점 5개에 위아래 각뿔의 꼭짓점 2개 — 5 + 2 = 7개예요."]},{"stem":"밑면이 삼각형인 똑같은 각뿔 두 개의 밑면끼리 꼭 맞게 붙여 새 입체도형을 만들었어요. 새 입체도형의 겉에 보이는 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["두 밑면은 서로 맞붙어 안으로 숨어요 — 겉에는 보이지 않아요.","각 각뿔의 옆면은 3개씩, 모두 삼각형이에요.","맞붙은 밑면의 변 3개에 위아래 옆 모서리 3개씩 — 3 + 3 + 3 = 9개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#9','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',4,'mc','auto','각기둥에는 있지만 각뿔에는 없는 것은 어느 것인가요?',ARRAY['M6-1-u2-X05','M6-1-u2-X11']::text[],true,'{"seq":9,"concept":"M6-1-u2-C5","difficulty":4,"kind":"mc","stem":"각기둥에는 있지만 각뿔에는 없는 것은 어느 것인가요?","options":[{"t":"서로 평행하고 합동인 두 밑면","correct":true},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"꼭짓점","mis":"M6-1-u2-X05"},{"t":"다각형인 밑면","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 밑면이 2개, 옆면이 직사각형이고 밑면과 수직으로 만나요.","각뿔은 밑면이 1개, 옆면이 삼각형이고 한 점에서 모두 만나요.","같은 말을 옮겨 쓰면 안 돼요."],"variant_rule":{"alt":[{"stem":"각기둥과 각뿔을 바르게 견준 것은 어느 것인가요?","options":[{"t":"밑면이 각기둥은 2개, 각뿔은 1개예요","correct":true},{"t":"옆면이 각기둥은 삼각형, 각뿔은 직사각형이에요","mis":"M6-1-u2-X03"},{"t":"밑면의 수가 같아요","mis":"M6-1-u2-X10"},{"t":"각뿔의 옆면도 밑면과 수직으로 만나요","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 밑면이 2개, 옆면이 직사각형이고 밑면과 수직으로 만나요.","각뿔은 밑면이 1개, 옆면이 삼각형이고 한 점에서 모두 만나요.","같은 말을 옮겨 쓰면 안 돼요."]},{"stem":"각뿔에 대해 바르게 설명한 것은 어느 것인가요?","options":[{"t":"밑면은 1개이고 옆면은 모두 삼각형이에요","correct":true},{"t":"밑면이 옆면과 모두 수직으로 만나요","mis":"M6-1-u2-X11"},{"t":"옆면은 모두 직사각형이에요","mis":"M6-1-u2-X03"},{"t":"밑면은 2개예요","mis":"M6-1-u2-X10"}],"explanation":["각기둥은 밑면이 2개, 옆면이 직사각형이고 밑면과 수직으로 만나요.","각뿔은 밑면이 1개, 옆면이 삼각형이고 한 점에서 모두 만나요.","같은 말을 옮겨 쓰면 안 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L06_challenge#10','math',6,1,'u2','L06','g6_1_math_u2_L06_challenge','lesson_challenge','M6-1-u2-C5',4,'essay','teacher','캠핑장에서 본 원뿔 모양 고깔과 사각뿔 모양 텐트가 있어요. 두 입체도형 가운데 각뿔인 것을 쓰고, 다른 하나가 각뿔이 아닌 까닭을 각뿔의 뜻으로 설명해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C5","difficulty":4,"kind":"essay","stem":"캠핑장에서 본 원뿔 모양 고깔과 사각뿔 모양 텐트가 있어요. 두 입체도형 가운데 각뿔인 것을 쓰고, 다른 하나가 각뿔이 아닌 까닭을 각뿔의 뜻으로 설명해 보세요.","answer_guide":{"answer":"예: 사각뿔 모양 텐트가 각뿔이다. 각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이다. 원뿔 모양 고깔은 밑면이 원이라 다각형이 아니고 옆면도 굽은 면이라 삼각형이 아니므로 각뿔이 아니다.","scoring_points":["사각뿔 모양 텐트를 각뿔이라고 했는가","각뿔의 뜻(한 면 다각형, 나머지 삼각형)을 썼는가","원뿔은 밑면이 원이라 각뿔이 아니라고 설명했는가"]},"explanation":["각뿔은 한 면이 다각형, 나머지가 삼각형이에요.","원뿔은 밑면이 원이에요.","그래서 사각뿔 텐트만 각뿔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#1','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',1,'mc','auto','밑면이 육각형인 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":1,"concept":"M6-1-u2-C6","difficulty":1,"kind":"mc","stem":"밑면이 육각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"육각뿔","correct":true},{"t":"육각기둥","mis":"M6-1-u2-X11"},{"t":"칠각뿔","mis":"M6-1-u2-X04"},{"t":"십이각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 육각형이에요.","그래서 이름은 육각뿔이에요."],"variant_rule":{"alt":[{"stem":"밑면이 오각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"오각뿔","correct":true},{"t":"오각기둥","mis":"M6-1-u2-X11"},{"t":"육각뿔","mis":"M6-1-u2-X04"},{"t":"십각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 오각형이에요.","그래서 이름은 오각뿔이에요."]},{"stem":"밑면이 사각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"사각뿔","correct":true},{"t":"사각기둥","mis":"M6-1-u2-X11"},{"t":"오각뿔","mis":"M6-1-u2-X04"},{"t":"팔각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 사각형이에요.","그래서 이름은 사각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#2','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',1,'sa','auto','사각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C6","difficulty":1,"kind":"sa","stem":"사각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["사각뿔의 밑면은 사각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 4개와 옆 모서리 4개 — 4 × 2 = 8개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"삼각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["삼각뿔의 밑면은 삼각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 3개와 옆 모서리 3개 — 3 × 2 = 6개예요."]},{"stem":"육각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["육각뿔의 밑면은 육각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#3','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',1,'sa','auto','오각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M6-1-u2-C6","difficulty":1,"kind":"sa","stem":"오각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["오각뿔의 밑면은 오각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 5 + 1 = 6개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"사각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["사각뿔의 밑면은 사각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 4개와 각뿔의 꼭짓점 1개 — 4 + 1 = 5개예요."]},{"stem":"육각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["육각뿔의 밑면은 육각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 6개와 각뿔의 꼭짓점 1개 — 6 + 1 = 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#4','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',1,'mc','auto','각뿔의 꼭짓점은 어떤 점인가요?',ARRAY['M6-1-u2-X05','M6-1-u2-X10']::text[],true,'{"seq":4,"concept":"M6-1-u2-C6","difficulty":1,"kind":"mc","stem":"각뿔의 꼭짓점은 어떤 점인가요?","options":[{"t":"옆면이 모두 만나는 점","correct":true},{"t":"밑면의 한가운데 있는 점","mis":"M6-1-u2-X05"},{"t":"모서리의 한가운데 있는 점","mis":"M6-1-u2-X05"},{"t":"밑면의 꼭짓점","mis":"M6-1-u2-X10"}],"explanation":["옆면이 모두 만나는 한 점을 각뿔의 꼭짓점이라고 해요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리는 비스듬해서 언제나 높이보다 길어요."],"variant_rule":{"alt":[{"stem":"각뿔의 높이는 무엇인가요?","options":[{"t":"각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이","correct":true},{"t":"옆 모서리의 길이","mis":"M6-1-u2-X06"},{"t":"밑면의 가장 긴 변의 길이","mis":"M6-1-u2-X06"},{"t":"밑면의 둘레","mis":"M6-1-u2-X06"}],"explanation":["옆면이 모두 만나는 한 점을 각뿔의 꼭짓점이라고 해요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리는 비스듬해서 언제나 높이보다 길어요."]},{"stem":"각뿔에서 옆 모서리의 길이가 높이가 될 수 없는 까닭은 무엇인가요?","options":[{"t":"옆 모서리는 비스듬히 기울어져 높이보다 길기 때문에","correct":true},{"t":"옆 모서리는 밑면에 있기 때문에","mis":"M6-1-u2-X05"},{"t":"옆 모서리는 높이보다 짧기 때문에","mis":"M6-1-u2-X06"},{"t":"각뿔에는 높이가 없기 때문에","mis":"M6-1-u2-X06"}],"explanation":["옆면이 모두 만나는 한 점을 각뿔의 꼭짓점이라고 해요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리는 비스듬해서 언제나 높이보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#5','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',2,'sa','auto','육각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"육각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 10 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 8 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"사각뿔 모양 건축물이 있어요. 옆 모서리가 13 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 12 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 13 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 12 cm예요."]},{"stem":"오각뿔 모양 건축물이 있어요. 옆 모서리가 17 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 15 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 17 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 15 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#6','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',2,'ox','auto','오각뿔의 꼭짓점은 5개예요.',ARRAY['M6-1-u2-X10']::text[],true,'{"seq":6,"concept":"M6-1-u2-C6","difficulty":2,"kind":"ox","stem":"오각뿔의 꼭짓점은 5개예요.","answer":"X","reason_options":[{"t":"밑면의 꼭짓점 5개에 각뿔의 꼭짓점 1개를 더해 6개이기 때문에","correct":true},{"t":"밑면이 오각형이라 꼭짓점도 5개이기 때문에","mis":"M6-1-u2-X10"}],"mis":"M6-1-u2-X10","explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."],"variant_rule":{"alt":[{"stem":"옆면이 4개인 각뿔은 사각뿔이에요.","answer":"O","reason_options":[{"t":"옆면의 수는 밑면의 변의 수와 같아 밑면이 사각형이기 때문에","correct":true},{"t":"각뿔의 이름은 면의 수로 정하기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."]},{"stem":"각뿔의 옆 모서리의 길이가 각뿔의 높이예요.","answer":"X","reason_options":[{"t":"높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이이기 때문에","correct":true},{"t":"옆 모서리가 가장 길기 때문에","mis":"M6-1-u2-X06"}],"explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#7','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',2,'sa','auto','팔각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"팔각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["팔각뿔의 밑면은 팔각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"칠각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["칠각뿔의 밑면은 칠각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요."]},{"stem":"구각뿔의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["구각뿔의 밑면은 구각형이에요.","면을 세는 방법을 떠올려요.","밑면 1개와 옆면 9개 — 9 + 1 = 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#8','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',2,'mc','auto','밑면이 다각형이고 옆면이 모두 삼각형이며 꼭짓점이 7개인 입체도형의 이름은 무엇인가요?',ARRAY['M6-1-u2-X10','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":8,"concept":"M6-1-u2-C6","difficulty":2,"kind":"mc","stem":"밑면이 다각형이고 옆면이 모두 삼각형이며 꼭짓점이 7개인 입체도형의 이름은 무엇인가요?","options":[{"t":"육각뿔","correct":true},{"t":"칠각뿔","mis":"M6-1-u2-X10"},{"t":"육각기둥","mis":"M6-1-u2-X11"},{"t":"오각뿔","mis":"M6-1-u2-X12"}],"explanation":["밑면이 다각형이고 옆면이 모두 삼각형이니 각뿔이에요.","각뿔의 꼭짓점은 변의 수 + 1 — 그래서 한 밑면의 변은 6개예요.","밑면이 육각형이라 육각뿔이에요."],"variant_rule":{"alt":[{"stem":"밑면이 다각형이고 옆면이 모두 삼각형이며 모서리가 10개인 입체도형의 이름은 무엇인가요?","options":[{"t":"오각뿔","correct":true},{"t":"십각뿔","mis":"M6-1-u2-X04"},{"t":"오각기둥","mis":"M6-1-u2-X11"},{"t":"육각뿔","mis":"M6-1-u2-X12"}],"explanation":["밑면이 다각형이고 옆면이 모두 삼각형이니 각뿔이에요.","각뿔의 모서리는 변의 수 × 2 — 그래서 한 밑면의 변은 5개예요.","밑면이 오각형이라 오각뿔이에요."]},{"stem":"밑면이 다각형이고 옆면이 모두 삼각형이며 꼭짓점이 8개인 입체도형의 이름은 무엇인가요?","options":[{"t":"칠각뿔","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X10"},{"t":"칠각기둥","mis":"M6-1-u2-X11"},{"t":"육각뿔","mis":"M6-1-u2-X12"}],"explanation":["밑면이 다각형이고 옆면이 모두 삼각형이니 각뿔이에요.","각뿔의 꼭짓점은 변의 수 + 1 — 그래서 한 밑면의 변은 7개예요.","밑면이 칠각형이라 칠각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#9','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',2,'match','auto','각뿔과 그 꼭짓점 수를 알맞게 이으세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C6","difficulty":2,"kind":"match","stem":"각뿔과 그 꼭짓점 수를 알맞게 이으세요.","pairs":[{"l":"삼각뿔","r":"4개"},{"l":"사각뿔","r":"5개"},{"l":"육각뿔","r":"7개"}],"mis":"M6-1-u2-X10","explanation":["각뿔의 꼭짓점 수는 변의 수 + 1이에요.","삼각뿔 4개, 사각뿔 5개, 육각뿔 7개예요.","밑면의 변의 수부터 보면 바로 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"각뿔과 그 모서리 수를 알맞게 이으세요.","pairs":[{"l":"사각뿔","r":"8개"},{"l":"오각뿔","r":"10개"},{"l":"팔각뿔","r":"16개"}],"explanation":["각뿔의 모서리 수는 변의 수 × 2예요.","사각뿔 8개, 오각뿔 10개, 팔각뿔 16개예요.","밑면의 변의 수부터 보면 바로 구할 수 있어요."]},{"stem":"각뿔과 그 면 수를 알맞게 이으세요.","pairs":[{"l":"삼각뿔","r":"4개"},{"l":"오각뿔","r":"6개"},{"l":"칠각뿔","r":"8개"}],"explanation":["각뿔의 면 수는 변의 수 + 1이에요.","삼각뿔 4개, 오각뿔 6개, 칠각뿔 8개예요.","밑면의 변의 수부터 보면 바로 구할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_basic#10','math',6,1,'u2','L07','g6_1_math_u2_L07_basic','lesson_basic','M6-1-u2-C6',3,'error','auto','오각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X10','M6-1-u2-X14']::text[],true,'{"seq":10,"concept":"M6-1-u2-C6","difficulty":3,"kind":"error","stem":"오각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「꼭짓점이 5개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"이현 — 「모서리가 10개야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「옆면이 5개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 5 + 1 = 6개예요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요.","준희는 각뿔의 꼭짓점을 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"육각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「꼭짓점이 6개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"수아 — 「모서리가 12개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「옆면이 6개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 6개와 각뿔의 꼭짓점 1개 — 6 + 1 = 7개예요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요.","서호는 각뿔의 꼭짓점을 빠뜨렸어요."]},{"stem":"칠각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꼭짓점이 7개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"나린 — 「모서리가 14개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「옆면이 7개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요.","밑면의 변 7개와 옆 모서리 7개 — 7 × 2 = 14개예요.","가온은 각뿔의 꼭짓점을 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#1','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',2,'sa','auto','십각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"십각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["십각뿔의 밑면은 십각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 10개와 각뿔의 꼭짓점 1개 — 10 + 1 = 11개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"구각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["구각뿔의 밑면은 구각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요."]},{"stem":"십일각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["십일각뿔의 밑면은 십일각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 11개와 각뿔의 꼭짓점 1개 — 11 + 1 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#2','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',2,'ox','auto','각뿔의 이름을 정하는 방식은 각기둥과 같아요.',ARRAY['M6-1-u2-X04']::text[],true,'{"seq":2,"concept":"M6-1-u2-C6","difficulty":2,"kind":"ox","stem":"각뿔의 이름을 정하는 방식은 각기둥과 같아요.","answer":"O","reason_options":[{"t":"둘 다 밑면의 모양에 따라 이름을 붙이기 때문에","correct":true},{"t":"둘 다 옆면의 모양으로 이름을 붙이기 때문에","mis":"M6-1-u2-X04"}],"mis":"M6-1-u2-X04","explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."],"variant_rule":{"alt":[{"stem":"꼭짓점의 수를 셀 때 각뿔의 꼭짓점은 빼고 세요.","answer":"X","reason_options":[{"t":"각뿔의 꼭짓점도 모서리가 만나는 꼭짓점이라 꼭 세어야 하기 때문에","correct":true},{"t":"각뿔의 꼭짓점은 면 위에 있지 않기 때문에","mis":"M6-1-u2-X10"}],"explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."]},{"stem":"사각뿔의 모서리는 8개예요.","answer":"O","reason_options":[{"t":"밑면의 변 4개와 옆 모서리 4개 — 4 × 2 = 8개이기 때문에","correct":true},{"t":"사각뿔은 사각기둥과 모서리 수가 같기 때문에","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#3','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',3,'mc','auto','밑면이 다각형이고 옆면이 모두 삼각형이며 모서리가 16개인 입체도형의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":3,"concept":"M6-1-u2-C6","difficulty":3,"kind":"mc","stem":"밑면이 다각형이고 옆면이 모두 삼각형이며 모서리가 16개인 입체도형의 이름은 무엇인가요?","options":[{"t":"팔각뿔","correct":true},{"t":"십육각뿔","mis":"M6-1-u2-X04"},{"t":"팔각기둥","mis":"M6-1-u2-X11"},{"t":"구각뿔","mis":"M6-1-u2-X12"}],"explanation":["밑면이 다각형이고 옆면이 모두 삼각형이니 각뿔이에요.","각뿔의 모서리는 변의 수 × 2 — 그래서 한 밑면의 변은 8개예요.","밑면이 팔각형이라 팔각뿔이에요."],"variant_rule":{"alt":[{"stem":"밑면이 다각형이고 옆면이 모두 삼각형이며 꼭짓점이 10개인 입체도형의 이름은 무엇인가요?","options":[{"t":"구각뿔","correct":true},{"t":"십각뿔","mis":"M6-1-u2-X10"},{"t":"구각기둥","mis":"M6-1-u2-X11"},{"t":"팔각뿔","mis":"M6-1-u2-X12"}],"explanation":["밑면이 다각형이고 옆면이 모두 삼각형이니 각뿔이에요.","각뿔의 꼭짓점은 변의 수 + 1 — 그래서 한 밑면의 변은 9개예요.","밑면이 구각형이라 구각뿔이에요."]},{"stem":"밑면이 다각형이고 옆면이 모두 삼각형이며 면이 8개인 입체도형의 이름은 무엇인가요?","options":[{"t":"칠각뿔","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X04"},{"t":"칠각기둥","mis":"M6-1-u2-X11"},{"t":"육각뿔","mis":"M6-1-u2-X12"}],"explanation":["밑면이 다각형이고 옆면이 모두 삼각형이니 각뿔이에요.","각뿔의 면은 변의 수 + 1 — 그래서 한 밑면의 변은 7개예요.","밑면이 칠각형이라 칠각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#4','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',3,'sa','auto','팔각뿔 모양 건축물이 있어요. 옆 모서리가 25 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 24 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C6","difficulty":3,"kind":"sa","stem":"팔각뿔 모양 건축물이 있어요. 옆 모서리가 25 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 24 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 25 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 24 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"삼각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 6 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 10 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 6 cm예요."]},{"stem":"칠각뿔 모양 건축물이 있어요. 옆 모서리가 26 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 24 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 26 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#5','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',3,'mc','auto','각뿔에서 옆 모서리의 길이가 높이가 될 수 없는 까닭은 무엇인가요?',ARRAY['M6-1-u2-X05','M6-1-u2-X06']::text[],true,'{"seq":5,"concept":"M6-1-u2-C6","difficulty":3,"kind":"mc","stem":"각뿔에서 옆 모서리의 길이가 높이가 될 수 없는 까닭은 무엇인가요?","options":[{"t":"옆 모서리는 비스듬히 기울어져 높이보다 길기 때문에","correct":true},{"t":"옆 모서리는 밑면에 있기 때문에","mis":"M6-1-u2-X05"},{"t":"옆 모서리는 높이보다 짧기 때문에","mis":"M6-1-u2-X06"},{"t":"각뿔에는 높이가 없기 때문에","mis":"M6-1-u2-X06"}],"explanation":["옆면이 모두 만나는 한 점을 각뿔의 꼭짓점이라고 해요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리는 비스듬해서 언제나 높이보다 길어요."],"variant_rule":{"alt":[{"stem":"각뿔의 꼭짓점은 어떤 점인가요?","options":[{"t":"옆면이 모두 만나는 점","correct":true},{"t":"밑면의 한가운데 있는 점","mis":"M6-1-u2-X05"},{"t":"모서리의 한가운데 있는 점","mis":"M6-1-u2-X05"},{"t":"밑면의 꼭짓점","mis":"M6-1-u2-X10"}],"explanation":["옆면이 모두 만나는 한 점을 각뿔의 꼭짓점이라고 해요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리는 비스듬해서 언제나 높이보다 길어요."]},{"stem":"각뿔의 높이는 무엇인가요?","options":[{"t":"각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이","correct":true},{"t":"옆 모서리의 길이","mis":"M6-1-u2-X06"},{"t":"밑면의 가장 긴 변의 길이","mis":"M6-1-u2-X06"},{"t":"밑면의 둘레","mis":"M6-1-u2-X06"}],"explanation":["옆면이 모두 만나는 한 점을 각뿔의 꼭짓점이라고 해요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리는 비스듬해서 언제나 높이보다 길어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#6','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',3,'sa','auto','육각뿔의 모서리 수와 꼭짓점 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C6","difficulty":3,"kind":"sa","stem":"육각뿔의 모서리 수와 꼭짓점 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["19"],"explanation":["밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요.","밑면의 꼭짓점 6개와 각뿔의 꼭짓점 1개 — 6 + 1 = 7개예요.","두 수를 더하면 12 + 7 = 19개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"칠각뿔의 면 수와 모서리 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["밑면 1개와 옆면 7개 — 7 + 1 = 8개예요.","밑면의 변 7개와 옆 모서리 7개 — 7 × 2 = 14개예요.","두 수를 더하면 8 + 14 = 22개예요."]},{"stem":"오각뿔의 면 수와 꼭짓점 수를 더하면 모두 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["밑면 1개와 옆면 5개 — 5 + 1 = 6개예요.","밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 5 + 1 = 6개예요.","두 수를 더하면 6 + 6 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#7','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',3,'error','auto','팔각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X10','M6-1-u2-X14']::text[],true,'{"seq":7,"concept":"M6-1-u2-C6","difficulty":3,"kind":"error","stem":"팔각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「꼭짓점이 8개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"라온 — 「모서리가 16개야.」","mis":"M6-1-u2-X14"},{"t":"예준 — 「옆면이 8개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 8개와 각뿔의 꼭짓점 1개 — 8 + 1 = 9개예요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요.","여울은 각뿔의 꼭짓점을 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"사각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「꼭짓점이 4개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"이현 — 「모서리가 8개야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「옆면이 4개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 4개와 각뿔의 꼭짓점 1개 — 4 + 1 = 5개예요.","밑면의 변 4개와 옆 모서리 4개 — 4 × 2 = 8개예요.","준희는 각뿔의 꼭짓점을 빠뜨렸어요."]},{"stem":"구각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「꼭짓점이 9개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"수아 — 「모서리가 18개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「옆면이 9개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요.","서호는 각뿔의 꼭짓점을 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#8','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',4,'sa','auto','밑면이 한 변이 3 cm인 정사각형이고 옆 모서리가 모두 5 cm인 사각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C6","difficulty":4,"kind":"sa","stem":"밑면이 한 변이 3 cm인 정사각형이고 옆 모서리가 모두 5 cm인 사각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["밑면의 변은 4개이고 모두 3 cm예요.","옆 모서리도 4개이고 모두 5 cm예요.","4 × 3 + 4 × 5 = 32 — 모두 32 cm예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 한 변이 2 cm인 정육각형이고 옆 모서리가 모두 7 cm인 육각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["54"],"explanation":["밑면의 변은 6개이고 모두 2 cm예요.","옆 모서리도 6개이고 모두 7 cm예요.","6 × 2 + 6 × 7 = 54 — 모두 54 cm예요."]},{"stem":"밑면이 한 변이 4 cm인 정오각형이고 옆 모서리가 모두 6 cm인 오각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["50"],"explanation":["밑면의 변은 5개이고 모두 4 cm예요.","옆 모서리도 5개이고 모두 6 cm예요.","5 × 4 + 5 × 6 = 50 — 모두 50 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#9','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',4,'sa','auto','밑면이 한 변이 6 cm인 정삼각형이고 옆 모서리가 모두 8 cm인 삼각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C6","difficulty":4,"kind":"sa","stem":"밑면이 한 변이 6 cm인 정삼각형이고 옆 모서리가 모두 8 cm인 삼각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["밑면의 변은 3개이고 모두 6 cm예요.","옆 모서리도 3개이고 모두 8 cm예요.","3 × 6 + 3 × 8 = 42 — 모두 42 cm예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 한 변이 2 cm인 정팔각형이고 옆 모서리가 모두 9 cm인 팔각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["88"],"explanation":["밑면의 변은 8개이고 모두 2 cm예요.","옆 모서리도 8개이고 모두 9 cm예요.","8 × 2 + 8 × 9 = 88 — 모두 88 cm예요."]},{"stem":"밑면이 한 변이 5 cm인 정육각형이고 옆 모서리가 모두 9 cm인 육각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["밑면의 변은 6개이고 모두 5 cm예요.","옆 모서리도 6개이고 모두 9 cm예요.","6 × 5 + 6 × 9 = 84 — 모두 84 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L07_challenge#10','math',6,1,'u2','L07','g6_1_math_u2_L07_challenge','lesson_challenge','M6-1-u2-C6',4,'essay','teacher','친구가 오각뿔의 꼭짓점을 「5개」라고 했어요. 잘못된 점을 쓰고, 오각뿔의 꼭짓점과 모서리의 수를 바르게 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C6","difficulty":4,"kind":"essay","stem":"친구가 오각뿔의 꼭짓점을 「5개」라고 했어요. 잘못된 점을 쓰고, 오각뿔의 꼭짓점과 모서리의 수를 바르게 구해 보세요.","answer_guide":{"answer":"예: 밑면의 꼭짓점 5개만 세고 옆면이 모두 만나는 각뿔의 꼭짓점 1개를 빠뜨렸다. 오각뿔의 꼭짓점은 5 + 1 = 6개이다. 모서리는 밑면의 변 5개와 옆 모서리 5개로 5 × 2 = 10개이다.","scoring_points":["각뿔의 꼭짓점을 빠뜨렸다고 썼는가","꼭짓점 6개를 구했는가","모서리 10개를 구했는가"]},"explanation":["각뿔의 꼭짓점을 빠뜨렸어요.","꼭짓점은 5 + 1 = 6개예요.","모서리는 5 × 2 = 10개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#1','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',1,'sa','auto','칠각기둥의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M6-1-u2-C7","difficulty":1,"kind":"sa","stem":"칠각기둥의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["9"],"explanation":["각기둥의 면 수 = 변의 수 + 2예요.","한 밑면의 변은 7개예요.","밑면 2개와 옆면 7개 — 7 + 2 = 9개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"팔각기둥의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["16"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 변은 8개예요.","한 밑면의 꼭짓점 8개가 위아래로 짝을 이뤄 — 8 × 2 = 16개예요."]},{"stem":"구각뿔의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["18"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","한 밑면의 변은 9개예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#2','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',1,'mc','auto','각기둥에서 면의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X12']::text[],true,'{"seq":2,"concept":"M6-1-u2-C7","difficulty":1,"kind":"mc","stem":"각기둥에서 면의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"변의 수 + 2","correct":true},{"t":"변의 수 × 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 3","mis":"M6-1-u2-X12"},{"t":"변의 수 + 1","mis":"M6-1-u2-X12"}],"explanation":["삼각기둥, 사각기둥, 오각기둥의 면 수를 세어 표로 늘어놓아요.","5개, 6개, 7개 — 변의 수 3, 4, 5와 견주어 봐요.","그래서 면 수 = 변의 수 + 2예요."],"variant_rule":{"alt":[{"stem":"각기둥에서 꼭짓점의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"변의 수 × 2","correct":true},{"t":"변의 수 + 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 3","mis":"M6-1-u2-X12"},{"t":"변의 수 + 1","mis":"M6-1-u2-X12"}],"explanation":["삼각기둥, 사각기둥, 오각기둥의 꼭짓점 수를 세어 표로 늘어놓아요.","6개, 8개, 10개 — 변의 수 3, 4, 5와 견주어 봐요.","그래서 꼭짓점 수 = 변의 수 × 2예요."]},{"stem":"각뿔에서 모서리의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"변의 수 × 2","correct":true},{"t":"변의 수 + 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 3","mis":"M6-1-u2-X12"},{"t":"변의 수 + 1","mis":"M6-1-u2-X12"}],"explanation":["삼각뿔, 사각뿔, 오각뿔의 모서리 수를 세어 표로 늘어놓아요.","6개, 8개, 10개 — 변의 수 3, 4, 5와 견주어 봐요.","그래서 모서리 수 = 변의 수 × 2예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#3','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',1,'mc','auto','각뿔에서 면의 수와 꼭짓점의 수를 견주면 어떠한가요?',ARRAY['M6-1-u2-X12','M6-1-u2-X10']::text[],true,'{"seq":3,"concept":"M6-1-u2-C7","difficulty":1,"kind":"mc","stem":"각뿔에서 면의 수와 꼭짓점의 수를 견주면 어떠한가요?","options":[{"t":"두 수가 서로 같아요","correct":true},{"t":"면의 수가 더 많아요","mis":"M6-1-u2-X12"},{"t":"꼭짓점의 수가 더 많아요","mis":"M6-1-u2-X10"},{"t":"밑면에 따라 달라져요","mis":"M6-1-u2-X12"}],"explanation":["각뿔은 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1이라 두 수가 같아요.","모서리는 각기둥이 변의 수 × 3, 각뿔이 변의 수 × 2예요.","그래서 답은 「두 수가 서로 같아요」예요."],"variant_rule":{"alt":[{"stem":"같은 밑면의 각기둥과 각뿔에서 모서리의 수를 견주면 어떠한가요?","options":[{"t":"각기둥이 변의 수만큼 더 많아요","correct":true},{"t":"두 수가 같아요","mis":"M6-1-u2-X12"},{"t":"각뿔이 더 많아요","mis":"M6-1-u2-X12"},{"t":"각기둥이 2개 더 많아요","mis":"M6-1-u2-X12"}],"explanation":["각뿔은 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1이라 두 수가 같아요.","모서리는 각기둥이 변의 수 × 3, 각뿔이 변의 수 × 2예요.","그래서 답은 「각기둥이 변의 수만큼 더 많아요」예요."]},{"stem":"각기둥에서 꼭짓점의 수와 모서리의 수를 견주면 어떠한가요?","options":[{"t":"모서리가 변의 수만큼 더 많아요","correct":true},{"t":"두 수가 같아요","mis":"M6-1-u2-X12"},{"t":"꼭짓점이 더 많아요","mis":"M6-1-u2-X12"},{"t":"모서리가 2개 더 많아요","mis":"M6-1-u2-X12"}],"explanation":["각뿔은 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1이라 두 수가 같아요.","모서리는 각기둥이 변의 수 × 3, 각뿔이 변의 수 × 2예요.","그래서 답은 「모서리가 변의 수만큼 더 많아요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#4','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',1,'sa','auto','십각기둥의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C7","difficulty":1,"kind":"sa","stem":"십각기둥의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["30"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","한 밑면의 변은 10개예요.","위 밑면 10개, 아래 밑면 10개, 옆 모서리 10개 — 10 × 3 = 30개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"십각뿔의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["11"],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","한 밑면의 변은 10개예요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요."]},{"stem":"십이각기둥의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["14"],"explanation":["각기둥의 면 수 = 변의 수 + 2예요.","한 밑면의 변은 12개예요.","밑면 2개와 옆면 12개 — 12 + 2 = 14개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#5','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'mc','auto','어떤 각기둥의 꼭짓점이 24개예요. 이 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":5,"concept":"M6-1-u2-C7","difficulty":2,"kind":"mc","stem":"어떤 각기둥의 꼭짓점이 24개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"십이각기둥","correct":true},{"t":"이십사각기둥","mis":"M6-1-u2-X04"},{"t":"십이각뿔","mis":"M6-1-u2-X11"},{"t":"십삼각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 꼭짓점 12개가 위아래로 짝을 이뤄 — 12 × 2 = 24개예요.","한 밑면의 변이 12개라 이름은 십이각기둥이에요."],"variant_rule":{"alt":[{"stem":"어떤 각기둥의 모서리가 27개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X12"},{"t":"팔각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","위 밑면 9개, 아래 밑면 9개, 옆 모서리 9개 — 9 × 3 = 27개예요.","한 밑면의 변이 9개라 이름은 구각기둥이에요."]},{"stem":"어떤 각기둥의 면이 12개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"십각기둥","correct":true},{"t":"십이각기둥","mis":"M6-1-u2-X04"},{"t":"십각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 면 수 = 변의 수 + 2예요.","밑면 2개와 옆면 10개 — 10 + 2 = 12개예요.","한 밑면의 변이 10개라 이름은 십각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#6','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'sa','auto','십일각뿔의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"십일각뿔의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 꼭짓점 수 = 변의 수 + 1이에요.","한 밑면의 변은 11개예요.","밑면의 꼭짓점 11개와 각뿔의 꼭짓점 1개 — 11 + 1 = 12개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"십오각기둥의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["30"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 변은 15개예요.","한 밑면의 꼭짓점 15개가 위아래로 짝을 이뤄 — 15 × 2 = 30개예요."]},{"stem":"십삼각뿔의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["26"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","한 밑면의 변은 13개예요.","밑면의 변 13개와 옆 모서리 13개 — 13 × 2 = 26개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#7','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'mc','auto','각뿔에서 면의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X12']::text[],true,'{"seq":7,"concept":"M6-1-u2-C7","difficulty":2,"kind":"mc","stem":"각뿔에서 면의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"변의 수 + 1","correct":true},{"t":"변의 수 + 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 3","mis":"M6-1-u2-X12"}],"explanation":["삼각뿔, 사각뿔, 오각뿔의 면 수를 세어 표로 늘어놓아요.","4개, 5개, 6개 — 변의 수 3, 4, 5와 견주어 봐요.","그래서 면 수 = 변의 수 + 1이에요."],"variant_rule":{"alt":[{"stem":"각기둥에서 모서리의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"변의 수 × 3","correct":true},{"t":"변의 수 + 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 2","mis":"M6-1-u2-X12"},{"t":"변의 수 + 1","mis":"M6-1-u2-X12"}],"explanation":["삼각기둥, 사각기둥, 오각기둥의 모서리 수를 세어 표로 늘어놓아요.","9개, 12개, 15개 — 변의 수 3, 4, 5와 견주어 봐요.","그래서 모서리 수 = 변의 수 × 3이에요."]},{"stem":"각뿔에서 꼭짓점의 수를 한 밑면의 변의 수로 나타낸 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"변의 수 + 1","correct":true},{"t":"변의 수 + 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 2","mis":"M6-1-u2-X12"},{"t":"변의 수 × 3","mis":"M6-1-u2-X12"}],"explanation":["삼각뿔, 사각뿔, 오각뿔의 꼭짓점 수를 세어 표로 늘어놓아요.","4개, 5개, 6개 — 변의 수 3, 4, 5와 견주어 봐요.","그래서 꼭짓점 수 = 변의 수 + 1이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#8','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'ox','auto','십각기둥의 모서리는 30개예요.',ARRAY['M6-1-u2-X12']::text[],true,'{"seq":8,"concept":"M6-1-u2-C7","difficulty":2,"kind":"ox","stem":"십각기둥의 모서리는 30개예요.","answer":"O","reason_options":[{"t":"변의 수 10의 3배라 10 × 3 = 30개이기 때문에","correct":true},{"t":"십각기둥이니 10개의 3배를 빼기 때문에","mis":"M6-1-u2-X12"}],"mis":"M6-1-u2-X12","explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"십각뿔의 꼭짓점은 10개예요.","answer":"X","reason_options":[{"t":"밑면의 꼭짓점 10개에 각뿔의 꼭짓점 1개를 더해 11개이기 때문에","correct":true},{"t":"각뿔의 꼭짓점은 세지 않기 때문에","mis":"M6-1-u2-X10"}],"explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."]},{"stem":"각뿔의 모서리의 수는 언제나 짝수예요.","answer":"O","reason_options":[{"t":"모서리의 수가 변의 수의 2배이기 때문에","correct":true},{"t":"각뿔의 면이 짝수이기 때문에","mis":"M6-1-u2-X12"}],"explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#9','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',2,'sa','auto','밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 21개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 21개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 21개이니 한 밑면의 변은 7개예요.","같은 밑면의 각뿔은 칠각뿔이에요.","밑면의 변 7개와 옆 모서리 7개 — 7 × 2 = 14개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 12개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 12개이니 한 밑면의 변은 6개예요.","같은 밑면의 각뿔은 육각뿔이에요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요."]},{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 면이 11개일 때, 각뿔의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["각기둥의 면 수 = 변의 수 + 2 — 11개이니 한 밑면의 변은 9개예요.","같은 밑면의 각뿔은 구각뿔이에요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_basic#10','math',6,1,'u2','L08','g6_1_math_u2_L08_basic','lesson_basic','M6-1-u2-C7',3,'match','auto','입체도형과 알맞은 수를 이으세요.','{}'::text[],true,'{"seq":10,"concept":"M6-1-u2-C7","difficulty":3,"kind":"match","stem":"입체도형과 알맞은 수를 이으세요.","pairs":[{"l":"십각기둥","r":"면 12개"},{"l":"십각뿔","r":"모서리 20개"},{"l":"팔각기둥","r":"꼭짓점 16개"}],"mis":"M6-1-u2-X12","explanation":["각기둥은 면 +2·꼭짓점 ×2·모서리 ×3이에요.","각뿔은 면 +1·꼭짓점 +1·모서리 ×2예요.","십각기둥 면 12개, 십각뿔 모서리 20개, 팔각기둥 꼭짓점 16개예요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 입체도형과 알맞은 수를 이으세요.","pairs":[{"l":"구각뿔","r":"면 10개"},{"l":"칠각기둥","r":"모서리 21개"},{"l":"십이각뿔","r":"꼭짓점 13개"}],"explanation":["각기둥은 면 +2·꼭짓점 ×2·모서리 ×3이에요.","각뿔은 면 +1·꼭짓점 +1·모서리 ×2예요.","구각뿔 면 10개, 칠각기둥 모서리 21개, 십이각뿔 꼭짓점 13개예요."]},{"stem":"이번에는 다른 보기예요. 입체도형과 알맞은 수를 이으세요.","pairs":[{"l":"육각기둥","r":"면 8개"},{"l":"십일각뿔","r":"모서리 22개"},{"l":"오각기둥","r":"꼭짓점 10개"}],"explanation":["각기둥은 면 +2·꼭짓점 ×2·모서리 ×3이에요.","각뿔은 면 +1·꼭짓점 +1·모서리 ×2예요.","육각기둥 면 8개, 십일각뿔 모서리 22개, 오각기둥 꼭짓점 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#1','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',2,'mc','auto','어떤 각뿔의 모서리가 16개예요. 이 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":1,"concept":"M6-1-u2-C7","difficulty":2,"kind":"mc","stem":"어떤 각뿔의 모서리가 16개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"팔각뿔","correct":true},{"t":"십육각뿔","mis":"M6-1-u2-X04"},{"t":"팔각기둥","mis":"M6-1-u2-X11"},{"t":"구각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요.","한 밑면의 변이 8개라 이름은 팔각뿔이에요."],"variant_rule":{"alt":[{"stem":"어떤 각뿔의 면이 9개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"팔각뿔","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X04"},{"t":"팔각기둥","mis":"M6-1-u2-X11"},{"t":"칠각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","밑면 1개와 옆면 8개 — 8 + 1 = 9개예요.","한 밑면의 변이 8개라 이름은 팔각뿔이에요."]},{"stem":"어떤 각기둥의 꼭짓점이 28개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"십사각기둥","correct":true},{"t":"십사각뿔","mis":"M6-1-u2-X11"},{"t":"십오각기둥","mis":"M6-1-u2-X12"},{"t":"십삼각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 꼭짓점 14개가 위아래로 짝을 이뤄 — 14 × 2 = 28개예요.","한 밑면의 변이 14개라 이름은 십사각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#2','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',2,'sa','auto','밑면이 오각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"밑면이 오각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요.","밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 5 + 1 = 6개예요.","차는 10 − 6 = 4개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 팔각형인 각기둥과 각뿔이 있어요. 두 입체도형의 모서리 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["위 밑면 8개, 아래 밑면 8개, 옆 모서리 8개 — 8 × 3 = 24개예요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요.","차는 24 − 16 = 8개예요."]},{"stem":"밑면이 칠각형인 각기둥과 각뿔이 있어요. 두 입체도형의 면 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["밑면 2개와 옆면 7개 — 7 + 2 = 9개예요.","밑면 1개와 옆면 7개 — 7 + 1 = 8개예요.","차는 9 − 8 = 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#3','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'mc','auto','각기둥의 꼭짓점의 수가 한 밑면의 변의 수의 2배인 까닭은 무엇인가요?',ARRAY['M6-1-u2-X12','M6-1-u2-X10']::text[],true,'{"seq":3,"concept":"M6-1-u2-C7","difficulty":3,"kind":"mc","stem":"각기둥의 꼭짓점의 수가 한 밑면의 변의 수의 2배인 까닭은 무엇인가요?","options":[{"t":"밑면이 2개라 꼭짓점이 위아래로 짝을 이루기 때문에","correct":true},{"t":"옆면이 직사각형이기 때문에","mis":"M6-1-u2-X12"},{"t":"면이 2개 더 있기 때문에","mis":"M6-1-u2-X12"},{"t":"밑면이 1개이기 때문에","mis":"M6-1-u2-X10"}],"explanation":["규칙은 외우는 것이 아니라 세는 방법에서 나와요.","각기둥은 밑면이 2개라 위아래로 짝을 이루고, 각뿔은 밑면 1개에 위의 한 점이 더해져요.","그래서 답은 「밑면이 2개라 꼭짓점이 위아래로 짝을 이루기 때문에」예요."],"variant_rule":{"alt":[{"stem":"각뿔의 꼭짓점의 수가 한 밑면의 변의 수보다 1 큰 까닭은 무엇인가요?","options":[{"t":"밑면의 꼭짓점에 위의 한 점(각뿔의 꼭짓점)이 더해지기 때문에","correct":true},{"t":"밑면이 1개이기 때문에","mis":"M6-1-u2-X12"},{"t":"옆면이 삼각형이라 1을 더하기 때문에","mis":"M6-1-u2-X12"},{"t":"밑면이 2개이기 때문에","mis":"M6-1-u2-X10"}],"explanation":["규칙은 외우는 것이 아니라 세는 방법에서 나와요.","각기둥은 밑면이 2개라 위아래로 짝을 이루고, 각뿔은 밑면 1개에 위의 한 점이 더해져요.","그래서 답은 「밑면의 꼭짓점에 위의 한 점(각뿔의 꼭짓점)이 더해지기 때문에」예요."]},{"stem":"각기둥의 모서리의 수가 한 밑면의 변의 수의 3배인 까닭은 무엇인가요?","options":[{"t":"위 밑면·아래 밑면·옆의 모서리가 변의 수만큼씩 세 묶음이기 때문에","correct":true},{"t":"옆면이 3개씩 있기 때문에","mis":"M6-1-u2-X12"},{"t":"꼭짓점마다 모서리가 1개씩이기 때문에","mis":"M6-1-u2-X12"},{"t":"밑면이 3개이기 때문에","mis":"M6-1-u2-X08"}],"explanation":["규칙은 외우는 것이 아니라 세는 방법에서 나와요.","각기둥은 밑면이 2개라 위아래로 짝을 이루고, 각뿔은 밑면 1개에 위의 한 점이 더해져요.","그래서 답은 「위 밑면·아래 밑면·옆의 모서리가 변의 수만큼씩 세 묶음이기 때문에」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#4','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'sa','auto','어떤 각뿔의 면이 10개예요. 이 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"어떤 각뿔의 면이 10개예요. 이 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["각뿔의 면 수 = 변의 수 + 1 — 한 밑면의 변은 9개예요.","이 입체도형은 구각뿔이에요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"어떤 각기둥의 모서리가 33개예요. 이 각기둥의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 한 밑면의 변은 11개예요.","이 입체도형은 십일각기둥이에요.","한 밑면의 꼭짓점 11개가 위아래로 짝을 이뤄 — 11 × 2 = 22개예요."]},{"stem":"어떤 각기둥의 꼭짓점이 24개예요. 이 각기둥의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 한 밑면의 변은 12개예요.","이 입체도형은 십이각기둥이에요.","밑면 2개와 옆면 12개 — 12 + 2 = 14개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#5','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'ox','auto','각기둥의 면의 수는 언제나 꼭짓점의 수보다 많아요.',ARRAY['M6-1-u2-X12']::text[],true,'{"seq":5,"concept":"M6-1-u2-C7","difficulty":3,"kind":"ox","stem":"각기둥의 면의 수는 언제나 꼭짓점의 수보다 많아요.","answer":"X","reason_options":[{"t":"삼각기둥만 봐도 면 5개, 꼭짓점 6개라 꼭짓점이 더 많기 때문에","correct":true},{"t":"각기둥은 면이 가장 많기 때문에","mis":"M6-1-u2-X12"}],"mis":"M6-1-u2-X12","explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."],"variant_rule":{"alt":[{"stem":"꼭짓점이 24개인 각기둥은 십이각기둥이에요.","answer":"O","reason_options":[{"t":"꼭짓점은 변의 수의 2배라 변이 12개이기 때문에","correct":true},{"t":"꼭짓점의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."]},{"stem":"모서리가 16개인 각뿔은 팔각뿔이에요.","answer":"O","reason_options":[{"t":"모서리는 변의 수의 2배라 변이 8개이기 때문에","correct":true},{"t":"모서리의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥 — 면 = 변의 수 + 2, 꼭짓점 = 변의 수 × 2, 모서리 = 변의 수 × 3이에요.","각뿔 — 면 = 변의 수 + 1, 꼭짓점 = 변의 수 + 1, 모서리 = 변의 수 × 2예요.","규칙으로 하나하나 세지 않고 구할 수 있어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#6','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'error','auto','건축가 서호가 육각기둥과 육각뿔을 그려 놓고 친구들과 수를 구했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X12','M6-1-u2-X14']::text[],true,'{"seq":6,"concept":"M6-1-u2-C7","difficulty":3,"kind":"error","stem":"건축가 서호가 육각기둥과 육각뿔을 그려 놓고 친구들과 수를 구했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「육각뿔의 모서리는 18개야.」","correct":true,"mis_target":"M6-1-u2-X12"},{"t":"이현 — 「육각기둥의 꼭짓점은 12개야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「육각뿔의 면은 7개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요.","준희는 각기둥의 모서리 규칙(×3)을 각뿔에 잘못 썼어요."],"variant_rule":{"alt":[{"stem":"건축가 서호가 팔각기둥과 팔각뿔을 그려 놓고 친구들과 수를 구했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「팔각뿔의 모서리는 24개야.」","correct":true,"mis_target":"M6-1-u2-X12"},{"t":"수아 — 「팔각기둥의 꼭짓점은 16개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「팔각뿔의 면은 9개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 8개가 위아래로 짝을 이뤄 — 8 × 2 = 16개예요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요.","서호는 각기둥의 모서리 규칙(×3)을 각뿔에 잘못 썼어요."]},{"stem":"건축가 서호가 오각기둥과 오각뿔을 그려 놓고 친구들과 수를 구했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「오각뿔의 모서리는 15개야.」","correct":true,"mis_target":"M6-1-u2-X12"},{"t":"나린 — 「오각기둥의 꼭짓점은 10개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「오각뿔의 면은 6개야.」","mis":"M6-1-u2-X14"}],"explanation":["한 밑면의 꼭짓점 5개가 위아래로 짝을 이뤄 — 5 × 2 = 10개예요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요.","가온은 각기둥의 모서리 규칙(×3)을 각뿔에 잘못 썼어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#7','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',3,'sa','auto','밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 36개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 36개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["13"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 36개이니 한 밑면의 변은 12개예요.","같은 밑면의 각뿔은 십이각뿔이에요.","밑면 1개와 옆면 12개 — 12 + 1 = 13개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 30개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 30개이니 한 밑면의 변은 15개예요.","같은 밑면의 각뿔은 십오각뿔이에요.","밑면의 변 15개와 옆 모서리 15개 — 15 × 2 = 30개예요."]},{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 면이 15개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["26"],"explanation":["각기둥의 면 수 = 변의 수 + 2 — 15개이니 한 밑면의 변은 13개예요.","같은 밑면의 각뿔은 십삼각뿔이에요.","밑면의 변 13개와 옆 모서리 13개 — 13 × 2 = 26개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#8','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',4,'sa','auto','칠각기둥의 (꼭짓점의 수) + (면의 수) − (모서리의 수)는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C7","difficulty":4,"kind":"sa","stem":"칠각기둥의 (꼭짓점의 수) + (면의 수) − (모서리의 수)는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["칠각기둥의 꼭짓점은 14개, 면은 9개, 모서리는 21개예요.","14 + 9 − 21 = 2예요.","각기둥도 각뿔도 언제나 2가 나와요 — 신기한 규칙이에요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"구각뿔의 (꼭짓점의 수) + (면의 수) − (모서리의 수)는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["구각뿔의 꼭짓점은 10개, 면은 10개, 모서리는 18개예요.","10 + 10 − 18 = 2예요.","각기둥도 각뿔도 언제나 2가 나와요 — 신기한 규칙이에요."]},{"stem":"십이각기둥의 (꼭짓점의 수) + (면의 수) − (모서리의 수)는 얼마인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["십이각기둥의 꼭짓점은 24개, 면은 14개, 모서리는 36개예요.","24 + 14 − 36 = 2예요.","각기둥도 각뿔도 언제나 2가 나와요 — 신기한 규칙이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#9','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',4,'sa','auto','모서리 수가 50개를 넘지 않는 각기둥 가운데 밑면의 변이 가장 많은 것은 밑면의 변이 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M6-1-u2-C7","difficulty":4,"kind":"sa","stem":"모서리 수가 50개를 넘지 않는 각기둥 가운데 밑면의 변이 가장 많은 것은 밑면의 변이 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","변이 16개이면 48개, 17개이면 51개예요.","50개를 넘지 않으니 밑면의 변은 16개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"모서리 수가 35개를 넘지 않는 각뿔 가운데 밑면의 변이 가장 많은 것은 밑면의 변이 몇 개인가요? 숫자로 쓰세요.","answer":["17"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","변이 17개이면 34개, 18개이면 36개예요.","35개를 넘지 않으니 밑면의 변은 17개예요."]},{"stem":"꼭짓점 수가 45개를 넘지 않는 각기둥 가운데 밑면의 변이 가장 많은 것은 밑면의 변이 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","변이 22개이면 44개, 23개이면 46개예요.","45개를 넘지 않으니 밑면의 변은 22개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_L08_challenge#10','math',6,1,'u2','L08','g6_1_math_u2_L08_challenge','lesson_challenge','M6-1-u2-C7',4,'essay','teacher','각기둥의 꼭짓점의 수는 한 밑면의 변의 수의 2배이고, 각뿔의 꼭짓점의 수는 한 밑면의 변의 수에 1을 더한 수예요. 두 규칙이 왜 다른지 세는 방법으로 설명하고, 십각기둥과 십각뿔의 꼭짓점의 수를 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M6-1-u2-C7","difficulty":4,"kind":"essay","stem":"각기둥의 꼭짓점의 수는 한 밑면의 변의 수의 2배이고, 각뿔의 꼭짓점의 수는 한 밑면의 변의 수에 1을 더한 수예요. 두 규칙이 왜 다른지 세는 방법으로 설명하고, 십각기둥과 십각뿔의 꼭짓점의 수를 구해 보세요.","answer_guide":{"answer":"예: 각기둥은 밑면이 2개라 한 밑면의 꼭짓점이 위아래로 짝을 이루므로 2배가 된다. 각뿔은 밑면이 1개이고 옆면이 모두 만나는 각뿔의 꼭짓점이 위에 한 점 더 있으므로 1을 더한다. 십각기둥의 꼭짓점은 10 × 2 = 20개, 십각뿔의 꼭짓점은 10 + 1 = 11개이다.","scoring_points":["각기둥은 밑면이 2개라 2배라고 설명했는가","각뿔은 위의 한 점을 더한다고 설명했는가","20개와 11개를 구했는가"]},"explanation":["각기둥은 위아래로 짝 — 2배예요.","각뿔은 위의 한 점 — 1을 더해요.","십각기둥 20개, 십각뿔 11개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#1','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C1',1,'mc','auto','두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?',ARRAY['M6-1-u2-X11']::text[],true,'{"seq":1,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"밑면","mis":"M6-1-u2-X11"},{"t":"옆면","mis":"M6-1-u2-X11"},{"t":"각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「각기둥」이에요."],"variant_rule":{"alt":[{"stem":"각기둥에서 서로 평행하고 합동인 두 면을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「밑면」이에요."]},{"stem":"두 밑면과 만나는 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「옆면」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#2','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C1',1,'mc','auto','각기둥의 옆면은 모두 어떤 도형인가요?',ARRAY['M6-1-u2-X03','M6-1-u2-X01']::text[],true,'{"seq":2,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"각기둥의 옆면은 모두 어떤 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「직사각형」이에요."],"variant_rule":{"alt":[{"stem":"각기둥의 두 밑면은 서로 어떤 관계인가요?","options":[{"t":"서로 평행하고 합동이에요","correct":true},{"t":"서로 수직이에요","mis":"M6-1-u2-X01"},{"t":"평행하지만 크기가 달라요","mis":"M6-1-u2-X02"},{"t":"한 꼭짓점에서 만나요","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「서로 평행하고 합동이에요」예요."]},{"stem":"각뿔의 옆면은 모두 어떤 도형인가요?","options":[{"t":"삼각형","correct":true},{"t":"직사각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X03"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#3','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C2',1,'mc','auto','밑면이 칠각형인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":3,"concept":"M6-1-u2-C2","difficulty":1,"kind":"mc","stem":"밑면이 칠각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"칠각기둥","correct":true},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X04"},{"t":"십사각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 칠각형이에요.","그래서 이름은 칠각기둥이에요."],"variant_rule":{"alt":[{"stem":"밑면이 오각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X04"},{"t":"십각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 오각형이에요.","그래서 이름은 오각기둥이에요."]},{"stem":"밑면이 구각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X04"},{"t":"십팔각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 구각형이에요.","그래서 이름은 구각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#4','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C6',1,'mc','auto','밑면이 팔각형인 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":4,"concept":"M6-1-u2-C6","difficulty":1,"kind":"mc","stem":"밑면이 팔각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"팔각뿔","correct":true},{"t":"팔각기둥","mis":"M6-1-u2-X11"},{"t":"구각뿔","mis":"M6-1-u2-X04"},{"t":"십육각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 팔각형이에요.","그래서 이름은 팔각뿔이에요."],"variant_rule":{"alt":[{"stem":"밑면이 칠각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"칠각뿔","correct":true},{"t":"칠각기둥","mis":"M6-1-u2-X11"},{"t":"팔각뿔","mis":"M6-1-u2-X04"},{"t":"십사각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 칠각형이에요.","그래서 이름은 칠각뿔이에요."]},{"stem":"밑면이 오각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"오각뿔","correct":true},{"t":"오각기둥","mis":"M6-1-u2-X11"},{"t":"육각뿔","mis":"M6-1-u2-X04"},{"t":"십각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 오각형이에요.","그래서 이름은 오각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#5','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C2',1,'sa','auto','육각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C2","difficulty":1,"kind":"sa","stem":"육각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["육각기둥의 밑면은 육각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"오각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["오각기둥의 밑면은 오각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 5개 — 5 + 2 = 7개예요."]},{"stem":"칠각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["칠각기둥의 밑면은 칠각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#6','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C6',1,'sa','auto','칠각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C6","difficulty":1,"kind":"sa","stem":"칠각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["칠각뿔의 밑면은 칠각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"팔각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["팔각뿔의 밑면은 팔각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 8개와 각뿔의 꼭짓점 1개 — 8 + 1 = 9개예요."]},{"stem":"오각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["오각뿔의 밑면은 오각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#7','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C3',1,'mc','auto','각기둥의 전개도에서 점선은 무엇을 나타내나요?',ARRAY['M6-1-u2-X07']::text[],true,'{"seq":7,"concept":"M6-1-u2-C3","difficulty":1,"kind":"mc","stem":"각기둥의 전개도에서 점선은 무엇을 나타내나요?","options":[{"t":"잘리지 않고 접히는 모서리","correct":true},{"t":"잘린 모서리","mis":"M6-1-u2-X07"},{"t":"밑면의 둘레","mis":"M6-1-u2-X07"},{"t":"옆면의 넓이","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘리지 않고 접히는 모서리」예요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도에서 실선은 무엇을 나타내나요?","options":[{"t":"잘린 모서리","correct":true},{"t":"잘리지 않고 접히는 모서리","mis":"M6-1-u2-X07"},{"t":"각기둥의 높이","mis":"M6-1-u2-X06"},{"t":"밑면의 대각선","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘린 모서리」예요."]},{"stem":"각기둥의 전개도는 어떤 그림인가요?","options":[{"t":"모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림","correct":true},{"t":"면을 하나씩 모두 떼어 늘어놓은 그림","mis":"M6-1-u2-X07"},{"t":"각기둥을 위에서 내려다본 그림","mis":"M6-1-u2-X07"},{"t":"밑면만 따라 그린 그림","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#8','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C4',1,'sa','auto','높이가 8 cm인 육각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C4","difficulty":1,"kind":"sa","stem":"높이가 8 cm인 육각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 8 cm로 그려요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"높이가 12 cm인 오각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 12 cm로 그려요."]},{"stem":"높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["11"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 11 cm로 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#9','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C1',2,'mc','auto','육각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 육각형은 무엇인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X05']::text[],true,'{"seq":9,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"육각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 육각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 육각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 육각형은 여전히 밑면이에요."],"variant_rule":{"alt":[{"stem":"오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 오각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 오각형은 여전히 밑면이에요."]},{"stem":"팔각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 팔각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 팔각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 팔각형은 여전히 밑면이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#10','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C1',2,'mc','auto','「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":10,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평행한 두 면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행한 두 오각형의 크기가 다른 입체도형」을 이 조건에 하나씩 대어 봐요.","평행한 두 면이 서로 합동이 아니기 때문에 각기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」을 이 조건에 하나씩 대어 봐요.","옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에 각기둥이 아니에요."]},{"stem":"「밑면이 원이고 뾰족한 점이 있는 고깔」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 다각형이 아니기 때문에","correct":true},{"t":"옆면이 삼각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「밑면이 원이고 뾰족한 점이 있는 고깔」을 이 조건에 대어 봐요.","밑면이 다각형이 아니기 때문에 각뿔이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#11','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C2',2,'sa','auto','문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 6 cm, 8 cm, 10 cm이고 옆면과 옆면이 만나는 모서리가 9 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 6 cm, 8 cm, 10 cm이고 옆면과 옆면이 만나는 모서리가 9 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 6 cm, 8 cm, 10 cm는 높이가 아니에요 — 높이는 9 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 5 cm, 12 cm, 13 cm이고 옆면과 옆면이 만나는 모서리가 4 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 5 cm, 12 cm, 13 cm는 높이가 아니에요 — 높이는 4 cm예요."]},{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 9 cm, 12 cm, 15 cm이고 옆면과 옆면이 만나는 모서리가 7 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 9 cm, 12 cm, 15 cm는 높이가 아니에요 — 높이는 7 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#12','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C6',2,'sa','auto','육각뿔 모양 건축물이 있어요. 옆 모서리가 13 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 12 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"육각뿔 모양 건축물이 있어요. 옆 모서리가 13 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 12 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 13 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 12 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"사각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 10 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 8 cm예요."]},{"stem":"오각뿔 모양 건축물이 있어요. 옆 모서리가 25 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 24 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 25 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 24 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#13','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C3',2,'mc','auto','칠각형 2개와 직사각형 7개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":13,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"칠각형 2개와 직사각형 7개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"칠각기둥","correct":true},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X08"},{"t":"십사각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 칠각형 2개가 밑면이 돼요.","직사각형 7개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 칠각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"구각형 2개와 직사각형 9개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X08"},{"t":"십팔각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 구각형 2개가 밑면이 돼요.","직사각형 9개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 구각기둥이 돼요."]},{"stem":"오각형 2개와 직사각형 5개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X08"},{"t":"십각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 오각형 2개가 밑면이 돼요.","직사각형 5개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 오각기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#14','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C4',2,'sa','auto','밑면의 변이 5 cm, 12 cm, 13 cm인 삼각기둥의 높이가 7 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u2-C4","difficulty":2,"kind":"sa","stem":"밑면의 변이 5 cm, 12 cm, 13 cm인 삼각기둥의 높이가 7 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","5 + 12 + 13 = 30 — 가로는 30 cm예요(높이 7 cm는 세로예요)."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 9 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","3 + 4 + 5 = 12 — 가로는 12 cm예요(높이 9 cm는 세로예요)."]},{"stem":"밑면의 변이 4 cm, 5 cm, 6 cm, 7 cm인 사각기둥의 높이가 8 cm예요. 전개도에서 옆면 4개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","4 + 5 + 6 + 7 = 22 — 가로는 22 cm예요(높이 8 cm는 세로예요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#15','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C7',2,'sa','auto','십이각기둥의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"십이각기둥의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["36"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","한 밑면의 변은 12개예요.","위 밑면 12개, 아래 밑면 12개, 옆 모서리 12개 — 12 × 3 = 36개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"십오각뿔의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["30"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","한 밑면의 변은 15개예요.","밑면의 변 15개와 옆 모서리 15개 — 15 × 2 = 30개예요."]},{"stem":"이십각기둥의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["40"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 변은 20개예요.","한 밑면의 꼭짓점 20개가 위아래로 짝을 이뤄 — 20 × 2 = 40개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#16','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C5',2,'ox','auto','각뿔의 옆면은 모두 직사각형이에요.',ARRAY['M6-1-u2-X03']::text[],true,'{"seq":16,"concept":"M6-1-u2-C5","difficulty":2,"kind":"ox","stem":"각뿔의 옆면은 모두 직사각형이에요.","answer":"X","reason_options":[{"t":"옆면은 밑면의 변과 한 점을 이은 삼각형이기 때문에","correct":true},{"t":"각기둥처럼 옆면이 밑면과 수직이기 때문에","mis":"M6-1-u2-X03"}],"mis":"M6-1-u2-X03","explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면 하나가 밑면, 삼각형들이 옆면이에요.","원뿔은 밑면이 원이라 각뿔이 아니에요."],"variant_rule":{"alt":[{"stem":"오각뿔의 꼭짓점은 5개예요.","answer":"X","reason_options":[{"t":"밑면의 꼭짓점 5개에 각뿔의 꼭짓점 1개를 더해 6개이기 때문에","correct":true},{"t":"밑면이 오각형이라 꼭짓점도 5개이기 때문에","mis":"M6-1-u2-X10"}],"explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."]},{"stem":"각기둥의 이름은 옆면의 모양으로 정해요.","answer":"X","reason_options":[{"t":"옆면은 모두 직사각형이고 이름은 밑면의 모양으로 정하기 때문에","correct":true},{"t":"옆면의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#17','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C7',3,'mc','auto','어떤 각기둥의 꼭짓점이 20개예요. 이 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X12','M6-1-u2-X11']::text[],true,'{"seq":17,"concept":"M6-1-u2-C7","difficulty":3,"kind":"mc","stem":"어떤 각기둥의 꼭짓점이 20개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"십각기둥","correct":true},{"t":"이십각기둥","mis":"M6-1-u2-X04"},{"t":"십구각뿔","mis":"M6-1-u2-X12"},{"t":"십각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 꼭짓점 10개가 위아래로 짝을 이뤄 — 10 × 2 = 20개예요.","한 밑면의 변이 10개라 이름은 십각기둥이에요."],"variant_rule":{"alt":[{"stem":"어떤 각뿔의 모서리가 18개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"구각뿔","correct":true},{"t":"십팔각뿔","mis":"M6-1-u2-X04"},{"t":"구각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요.","한 밑면의 변이 9개라 이름은 구각뿔이에요."]},{"stem":"어떤 각기둥의 모서리가 24개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"팔각기둥","correct":true},{"t":"이십사각기둥","mis":"M6-1-u2-X04"},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","위 밑면 8개, 아래 밑면 8개, 옆 모서리 8개 — 8 × 3 = 24개예요.","한 밑면의 변이 8개라 이름은 팔각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#18','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C7',3,'sa','auto','밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 24개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 24개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 24개이니 한 밑면의 변은 8개예요.","같은 밑면의 각뿔은 팔각뿔이에요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 20개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 20개이니 한 밑면의 변은 10개예요.","같은 밑면의 각뿔은 십각뿔이에요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요."]},{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 면이 8개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각기둥의 면 수 = 변의 수 + 2 — 8개이니 한 밑면의 변은 6개예요.","같은 밑면의 각뿔은 육각뿔이에요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#19','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C3',3,'mc','auto','「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X08']::text[],true,'{"seq":19,"concept":"M6-1-u2-C3","difficulty":3,"kind":"mc","stem":"「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","correct":true},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 옆면의 수가 한 밑면의 변의 수와 다르기 때문에 전개도가 아니에요."],"variant_rule":{"alt":[{"stem":"「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 1개뿐이기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 밑면이 1개뿐이기 때문에 전개도가 아니에요."]},{"stem":"「오각형 2개와 직사각형 5개가 이어졌는데, 두 오각형이 같은 쪽에 붙어 접으면 겹치는 그림」은 오각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X13"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X13"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X13"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 접으면 두 밑면이 겹쳐 맞닿지 않기 때문에 전개도가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#20','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C1',3,'error','auto','각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X14']::text[],true,'{"seq":20,"concept":"M6-1-u2-C1","difficulty":3,"kind":"error","stem":"각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「각기둥을 옆으로 눕히면 바닥에 닿은 옆면이 밑면이 돼.」","correct":true,"mis_target":"M6-1-u2-X01"},{"t":"이현 — 「각기둥의 옆면은 모두 직사각형이야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥을 눕혀도 서로 평행하고 합동인 두 면이 밑면이에요.","바닥에 닿은 면이 직사각형 옆면이면 그것은 여전히 옆면이에요.","준희는 밑면을 위치로 잘못 정했어요."],"variant_rule":{"alt":[{"stem":"각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「각기둥의 높이는 밑면의 가장 긴 변의 길이야.」","correct":true,"mis_target":"M6-1-u2-X06"},{"t":"수아 — 「각기둥의 밑면은 2개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「각기둥의 밑면은 옆면과 수직으로 만나.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 변은 밑면 안의 선분이라 높이가 될 수 없어요.","서호는 높이를 잘못 말했어요."]},{"stem":"오각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꼭짓점이 5개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"나린 — 「모서리가 10개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「옆면이 5개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 5 + 1 = 6개예요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요.","가온은 각뿔의 꼭짓점을 빠뜨렸어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#21','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C7',3,'sa','auto','밑면이 육각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면이 육각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요.","밑면의 꼭짓점 6개와 각뿔의 꼭짓점 1개 — 6 + 1 = 7개예요.","차는 12 − 7 = 5개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 구각형인 각기둥과 각뿔이 있어요. 두 입체도형의 모서리 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["위 밑면 9개, 아래 밑면 9개, 옆 모서리 9개 — 9 × 3 = 27개예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요.","차는 27 − 18 = 9개예요."]},{"stem":"밑면이 십각형인 각기둥과 각뿔이 있어요. 두 입체도형의 면 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["밑면 2개와 옆면 10개 — 10 + 2 = 12개예요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요.","차는 12 − 11 = 1개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#22','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C4',3,'mc','auto','밑면이 한 변이 5 cm인 정사각형이고 높이가 8 cm인 사각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":22,"concept":"M6-1-u2-C4","difficulty":3,"kind":"mc","stem":"밑면이 한 변이 5 cm인 정사각형이고 높이가 8 cm인 사각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 5 cm, 세로 8 cm","correct":true},{"t":"가로 8 cm, 세로 20 cm","mis":"M6-1-u2-X09"},{"t":"가로 20 cm, 세로 8 cm","mis":"M6-1-u2-X09"},{"t":"가로 5 cm, 세로 5 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 5 cm예요.","옆면의 세로는 각기둥의 높이와 같아 8 cm예요.","그래서 옆면 하나는 「가로 5 cm, 세로 8 cm」예요."],"variant_rule":{"alt":[{"stem":"밑면이 한 변이 3 cm인 정육각형이고 높이가 10 cm인 육각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 3 cm, 세로 10 cm","correct":true},{"t":"가로 10 cm, 세로 18 cm","mis":"M6-1-u2-X09"},{"t":"가로 18 cm, 세로 10 cm","mis":"M6-1-u2-X09"},{"t":"가로 3 cm, 세로 3 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 3 cm예요.","옆면의 세로는 각기둥의 높이와 같아 10 cm예요.","그래서 옆면 하나는 「가로 3 cm, 세로 10 cm」예요."]},{"stem":"밑면이 한 변이 6 cm인 정오각형이고 높이가 7 cm인 오각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 6 cm, 세로 7 cm","correct":true},{"t":"가로 7 cm, 세로 30 cm","mis":"M6-1-u2-X09"},{"t":"가로 30 cm, 세로 7 cm","mis":"M6-1-u2-X09"},{"t":"가로 6 cm, 세로 6 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 6 cm예요.","옆면의 세로는 각기둥의 높이와 같아 7 cm예요.","그래서 옆면 하나는 「가로 6 cm, 세로 7 cm」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#23','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C2',4,'sa','auto','밑면이 한 변이 4 cm인 정사각형이고 높이가 6 cm인 사각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u2-C2","difficulty":4,"kind":"sa","stem":"밑면이 한 변이 4 cm인 정사각형이고 높이가 6 cm인 사각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["두 밑면의 변은 4개씩 — 4 × 2 = 8개이고 모두 4 cm예요.","옆 모서리는 4개이고 모두 높이와 같은 6 cm예요.","8 × 4 + 4 × 6 = 56 — 모두 56 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"밑면이 한 변이 3 cm인 정오각형이고 옆 모서리가 모두 9 cm인 오각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["밑면의 변은 5개이고 모두 3 cm예요.","옆 모서리도 5개이고 모두 9 cm예요.","5 × 3 + 5 × 9 = 60 — 모두 60 cm예요."]},{"stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 7 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 3 + 4 + 5 = 12 cm예요.","세로는 높이 7 cm예요.","넓이는 12 × 7 = 84 cm²예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#24','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C1',4,'essay','teacher','각기둥의 밑면은 「아래에 있는 면」일까요? 오각기둥을 옆으로 눕힌 경우를 들어 밑면을 찾는 방법을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u2-C1","difficulty":4,"kind":"essay","stem":"각기둥의 밑면은 「아래에 있는 면」일까요? 오각기둥을 옆으로 눕힌 경우를 들어 밑면을 찾는 방법을 설명해 보세요.","answer_guide":{"answer":"예: 밑면은 아래에 있는 면이 아니다. 오각기둥을 옆으로 눕히면 바닥에는 직사각형 옆면이 닿지만, 밑면은 여전히 서로 평행하고 합동인 두 오각형이다. 밑면은 위치가 아니라 평행하고 합동인 두 면이라는 관계로 찾는다.","scoring_points":["밑면은 아래 면이 아니라고 답했는가","눕혀도 두 오각형이 밑면이라고 썼는가","평행·합동이라는 관계로 찾는다고 설명했는가"]},"explanation":["눕히면 바닥에는 옆면이 닿아요.","밑면은 여전히 두 오각형이에요.","밑면은 관계로 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_a#25','math',6,1,'u2','','g6_1_math_u2_review_a','unit_review','M6-1-u2-C3',4,'essay','teacher','어떤 각기둥의 전개도에 옆면이 7개 그려져 있어요. 이 각기둥의 이름을 쓰고, 전개도에 그려진 면의 수와 각기둥의 모서리의 수를 구하는 과정을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u2-C3","difficulty":4,"kind":"essay","stem":"어떤 각기둥의 전개도에 옆면이 7개 그려져 있어요. 이 각기둥의 이름을 쓰고, 전개도에 그려진 면의 수와 각기둥의 모서리의 수를 구하는 과정을 설명해 보세요.","answer_guide":{"answer":"예: 옆면의 수는 한 밑면의 변의 수와 같으므로 밑면은 칠각형이고 이름은 칠각기둥이다. 전개도에는 밑면 2개와 옆면 7개가 있어 면은 7 + 2 = 9개이다. 모서리는 위 밑면 7개, 아래 밑면 7개, 옆 모서리 7개로 7 × 3 = 21개이다.","scoring_points":["옆면의 수 = 밑면의 변의 수로 칠각기둥을 찾았는가","면 9개를 구했는가","모서리 21개를 구했는가"]},"explanation":["옆면 7개 — 밑면은 칠각형이에요.","면은 7 + 2 = 9개예요.","모서리는 7 × 3 = 21개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#1','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C1',1,'mc','auto','각기둥에서 서로 평행하고 합동인 두 면을 무엇이라고 하나요?',ARRAY['M6-1-u2-X01']::text[],true,'{"seq":1,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"각기둥에서 서로 평행하고 합동인 두 면을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「밑면」이에요."],"variant_rule":{"alt":[{"stem":"두 밑면과 만나는 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「옆면」이에요."]},{"stem":"한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형을 무엇이라고 하나요?","options":[{"t":"각뿔","correct":true},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각기둥","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면이 밑면, 밑면과 만나는 삼각형이 옆면이에요.","그래서 답은 「각뿔」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#2','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C1',1,'mc','auto','각기둥의 두 밑면은 서로 어떤 관계인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X02','M6-1-u2-X11']::text[],true,'{"seq":2,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"각기둥의 두 밑면은 서로 어떤 관계인가요?","options":[{"t":"서로 평행하고 합동이에요","correct":true},{"t":"서로 수직이에요","mis":"M6-1-u2-X01"},{"t":"평행하지만 크기가 달라요","mis":"M6-1-u2-X02"},{"t":"한 꼭짓점에서 만나요","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「서로 평행하고 합동이에요」예요."],"variant_rule":{"alt":[{"stem":"각뿔의 옆면은 모두 어떤 도형인가요?","options":[{"t":"삼각형","correct":true},{"t":"직사각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X03"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."]},{"stem":"각뿔의 옆면은 모두 어디에서 만나나요?","options":[{"t":"한 점에서 모두 만나요","correct":true},{"t":"만나지 않아요","mis":"M6-1-u2-X11"},{"t":"밑면과 수직으로 만나요","mis":"M6-1-u2-X11"},{"t":"위쪽 밑면에서 만나요","mis":"M6-1-u2-X10"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#3','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C2',1,'mc','auto','밑면이 오각형인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":3,"concept":"M6-1-u2-C2","difficulty":1,"kind":"mc","stem":"밑면이 오각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X04"},{"t":"십각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 오각형이에요.","그래서 이름은 오각기둥이에요."],"variant_rule":{"alt":[{"stem":"밑면이 구각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X04"},{"t":"십팔각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 구각형이에요.","그래서 이름은 구각기둥이에요."]},{"stem":"밑면이 육각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"육각기둥","correct":true},{"t":"육각뿔","mis":"M6-1-u2-X11"},{"t":"팔각기둥","mis":"M6-1-u2-X04"},{"t":"십이각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 육각형이에요.","그래서 이름은 육각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#4','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C6',1,'mc','auto','밑면이 칠각형인 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":4,"concept":"M6-1-u2-C6","difficulty":1,"kind":"mc","stem":"밑면이 칠각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"칠각뿔","correct":true},{"t":"칠각기둥","mis":"M6-1-u2-X11"},{"t":"팔각뿔","mis":"M6-1-u2-X04"},{"t":"십사각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 칠각형이에요.","그래서 이름은 칠각뿔이에요."],"variant_rule":{"alt":[{"stem":"밑면이 오각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"오각뿔","correct":true},{"t":"오각기둥","mis":"M6-1-u2-X11"},{"t":"육각뿔","mis":"M6-1-u2-X04"},{"t":"십각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 오각형이에요.","그래서 이름은 오각뿔이에요."]},{"stem":"밑면이 구각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"구각뿔","correct":true},{"t":"구각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X04"},{"t":"십팔각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 구각형이에요.","그래서 이름은 구각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#5','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C2',1,'sa','auto','오각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C2","difficulty":1,"kind":"sa","stem":"오각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["오각기둥의 밑면은 오각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 5개 — 5 + 2 = 7개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"칠각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["칠각기둥의 밑면은 칠각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요."]},{"stem":"사각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["사각기둥의 밑면은 사각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#6','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C6',1,'sa','auto','팔각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C6","difficulty":1,"kind":"sa","stem":"팔각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["팔각뿔의 밑면은 팔각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 8개와 각뿔의 꼭짓점 1개 — 8 + 1 = 9개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"오각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["오각뿔의 밑면은 오각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요."]},{"stem":"구각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["구각뿔의 밑면은 구각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#7','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C3',1,'mc','auto','각기둥의 전개도에서 실선은 무엇을 나타내나요?',ARRAY['M6-1-u2-X07','M6-1-u2-X06']::text[],true,'{"seq":7,"concept":"M6-1-u2-C3","difficulty":1,"kind":"mc","stem":"각기둥의 전개도에서 실선은 무엇을 나타내나요?","options":[{"t":"잘린 모서리","correct":true},{"t":"잘리지 않고 접히는 모서리","mis":"M6-1-u2-X07"},{"t":"각기둥의 높이","mis":"M6-1-u2-X06"},{"t":"밑면의 대각선","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘린 모서리」예요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도는 어떤 그림인가요?","options":[{"t":"모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림","correct":true},{"t":"면을 하나씩 모두 떼어 늘어놓은 그림","mis":"M6-1-u2-X07"},{"t":"각기둥을 위에서 내려다본 그림","mis":"M6-1-u2-X07"},{"t":"밑면만 따라 그린 그림","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림」이에요."]},{"stem":"같은 사각기둥인데 전개도의 모양이 서로 다르게 나오는 까닭은 무엇인가요?","options":[{"t":"자르는 모서리가 달라져서","correct":true},{"t":"밑면의 크기가 달라져서","mis":"M6-1-u2-X13"},{"t":"높이가 달라져서","mis":"M6-1-u2-X13"},{"t":"옆면의 수가 달라져서","mis":"M6-1-u2-X08"}],"explanation":["전개도는 각기둥의 모서리를 잘라서 펼친 그림이에요.","어느 모서리를 자르느냐가 달라지면 펼쳐진 모양도 달라져요.","자른 자리가 다를 뿐 접으면 같은 각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#8','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C4',1,'sa','auto','높이가 12 cm인 오각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C4","difficulty":1,"kind":"sa","stem":"높이가 12 cm인 오각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 12 cm로 그려요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["11"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 11 cm로 그려요."]},{"stem":"높이가 5 cm인 칠각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 5 cm로 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#9','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C1',2,'mc','auto','오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X05']::text[],true,'{"seq":9,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 오각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 오각형은 여전히 밑면이에요."],"variant_rule":{"alt":[{"stem":"팔각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 팔각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 팔각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 팔각형은 여전히 밑면이에요."]},{"stem":"사각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 사각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 사각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 사각형은 여전히 밑면이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#10','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C1',2,'mc','auto','「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":10,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」을 이 조건에 하나씩 대어 봐요.","옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에 각기둥이 아니에요."],"variant_rule":{"alt":[{"stem":"「밑면이 원이고 뾰족한 점이 있는 고깔」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 다각형이 아니기 때문에","correct":true},{"t":"옆면이 삼각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「밑면이 원이고 뾰족한 점이 있는 고깔」을 이 조건에 대어 봐요.","밑면이 다각형이 아니기 때문에 각뿔이 아니에요."]},{"stem":"「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 삼각형이 아니기 때문에","correct":true},{"t":"밑면이 다각형이 아니기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」을 이 조건에 대어 봐요.","옆면이 삼각형이 아니기 때문에 각뿔이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#11','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C2',2,'sa','auto','문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 5 cm, 12 cm, 13 cm이고 옆면과 옆면이 만나는 모서리가 4 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 5 cm, 12 cm, 13 cm이고 옆면과 옆면이 만나는 모서리가 4 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 5 cm, 12 cm, 13 cm는 높이가 아니에요 — 높이는 4 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 9 cm, 12 cm, 15 cm이고 옆면과 옆면이 만나는 모서리가 7 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 9 cm, 12 cm, 15 cm는 높이가 아니에요 — 높이는 7 cm예요."]},{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 8 cm, 15 cm, 17 cm이고 옆면과 옆면이 만나는 모서리가 5 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 8 cm, 15 cm, 17 cm는 높이가 아니에요 — 높이는 5 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#12','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C6',2,'sa','auto','사각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"사각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 10 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 8 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"오각뿔 모양 건축물이 있어요. 옆 모서리가 25 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 24 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 25 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 24 cm예요."]},{"stem":"팔각뿔 모양 건축물이 있어요. 옆 모서리가 17 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 15 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 17 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 15 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#13','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C3',2,'mc','auto','구각형 2개와 직사각형 9개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":13,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"구각형 2개와 직사각형 9개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X08"},{"t":"십팔각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 구각형 2개가 밑면이 돼요.","직사각형 9개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 구각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"오각형 2개와 직사각형 5개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X08"},{"t":"십각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 오각형 2개가 밑면이 돼요.","직사각형 5개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 오각기둥이 돼요."]},{"stem":"팔각형 2개와 직사각형 8개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"팔각기둥","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X08"},{"t":"십육각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 팔각형 2개가 밑면이 돼요.","직사각형 8개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 팔각기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#14','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C4',2,'sa','auto','밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 9 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u2-C4","difficulty":2,"kind":"sa","stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 9 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","3 + 4 + 5 = 12 — 가로는 12 cm예요(높이 9 cm는 세로예요)."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면의 변이 4 cm, 5 cm, 6 cm, 7 cm인 사각기둥의 높이가 8 cm예요. 전개도에서 옆면 4개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","4 + 5 + 6 + 7 = 22 — 가로는 22 cm예요(높이 8 cm는 세로예요)."]},{"stem":"밑면의 변이 6 cm, 8 cm, 10 cm인 삼각기둥의 높이가 5 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","6 + 8 + 10 = 24 — 가로는 24 cm예요(높이 5 cm는 세로예요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#15','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C7',2,'sa','auto','십오각뿔의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"십오각뿔의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["30"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","한 밑면의 변은 15개예요.","밑면의 변 15개와 옆 모서리 15개 — 15 × 2 = 30개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"이십각기둥의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["40"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 변은 20개예요.","한 밑면의 꼭짓점 20개가 위아래로 짝을 이뤄 — 20 × 2 = 40개예요."]},{"stem":"십사각뿔의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","한 밑면의 변은 14개예요.","밑면 1개와 옆면 14개 — 14 + 1 = 15개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#16','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C6',2,'ox','auto','오각뿔의 꼭짓점은 5개예요.',ARRAY['M6-1-u2-X10']::text[],true,'{"seq":16,"concept":"M6-1-u2-C6","difficulty":2,"kind":"ox","stem":"오각뿔의 꼭짓점은 5개예요.","answer":"X","reason_options":[{"t":"밑면의 꼭짓점 5개에 각뿔의 꼭짓점 1개를 더해 6개이기 때문에","correct":true},{"t":"밑면이 오각형이라 꼭짓점도 5개이기 때문에","mis":"M6-1-u2-X10"}],"mis":"M6-1-u2-X10","explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."],"variant_rule":{"alt":[{"stem":"각기둥의 이름은 옆면의 모양으로 정해요.","answer":"X","reason_options":[{"t":"옆면은 모두 직사각형이고 이름은 밑면의 모양으로 정하기 때문에","correct":true},{"t":"옆면의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."]},{"stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 접히는 모서리가 점선이기 때문에","correct":true},{"t":"잘린 곳은 끊어져 보이게 점선으로 그리기 때문에","mis":"M6-1-u2-X07"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#17','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C7',3,'mc','auto','어떤 각뿔의 모서리가 18개예요. 이 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":17,"concept":"M6-1-u2-C7","difficulty":3,"kind":"mc","stem":"어떤 각뿔의 모서리가 18개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"구각뿔","correct":true},{"t":"십팔각뿔","mis":"M6-1-u2-X04"},{"t":"구각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요.","한 밑면의 변이 9개라 이름은 구각뿔이에요."],"variant_rule":{"alt":[{"stem":"어떤 각기둥의 모서리가 24개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"팔각기둥","correct":true},{"t":"이십사각기둥","mis":"M6-1-u2-X04"},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","위 밑면 8개, 아래 밑면 8개, 옆 모서리 8개 — 8 × 3 = 24개예요.","한 밑면의 변이 8개라 이름은 팔각기둥이에요."]},{"stem":"어떤 각뿔의 면이 12개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"십일각뿔","correct":true},{"t":"십이각뿔","mis":"M6-1-u2-X04"},{"t":"십일각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","밑면 1개와 옆면 11개 — 11 + 1 = 12개예요.","한 밑면의 변이 11개라 이름은 십일각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#18','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C7',3,'sa','auto','밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 20개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 20개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 20개이니 한 밑면의 변은 10개예요.","같은 밑면의 각뿔은 십각뿔이에요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 면이 8개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각기둥의 면 수 = 변의 수 + 2 — 8개이니 한 밑면의 변은 6개예요.","같은 밑면의 각뿔은 육각뿔이에요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요."]},{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 27개일 때, 각뿔의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 27개이니 한 밑면의 변은 9개예요.","같은 밑면의 각뿔은 구각뿔이에요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#19','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C3',3,'mc','auto','「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X08']::text[],true,'{"seq":19,"concept":"M6-1-u2-C3","difficulty":3,"kind":"mc","stem":"「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 1개뿐이기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 밑면이 1개뿐이기 때문에 전개도가 아니에요."],"variant_rule":{"alt":[{"stem":"「오각형 2개와 직사각형 5개가 이어졌는데, 두 오각형이 같은 쪽에 붙어 접으면 겹치는 그림」은 오각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X13"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X13"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X13"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 접으면 두 밑면이 겹쳐 맞닿지 않기 때문에 전개도가 아니에요."]},{"stem":"「크기가 다른 사각형 2개와 직사각형 4개가 이어진 그림」은 사각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X02"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 두 밑면이 서로 합동이 아니기 때문에 전개도가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#20','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C2',3,'error','auto','각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X06','M6-1-u2-X14']::text[],true,'{"seq":20,"concept":"M6-1-u2-C2","difficulty":3,"kind":"error","stem":"각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「각기둥의 높이는 밑면의 가장 긴 변의 길이야.」","correct":true,"mis_target":"M6-1-u2-X06"},{"t":"수아 — 「각기둥의 밑면은 2개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「각기둥의 밑면은 옆면과 수직으로 만나.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 변은 밑면 안의 선분이라 높이가 될 수 없어요.","서호는 높이를 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"오각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꼭짓점이 5개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"나린 — 「모서리가 10개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「옆면이 5개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 5 + 1 = 6개예요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요.","가온은 각뿔의 꼭짓점을 빠뜨렸어요."]},{"stem":"육각기둥의 전개도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「옆면이 8개 그려져 있어.」","correct":true,"mis_target":"M6-1-u2-X08"},{"t":"라온 — 「밑면이 2개 그려져 있어.」","mis":"M6-1-u2-X14"},{"t":"예준 — 「접히는 모서리는 점선이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","육각기둥의 옆면은 6개, 밑면은 2개예요.","여울은 면 전체의 수를 옆면의 수로 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#21','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C7',3,'sa','auto','밑면이 구각형인 각기둥과 각뿔이 있어요. 두 입체도형의 모서리 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면이 구각형인 각기둥과 각뿔이 있어요. 두 입체도형의 모서리 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["위 밑면 9개, 아래 밑면 9개, 옆 모서리 9개 — 9 × 3 = 27개예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요.","차는 27 − 18 = 9개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 십각형인 각기둥과 각뿔이 있어요. 두 입체도형의 면 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["밑면 2개와 옆면 10개 — 10 + 2 = 12개예요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요.","차는 12 − 11 = 1개예요."]},{"stem":"밑면이 칠각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요.","밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요.","차는 14 − 8 = 6개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#22','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C4',3,'mc','auto','밑면이 한 변이 3 cm인 정육각형이고 높이가 10 cm인 육각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":22,"concept":"M6-1-u2-C4","difficulty":3,"kind":"mc","stem":"밑면이 한 변이 3 cm인 정육각형이고 높이가 10 cm인 육각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 3 cm, 세로 10 cm","correct":true},{"t":"가로 10 cm, 세로 18 cm","mis":"M6-1-u2-X09"},{"t":"가로 18 cm, 세로 10 cm","mis":"M6-1-u2-X09"},{"t":"가로 3 cm, 세로 3 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 3 cm예요.","옆면의 세로는 각기둥의 높이와 같아 10 cm예요.","그래서 옆면 하나는 「가로 3 cm, 세로 10 cm」예요."],"variant_rule":{"alt":[{"stem":"밑면이 한 변이 6 cm인 정오각형이고 높이가 7 cm인 오각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 6 cm, 세로 7 cm","correct":true},{"t":"가로 7 cm, 세로 30 cm","mis":"M6-1-u2-X09"},{"t":"가로 30 cm, 세로 7 cm","mis":"M6-1-u2-X09"},{"t":"가로 6 cm, 세로 6 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 6 cm예요.","옆면의 세로는 각기둥의 높이와 같아 7 cm예요.","그래서 옆면 하나는 「가로 6 cm, 세로 7 cm」예요."]},{"stem":"밑면이 한 변이 4 cm인 정삼각형이고 높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 4 cm, 세로 11 cm","correct":true},{"t":"가로 11 cm, 세로 12 cm","mis":"M6-1-u2-X09"},{"t":"가로 12 cm, 세로 11 cm","mis":"M6-1-u2-X09"},{"t":"가로 4 cm, 세로 4 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 4 cm예요.","옆면의 세로는 각기둥의 높이와 같아 11 cm예요.","그래서 옆면 하나는 「가로 4 cm, 세로 11 cm」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#23','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C6',4,'sa','auto','밑면이 한 변이 3 cm인 정오각형이고 옆 모서리가 모두 9 cm인 오각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u2-C6","difficulty":4,"kind":"sa","stem":"밑면이 한 변이 3 cm인 정오각형이고 옆 모서리가 모두 9 cm인 오각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["밑면의 변은 5개이고 모두 3 cm예요.","옆 모서리도 5개이고 모두 9 cm예요.","5 × 3 + 5 × 9 = 60 — 모두 60 cm예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 7 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 3 + 4 + 5 = 12 cm예요.","세로는 높이 7 cm예요.","넓이는 12 × 7 = 84 cm²예요."]},{"stem":"어떤 각뿔의 모서리가 22개예요. 이 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2 — 한 밑면의 변은 11개예요.","이 입체도형은 십일각뿔이에요.","밑면 1개와 옆면 11개 — 11 + 1 = 12개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#24','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C2',4,'essay','teacher','밑면이 한 변이 3 cm인 정육각형이고 높이가 5 cm인 육각기둥이 있어요. 모든 모서리의 길이의 합을 구하는 과정을 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u2-C2","difficulty":4,"kind":"essay","stem":"밑면이 한 변이 3 cm인 정육각형이고 높이가 5 cm인 육각기둥이 있어요. 모든 모서리의 길이의 합을 구하는 과정을 쓰세요.","answer_guide":{"answer":"예: 육각기둥의 모서리는 6 × 3 = 18개이다. 두 밑면의 변 12개는 모두 3 cm이므로 12 × 3 = 36 cm이고, 옆 모서리 6개는 높이와 같은 5 cm이므로 6 × 5 = 30 cm이다. 모두 더하면 36 + 30 = 66 cm이다.","scoring_points":["밑면의 변 12개와 옆 모서리 6개로 나누었는가","36 cm와 30 cm를 구했는가","66 cm를 구했는가"]},"explanation":["밑면의 변 12개 — 12 × 3 = 36 cm예요.","옆 모서리 6개 — 6 × 5 = 30 cm예요.","36 + 30 = 66 cm예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_b#25','math',6,1,'u2','','g6_1_math_u2_review_b','unit_review','M6-1-u2-C3',4,'essay','teacher','「사각형 2개와 직사각형 4개가 이어진 그림은 언제나 사각기둥의 전개도이다.」 이 말이 맞는지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u2-C3","difficulty":4,"kind":"essay","stem":"「사각형 2개와 직사각형 4개가 이어진 그림은 언제나 사각기둥의 전개도이다.」 이 말이 맞는지 쓰고, 그렇게 생각한 까닭을 설명해 보세요.","answer_guide":{"answer":"예: 언제나 맞는 것은 아니다. 면의 수가 맞더라도 두 사각형이 서로 합동이어야 하고, 접었을 때 맞닿는 선분의 길이가 같아야 하며, 접어서 면이 겹치지 않아야 전개도가 된다. 두 밑면이 같은 쪽에 붙어 겹치거나 길이가 맞지 않으면 사각기둥이 되지 않는다.","scoring_points":["언제나 맞는 것은 아니라고 답했는가","합동·맞닿는 선분 길이·겹침 가운데 하나 이상의 조건을 썼는가","조건이 어긋나면 사각기둥이 되지 않는다고 설명했는가"]},"explanation":["면의 수만으로는 모자라요.","밑면 합동·맞닿는 선분 길이·겹치지 않음을 봐야 해요.","그래서 언제나 맞지는 않아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#1','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C1',1,'mc','auto','두 밑면과 만나는 면을 무엇이라고 하나요?',ARRAY['M6-1-u2-X01']::text[],true,'{"seq":1,"concept":"M6-1-u2-C1","difficulty":1,"kind":"mc","stem":"두 밑면과 만나는 면을 무엇이라고 하나요?","options":[{"t":"옆면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「옆면」이에요."],"variant_rule":{"alt":[{"stem":"한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형을 무엇이라고 하나요?","options":[{"t":"각뿔","correct":true},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각기둥","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면이 밑면, 밑면과 만나는 삼각형이 옆면이에요.","그래서 답은 「각뿔」이에요."]},{"stem":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"밑면","mis":"M6-1-u2-X11"},{"t":"옆면","mis":"M6-1-u2-X11"},{"t":"각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「각기둥」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#2','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C5',1,'mc','auto','각뿔의 옆면은 모두 어떤 도형인가요?',ARRAY['M6-1-u2-X03']::text[],true,'{"seq":2,"concept":"M6-1-u2-C5","difficulty":1,"kind":"mc","stem":"각뿔의 옆면은 모두 어떤 도형인가요?","options":[{"t":"삼각형","correct":true},{"t":"직사각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X03"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."],"variant_rule":{"alt":[{"stem":"각뿔의 옆면은 모두 어디에서 만나나요?","options":[{"t":"한 점에서 모두 만나요","correct":true},{"t":"만나지 않아요","mis":"M6-1-u2-X11"},{"t":"밑면과 수직으로 만나요","mis":"M6-1-u2-X11"},{"t":"위쪽 밑면에서 만나요","mis":"M6-1-u2-X10"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."]},{"stem":"각기둥의 옆면은 모두 어떤 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「직사각형」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#3','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C2',1,'mc','auto','밑면이 구각형인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":3,"concept":"M6-1-u2-C2","difficulty":1,"kind":"mc","stem":"밑면이 구각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X04"},{"t":"십팔각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 구각형이에요.","그래서 이름은 구각기둥이에요."],"variant_rule":{"alt":[{"stem":"밑면이 육각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"육각기둥","correct":true},{"t":"육각뿔","mis":"M6-1-u2-X11"},{"t":"팔각기둥","mis":"M6-1-u2-X04"},{"t":"십이각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 육각형이에요.","그래서 이름은 육각기둥이에요."]},{"stem":"밑면이 칠각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"칠각기둥","correct":true},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X04"},{"t":"십사각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 칠각형이에요.","그래서 이름은 칠각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#4','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C6',1,'mc','auto','밑면이 오각형인 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":4,"concept":"M6-1-u2-C6","difficulty":1,"kind":"mc","stem":"밑면이 오각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"오각뿔","correct":true},{"t":"오각기둥","mis":"M6-1-u2-X11"},{"t":"육각뿔","mis":"M6-1-u2-X04"},{"t":"십각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 오각형이에요.","그래서 이름은 오각뿔이에요."],"variant_rule":{"alt":[{"stem":"밑면이 구각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"구각뿔","correct":true},{"t":"구각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X04"},{"t":"십팔각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 구각형이에요.","그래서 이름은 구각뿔이에요."]},{"stem":"밑면이 팔각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"팔각뿔","correct":true},{"t":"팔각기둥","mis":"M6-1-u2-X11"},{"t":"구각뿔","mis":"M6-1-u2-X04"},{"t":"십육각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 팔각형이에요.","그래서 이름은 팔각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#5','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C2',1,'sa','auto','칠각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C2","difficulty":1,"kind":"sa","stem":"칠각기둥의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["14"],"explanation":["칠각기둥의 밑면은 칠각형이에요.","꼭짓점을 세는 방법을 떠올려요.","한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요."],"mis":"M6-1-u2-X05","variant_rule":{"alt":[{"stem":"사각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["사각기둥의 밑면은 사각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."]},{"stem":"육각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["육각기둥의 밑면은 육각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#6','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C6',1,'sa','auto','오각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C6","difficulty":1,"kind":"sa","stem":"오각뿔의 모서리는 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["오각뿔의 밑면은 오각형이에요.","모서리를 세는 방법을 떠올려요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"구각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["구각뿔의 밑면은 구각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."]},{"stem":"칠각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["칠각뿔의 밑면은 칠각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#7','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C3',1,'mc','auto','각기둥의 전개도는 어떤 그림인가요?',ARRAY['M6-1-u2-X07','M6-1-u2-X08']::text[],true,'{"seq":7,"concept":"M6-1-u2-C3","difficulty":1,"kind":"mc","stem":"각기둥의 전개도는 어떤 그림인가요?","options":[{"t":"모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림","correct":true},{"t":"면을 하나씩 모두 떼어 늘어놓은 그림","mis":"M6-1-u2-X07"},{"t":"각기둥을 위에서 내려다본 그림","mis":"M6-1-u2-X07"},{"t":"밑면만 따라 그린 그림","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「모든 면이 이어지도록 모서리를 잘라 평면 위에 펼친 그림」이에요."],"variant_rule":{"alt":[{"stem":"같은 사각기둥인데 전개도의 모양이 서로 다르게 나오는 까닭은 무엇인가요?","options":[{"t":"자르는 모서리가 달라져서","correct":true},{"t":"밑면의 크기가 달라져서","mis":"M6-1-u2-X13"},{"t":"높이가 달라져서","mis":"M6-1-u2-X13"},{"t":"옆면의 수가 달라져서","mis":"M6-1-u2-X08"}],"explanation":["전개도는 각기둥의 모서리를 잘라서 펼친 그림이에요.","어느 모서리를 자르느냐가 달라지면 펼쳐진 모양도 달라져요.","자른 자리가 다를 뿐 접으면 같은 각기둥이에요."]},{"stem":"각기둥의 전개도에서 점선은 무엇을 나타내나요?","options":[{"t":"잘리지 않고 접히는 모서리","correct":true},{"t":"잘린 모서리","mis":"M6-1-u2-X07"},{"t":"밑면의 둘레","mis":"M6-1-u2-X07"},{"t":"옆면의 넓이","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘리지 않고 접히는 모서리」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#8','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C4',1,'sa','auto','높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C4","difficulty":1,"kind":"sa","stem":"높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["11"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 11 cm로 그려요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"높이가 5 cm인 칠각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 5 cm로 그려요."]},{"stem":"높이가 8 cm인 육각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 8 cm로 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#9','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C1',2,'mc','auto','팔각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 팔각형은 무엇인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X05']::text[],true,'{"seq":9,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"팔각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 팔각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 팔각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 팔각형은 여전히 밑면이에요."],"variant_rule":{"alt":[{"stem":"사각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 사각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 사각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 사각형은 여전히 밑면이에요."]},{"stem":"육각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 육각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 육각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 육각형은 여전히 밑면이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#10','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C5',2,'mc','auto','「밑면이 원이고 뾰족한 점이 있는 고깔」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X11']::text[],true,'{"seq":10,"concept":"M6-1-u2-C5","difficulty":2,"kind":"mc","stem":"「밑면이 원이고 뾰족한 점이 있는 고깔」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 다각형이 아니기 때문에","correct":true},{"t":"옆면이 삼각형이 아니기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X11"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「밑면이 원이고 뾰족한 점이 있는 고깔」을 이 조건에 대어 봐요.","밑면이 다각형이 아니기 때문에 각뿔이 아니에요."],"variant_rule":{"alt":[{"stem":"「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 삼각형이 아니기 때문에","correct":true},{"t":"밑면이 다각형이 아니기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」을 이 조건에 대어 봐요.","옆면이 삼각형이 아니기 때문에 각뿔이 아니에요."]},{"stem":"「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평행한 두 면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행한 두 오각형의 크기가 다른 입체도형」을 이 조건에 하나씩 대어 봐요.","평행한 두 면이 서로 합동이 아니기 때문에 각기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#11','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C2',2,'sa','auto','문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 9 cm, 12 cm, 15 cm이고 옆면과 옆면이 만나는 모서리가 7 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 9 cm, 12 cm, 15 cm이고 옆면과 옆면이 만나는 모서리가 7 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 9 cm, 12 cm, 15 cm는 높이가 아니에요 — 높이는 7 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 8 cm, 15 cm, 17 cm이고 옆면과 옆면이 만나는 모서리가 5 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 8 cm, 15 cm, 17 cm는 높이가 아니에요 — 높이는 5 cm예요."]},{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 6 cm, 8 cm, 10 cm이고 옆면과 옆면이 만나는 모서리가 9 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 6 cm, 8 cm, 10 cm는 높이가 아니에요 — 높이는 9 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#12','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C6',2,'sa','auto','오각뿔 모양 건축물이 있어요. 옆 모서리가 25 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 24 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"오각뿔 모양 건축물이 있어요. 옆 모서리가 25 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 24 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 25 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 24 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"팔각뿔 모양 건축물이 있어요. 옆 모서리가 17 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 15 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 17 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 15 cm예요."]},{"stem":"육각뿔 모양 건축물이 있어요. 옆 모서리가 13 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 12 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 13 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 12 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#13','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C3',2,'mc','auto','오각형 2개와 직사각형 5개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":13,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"오각형 2개와 직사각형 5개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X08"},{"t":"십각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 오각형 2개가 밑면이 돼요.","직사각형 5개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 오각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"팔각형 2개와 직사각형 8개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"팔각기둥","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X08"},{"t":"십육각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 팔각형 2개가 밑면이 돼요.","직사각형 8개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 팔각기둥이 돼요."]},{"stem":"칠각형 2개와 직사각형 7개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"칠각기둥","correct":true},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X08"},{"t":"십사각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 칠각형 2개가 밑면이 돼요.","직사각형 7개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 칠각기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#14','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C4',2,'sa','auto','밑면의 변이 4 cm, 5 cm, 6 cm, 7 cm인 사각기둥의 높이가 8 cm예요. 전개도에서 옆면 4개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u2-C4","difficulty":2,"kind":"sa","stem":"밑면의 변이 4 cm, 5 cm, 6 cm, 7 cm인 사각기둥의 높이가 8 cm예요. 전개도에서 옆면 4개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","4 + 5 + 6 + 7 = 22 — 가로는 22 cm예요(높이 8 cm는 세로예요)."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면의 변이 6 cm, 8 cm, 10 cm인 삼각기둥의 높이가 5 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","6 + 8 + 10 = 24 — 가로는 24 cm예요(높이 5 cm는 세로예요)."]},{"stem":"밑면의 변이 5 cm, 12 cm, 13 cm인 삼각기둥의 높이가 7 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","5 + 12 + 13 = 30 — 가로는 30 cm예요(높이 7 cm는 세로예요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#15','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C7',2,'sa','auto','이십각기둥의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"이십각기둥의 꼭짓점은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["40"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 변은 20개예요.","한 밑면의 꼭짓점 20개가 위아래로 짝을 이뤄 — 20 × 2 = 40개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"십사각뿔의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","한 밑면의 변은 14개예요.","밑면 1개와 옆면 14개 — 14 + 1 = 15개예요."]},{"stem":"십이각기둥의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["36"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","한 밑면의 변은 12개예요.","위 밑면 12개, 아래 밑면 12개, 옆 모서리 12개 — 12 × 3 = 36개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#16','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C2',2,'ox','auto','각기둥의 이름은 옆면의 모양으로 정해요.',ARRAY['M6-1-u2-X04']::text[],true,'{"seq":16,"concept":"M6-1-u2-C2","difficulty":2,"kind":"ox","stem":"각기둥의 이름은 옆면의 모양으로 정해요.","answer":"X","reason_options":[{"t":"옆면은 모두 직사각형이고 이름은 밑면의 모양으로 정하기 때문에","correct":true},{"t":"옆면의 수가 이름이 되기 때문에","mis":"M6-1-u2-X04"}],"mis":"M6-1-u2-X04","explanation":["각기둥의 이름은 밑면의 모양으로 정해요.","면과 면이 만나는 선분이 모서리, 모서리와 모서리가 만나는 점이 꼭짓점이에요.","높이는 두 밑면 사이의 거리예요."],"variant_rule":{"alt":[{"stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 접히는 모서리가 점선이기 때문에","correct":true},{"t":"잘린 곳은 끊어져 보이게 점선으로 그리기 때문에","mis":"M6-1-u2-X07"}],"explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."]},{"stem":"각뿔의 옆면은 모두 직사각형이에요.","answer":"X","reason_options":[{"t":"옆면은 밑면의 변과 한 점을 이은 삼각형이기 때문에","correct":true},{"t":"각기둥처럼 옆면이 밑면과 수직이기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면 하나가 밑면, 삼각형들이 옆면이에요.","원뿔은 밑면이 원이라 각뿔이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#17','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C7',3,'mc','auto','어떤 각기둥의 모서리가 24개예요. 이 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":17,"concept":"M6-1-u2-C7","difficulty":3,"kind":"mc","stem":"어떤 각기둥의 모서리가 24개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"팔각기둥","correct":true},{"t":"이십사각기둥","mis":"M6-1-u2-X04"},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X12"}],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","위 밑면 8개, 아래 밑면 8개, 옆 모서리 8개 — 8 × 3 = 24개예요.","한 밑면의 변이 8개라 이름은 팔각기둥이에요."],"variant_rule":{"alt":[{"stem":"어떤 각뿔의 면이 12개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"십일각뿔","correct":true},{"t":"십이각뿔","mis":"M6-1-u2-X04"},{"t":"십일각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","밑면 1개와 옆면 11개 — 11 + 1 = 12개예요.","한 밑면의 변이 11개라 이름은 십일각뿔이에요."]},{"stem":"어떤 각기둥의 꼭짓점이 20개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"십각기둥","correct":true},{"t":"이십각기둥","mis":"M6-1-u2-X04"},{"t":"십구각뿔","mis":"M6-1-u2-X12"},{"t":"십각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 꼭짓점 10개가 위아래로 짝을 이뤄 — 10 × 2 = 20개예요.","한 밑면의 변이 10개라 이름은 십각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#18','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C7',3,'sa','auto','밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 면이 8개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 면이 8개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각기둥의 면 수 = 변의 수 + 2 — 8개이니 한 밑면의 변은 6개예요.","같은 밑면의 각뿔은 육각뿔이에요.","밑면의 변 6개와 옆 모서리 6개 — 6 × 2 = 12개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 27개일 때, 각뿔의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 27개이니 한 밑면의 변은 9개예요.","같은 밑면의 각뿔은 구각뿔이에요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."]},{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 24개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 24개이니 한 밑면의 변은 8개예요.","같은 밑면의 각뿔은 팔각뿔이에요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#19','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C3',3,'mc','auto','「오각형 2개와 직사각형 5개가 이어졌는데, 두 오각형이 같은 쪽에 붙어 접으면 겹치는 그림」은 오각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X13']::text[],true,'{"seq":19,"concept":"M6-1-u2-C3","difficulty":3,"kind":"mc","stem":"「오각형 2개와 직사각형 5개가 이어졌는데, 두 오각형이 같은 쪽에 붙어 접으면 겹치는 그림」은 오각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X13"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X13"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X13"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 접으면 두 밑면이 겹쳐 맞닿지 않기 때문에 전개도가 아니에요."],"variant_rule":{"alt":[{"stem":"「크기가 다른 사각형 2개와 직사각형 4개가 이어진 그림」은 사각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X02"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 두 밑면이 서로 합동이 아니기 때문에 전개도가 아니에요."]},{"stem":"「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","correct":true},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 옆면의 수가 한 밑면의 변의 수와 다르기 때문에 전개도가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#20','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C6',3,'error','auto','오각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X10','M6-1-u2-X14']::text[],true,'{"seq":20,"concept":"M6-1-u2-C6","difficulty":3,"kind":"error","stem":"오각뿔 모양 화분을 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"가온 — 「꼭짓점이 5개야.」","correct":true,"mis_target":"M6-1-u2-X10"},{"t":"나린 — 「모서리가 10개야.」","mis":"M6-1-u2-X14"},{"t":"유진 — 「옆면이 5개야.」","mis":"M6-1-u2-X14"}],"explanation":["밑면의 꼭짓점 5개와 각뿔의 꼭짓점 1개 — 5 + 1 = 6개예요.","밑면의 변 5개와 옆 모서리 5개 — 5 × 2 = 10개예요.","가온은 각뿔의 꼭짓점을 빠뜨렸어요."],"variant_rule":{"alt":[{"stem":"육각기둥의 전개도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「옆면이 8개 그려져 있어.」","correct":true,"mis_target":"M6-1-u2-X08"},{"t":"라온 — 「밑면이 2개 그려져 있어.」","mis":"M6-1-u2-X14"},{"t":"예준 — 「접히는 모서리는 점선이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","육각기둥의 옆면은 6개, 밑면은 2개예요.","여울은 면 전체의 수를 옆면의 수로 잘못 말했어요."]},{"stem":"각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「각기둥을 옆으로 눕히면 바닥에 닿은 옆면이 밑면이 돼.」","correct":true,"mis_target":"M6-1-u2-X01"},{"t":"이현 — 「각기둥의 옆면은 모두 직사각형이야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥을 눕혀도 서로 평행하고 합동인 두 면이 밑면이에요.","바닥에 닿은 면이 직사각형 옆면이면 그것은 여전히 옆면이에요.","준희는 밑면을 위치로 잘못 정했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#21','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C7',3,'sa','auto','밑면이 십각형인 각기둥과 각뿔이 있어요. 두 입체도형의 면 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면이 십각형인 각기둥과 각뿔이 있어요. 두 입체도형의 면 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["1"],"explanation":["밑면 2개와 옆면 10개 — 10 + 2 = 12개예요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요.","차는 12 − 11 = 1개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 칠각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요.","밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요.","차는 14 − 8 = 6개예요."]},{"stem":"밑면이 육각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요.","밑면의 꼭짓점 6개와 각뿔의 꼭짓점 1개 — 6 + 1 = 7개예요.","차는 12 − 7 = 5개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#22','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C4',3,'mc','auto','밑면이 한 변이 6 cm인 정오각형이고 높이가 7 cm인 오각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":22,"concept":"M6-1-u2-C4","difficulty":3,"kind":"mc","stem":"밑면이 한 변이 6 cm인 정오각형이고 높이가 7 cm인 오각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 6 cm, 세로 7 cm","correct":true},{"t":"가로 7 cm, 세로 30 cm","mis":"M6-1-u2-X09"},{"t":"가로 30 cm, 세로 7 cm","mis":"M6-1-u2-X09"},{"t":"가로 6 cm, 세로 6 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 6 cm예요.","옆면의 세로는 각기둥의 높이와 같아 7 cm예요.","그래서 옆면 하나는 「가로 6 cm, 세로 7 cm」예요."],"variant_rule":{"alt":[{"stem":"밑면이 한 변이 4 cm인 정삼각형이고 높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 4 cm, 세로 11 cm","correct":true},{"t":"가로 11 cm, 세로 12 cm","mis":"M6-1-u2-X09"},{"t":"가로 12 cm, 세로 11 cm","mis":"M6-1-u2-X09"},{"t":"가로 4 cm, 세로 4 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 4 cm예요.","옆면의 세로는 각기둥의 높이와 같아 11 cm예요.","그래서 옆면 하나는 「가로 4 cm, 세로 11 cm」예요."]},{"stem":"밑면이 한 변이 5 cm인 정사각형이고 높이가 8 cm인 사각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 5 cm, 세로 8 cm","correct":true},{"t":"가로 8 cm, 세로 20 cm","mis":"M6-1-u2-X09"},{"t":"가로 20 cm, 세로 8 cm","mis":"M6-1-u2-X09"},{"t":"가로 5 cm, 세로 5 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 5 cm예요.","옆면의 세로는 각기둥의 높이와 같아 8 cm예요.","그래서 옆면 하나는 「가로 5 cm, 세로 8 cm」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#23','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C4',4,'sa','auto','밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 7 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u2-C4","difficulty":4,"kind":"sa","stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 7 cm예요. 전개도에서 옆면을 모두 이어 붙인 큰 직사각형의 넓이는 몇 cm²인가요? 숫자로 쓰세요.","answer":["84"],"explanation":["이어 붙인 직사각형의 가로는 밑면의 둘레 3 + 4 + 5 = 12 cm예요.","세로는 높이 7 cm예요.","넓이는 12 × 7 = 84 cm²예요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"어떤 각뿔의 모서리가 22개예요. 이 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2 — 한 밑면의 변은 11개예요.","이 입체도형은 십일각뿔이에요.","밑면 1개와 옆면 11개 — 11 + 1 = 12개예요."]},{"stem":"밑면이 한 변이 4 cm인 정사각형이고 높이가 6 cm인 사각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["두 밑면의 변은 4개씩 — 4 × 2 = 8개이고 모두 4 cm예요.","옆 모서리는 4개이고 모두 높이와 같은 6 cm예요.","8 × 4 + 4 × 6 = 56 — 모두 56 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#24','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C5',4,'essay','teacher','캠핑장에서 본 원뿔 모양 고깔과 사각뿔 모양 텐트가 있어요. 두 입체도형 가운데 각뿔인 것을 쓰고, 다른 하나가 각뿔이 아닌 까닭을 각뿔의 뜻으로 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u2-C5","difficulty":4,"kind":"essay","stem":"캠핑장에서 본 원뿔 모양 고깔과 사각뿔 모양 텐트가 있어요. 두 입체도형 가운데 각뿔인 것을 쓰고, 다른 하나가 각뿔이 아닌 까닭을 각뿔의 뜻으로 설명해 보세요.","answer_guide":{"answer":"예: 사각뿔 모양 텐트가 각뿔이다. 각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이다. 원뿔 모양 고깔은 밑면이 원이라 다각형이 아니고 옆면도 굽은 면이라 삼각형이 아니므로 각뿔이 아니다.","scoring_points":["사각뿔 모양 텐트를 각뿔이라고 했는가","각뿔의 뜻(한 면 다각형, 나머지 삼각형)을 썼는가","원뿔은 밑면이 원이라 각뿔이 아니라고 설명했는가"]},"explanation":["각뿔은 한 면이 다각형, 나머지가 삼각형이에요.","원뿔은 밑면이 원이에요.","그래서 사각뿔 텐트만 각뿔이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_c#25','math',6,1,'u2','','g6_1_math_u2_review_c','unit_review','M6-1-u2-C6',4,'essay','teacher','친구가 오각뿔의 꼭짓점을 「5개」라고 했어요. 잘못된 점을 쓰고, 오각뿔의 꼭짓점과 모서리의 수를 바르게 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u2-C6","difficulty":4,"kind":"essay","stem":"친구가 오각뿔의 꼭짓점을 「5개」라고 했어요. 잘못된 점을 쓰고, 오각뿔의 꼭짓점과 모서리의 수를 바르게 구해 보세요.","answer_guide":{"answer":"예: 밑면의 꼭짓점 5개만 세고 옆면이 모두 만나는 각뿔의 꼭짓점 1개를 빠뜨렸다. 오각뿔의 꼭짓점은 5 + 1 = 6개이다. 모서리는 밑면의 변 5개와 옆 모서리 5개로 5 × 2 = 10개이다.","scoring_points":["각뿔의 꼭짓점을 빠뜨렸다고 썼는가","꼭짓점 6개를 구했는가","모서리 10개를 구했는가"]},"explanation":["각뿔의 꼭짓점을 빠뜨렸어요.","꼭짓점은 5 + 1 = 6개예요.","모서리는 5 × 2 = 10개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#1','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C5',1,'mc','auto','한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형을 무엇이라고 하나요?',ARRAY['M6-1-u2-X01','M6-1-u2-X11']::text[],true,'{"seq":1,"concept":"M6-1-u2-C5","difficulty":1,"kind":"mc","stem":"한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형을 무엇이라고 하나요?","options":[{"t":"각뿔","correct":true},{"t":"밑면","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각기둥","mis":"M6-1-u2-X11"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면이 밑면, 밑면과 만나는 삼각형이 옆면이에요.","그래서 답은 「각뿔」이에요."],"variant_rule":{"alt":[{"stem":"두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형을 무엇이라고 하나요?","options":[{"t":"각기둥","correct":true},{"t":"밑면","mis":"M6-1-u2-X11"},{"t":"옆면","mis":"M6-1-u2-X11"},{"t":"각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「각기둥」이에요."]},{"stem":"각기둥에서 서로 평행하고 합동인 두 면을 무엇이라고 하나요?","options":[{"t":"밑면","correct":true},{"t":"각기둥","mis":"M6-1-u2-X01"},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"각뿔","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형으로 이루어진 입체도형이에요.","그 두 면이 밑면, 두 밑면과 만나는 면이 옆면이에요.","그래서 답은 「밑면」이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#2','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C5',1,'mc','auto','각뿔의 옆면은 모두 어디에서 만나나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X10']::text[],true,'{"seq":2,"concept":"M6-1-u2-C5","difficulty":1,"kind":"mc","stem":"각뿔의 옆면은 모두 어디에서 만나나요?","options":[{"t":"한 점에서 모두 만나요","correct":true},{"t":"만나지 않아요","mis":"M6-1-u2-X11"},{"t":"밑면과 수직으로 만나요","mis":"M6-1-u2-X11"},{"t":"위쪽 밑면에서 만나요","mis":"M6-1-u2-X10"}],"explanation":["각뿔의 옆면 하나는 밑면의 변 하나와 위쪽 한 점으로 만들어져요.","선분 하나와 그 밖의 한 점을 이으면 언제나 삼각형이에요.","그래서 옆면은 모두 삼각형이고 한 점에서 만나요."],"variant_rule":{"alt":[{"stem":"각기둥의 옆면은 모두 어떤 도형인가요?","options":[{"t":"직사각형","correct":true},{"t":"삼각형","mis":"M6-1-u2-X03"},{"t":"사다리꼴","mis":"M6-1-u2-X03"},{"t":"밑면과 같은 다각형","mis":"M6-1-u2-X01"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「직사각형」이에요."]},{"stem":"각기둥의 두 밑면은 서로 어떤 관계인가요?","options":[{"t":"서로 평행하고 합동이에요","correct":true},{"t":"서로 수직이에요","mis":"M6-1-u2-X01"},{"t":"평행하지만 크기가 달라요","mis":"M6-1-u2-X02"},{"t":"한 꼭짓점에서 만나요","mis":"M6-1-u2-X11"}],"explanation":["각기둥은 두 밑면이 서로 평행하고 합동인 다각형이에요.","옆면은 모두 직사각형이고 두 밑면과 수직으로 만나요.","그래서 답은 「서로 평행하고 합동이에요」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#3','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C2',1,'mc','auto','밑면이 육각형인 각기둥의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":3,"concept":"M6-1-u2-C2","difficulty":1,"kind":"mc","stem":"밑면이 육각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"육각기둥","correct":true},{"t":"육각뿔","mis":"M6-1-u2-X11"},{"t":"팔각기둥","mis":"M6-1-u2-X04"},{"t":"십이각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 육각형이에요.","그래서 이름은 육각기둥이에요."],"variant_rule":{"alt":[{"stem":"밑면이 칠각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"칠각기둥","correct":true},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X04"},{"t":"십사각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 칠각형이에요.","그래서 이름은 칠각기둥이에요."]},{"stem":"밑면이 오각형인 각기둥의 이름은 무엇인가요?","options":[{"t":"오각기둥","correct":true},{"t":"오각뿔","mis":"M6-1-u2-X11"},{"t":"칠각기둥","mis":"M6-1-u2-X04"},{"t":"십각기둥","mis":"M6-1-u2-X04"}],"explanation":["각기둥의 이름은 밑면의 모양이 정해요.","밑면이 오각형이에요.","그래서 이름은 오각기둥이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#4','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C6',1,'mc','auto','밑면이 구각형인 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X11','M6-1-u2-X04']::text[],true,'{"seq":4,"concept":"M6-1-u2-C6","difficulty":1,"kind":"mc","stem":"밑면이 구각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"구각뿔","correct":true},{"t":"구각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X04"},{"t":"십팔각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 구각형이에요.","그래서 이름은 구각뿔이에요."],"variant_rule":{"alt":[{"stem":"밑면이 팔각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"팔각뿔","correct":true},{"t":"팔각기둥","mis":"M6-1-u2-X11"},{"t":"구각뿔","mis":"M6-1-u2-X04"},{"t":"십육각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 팔각형이에요.","그래서 이름은 팔각뿔이에요."]},{"stem":"밑면이 칠각형인 각뿔의 이름은 무엇인가요?","options":[{"t":"칠각뿔","correct":true},{"t":"칠각기둥","mis":"M6-1-u2-X11"},{"t":"팔각뿔","mis":"M6-1-u2-X04"},{"t":"십사각뿔","mis":"M6-1-u2-X04"}],"explanation":["각뿔의 이름도 각기둥처럼 밑면의 모양이 정해요.","밑면이 칠각형이에요.","그래서 이름은 칠각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#5','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C2',1,'sa','auto','사각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M6-1-u2-C2","difficulty":1,"kind":"sa","stem":"사각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["사각기둥의 밑면은 사각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 4개 — 4 + 2 = 6개예요."],"mis":"M6-1-u2-X08","variant_rule":{"alt":[{"stem":"육각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["육각기둥의 밑면은 육각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 6개 — 6 + 2 = 8개예요."]},{"stem":"오각기둥의 면은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["오각기둥의 밑면은 오각형이에요.","면을 세는 방법을 떠올려요.","밑면 2개와 옆면 5개 — 5 + 2 = 7개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#6','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C6',1,'sa','auto','구각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M6-1-u2-C6","difficulty":1,"kind":"sa","stem":"구각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["구각뿔의 밑면은 구각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."],"mis":"M6-1-u2-X10","variant_rule":{"alt":[{"stem":"칠각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["칠각뿔의 밑면은 칠각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요."]},{"stem":"팔각뿔의 꼭짓점은 모두 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["팔각뿔의 밑면은 팔각형이에요.","꼭짓점을 셀 때 각뿔의 꼭짓점을 빠뜨리지 않아요.","밑면의 꼭짓점 8개와 각뿔의 꼭짓점 1개 — 8 + 1 = 9개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#7','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C4',1,'mc','auto','같은 사각기둥인데 전개도의 모양이 서로 다르게 나오는 까닭은 무엇인가요?',ARRAY['M6-1-u2-X13','M6-1-u2-X08']::text[],true,'{"seq":7,"concept":"M6-1-u2-C4","difficulty":1,"kind":"mc","stem":"같은 사각기둥인데 전개도의 모양이 서로 다르게 나오는 까닭은 무엇인가요?","options":[{"t":"자르는 모서리가 달라져서","correct":true},{"t":"밑면의 크기가 달라져서","mis":"M6-1-u2-X13"},{"t":"높이가 달라져서","mis":"M6-1-u2-X13"},{"t":"옆면의 수가 달라져서","mis":"M6-1-u2-X08"}],"explanation":["전개도는 각기둥의 모서리를 잘라서 펼친 그림이에요.","어느 모서리를 자르느냐가 달라지면 펼쳐진 모양도 달라져요.","자른 자리가 다를 뿐 접으면 같은 각기둥이에요."],"variant_rule":{"alt":[{"stem":"각기둥의 전개도에서 점선은 무엇을 나타내나요?","options":[{"t":"잘리지 않고 접히는 모서리","correct":true},{"t":"잘린 모서리","mis":"M6-1-u2-X07"},{"t":"밑면의 둘레","mis":"M6-1-u2-X07"},{"t":"옆면의 넓이","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘리지 않고 접히는 모서리」예요."]},{"stem":"각기둥의 전개도에서 실선은 무엇을 나타내나요?","options":[{"t":"잘린 모서리","correct":true},{"t":"잘리지 않고 접히는 모서리","mis":"M6-1-u2-X07"},{"t":"각기둥의 높이","mis":"M6-1-u2-X06"},{"t":"밑면의 대각선","mis":"M6-1-u2-X07"}],"explanation":["각기둥의 모든 면이 이어지도록 모서리를 잘라 펼친 그림이 전개도예요.","실선은 잘린 모서리, 점선은 잘리지 않고 접히는 모서리예요.","그래서 답은 「잘린 모서리」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#8','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C4',1,'sa','auto','높이가 5 cm인 칠각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M6-1-u2-C4","difficulty":1,"kind":"sa","stem":"높이가 5 cm인 칠각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["5"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 5 cm로 그려요."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"높이가 8 cm인 육각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["8"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 8 cm로 그려요."]},{"stem":"높이가 12 cm인 오각기둥의 전개도를 그려요. 옆면의 세로는 몇 cm로 그려야 하나요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면의 가로는 밑면의 변의 길이와 같아요.","옆면의 세로는 각기둥의 높이와 같아요.","그래서 세로는 12 cm로 그려요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#9','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C1',2,'mc','auto','사각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 사각형은 무엇인가요?',ARRAY['M6-1-u2-X01','M6-1-u2-X05']::text[],true,'{"seq":9,"concept":"M6-1-u2-C1","difficulty":2,"kind":"mc","stem":"사각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 사각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 사각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 사각형은 여전히 밑면이에요."],"variant_rule":{"alt":[{"stem":"육각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 육각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 육각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 육각형은 여전히 밑면이에요."]},{"stem":"오각기둥 모양 저금통을 옆으로 눕혀 놓았어요. 이때 바닥이 아니라 양옆에 서 있는 두 오각형은 무엇인가요?","options":[{"t":"밑면","correct":true},{"t":"옆면","mis":"M6-1-u2-X01"},{"t":"모서리","mis":"M6-1-u2-X05"},{"t":"높이","mis":"M6-1-u2-X05"}],"explanation":["밑면은 아래에 놓인 면이 아니에요.","서로 평행하고 합동인 두 오각형이 밑면이에요.","눕혀도 그 관계는 그대로라 두 오각형은 여전히 밑면이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#10','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C5',2,'mc','auto','「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X03']::text[],true,'{"seq":10,"concept":"M6-1-u2-C5","difficulty":2,"kind":"mc","stem":"「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」은 각뿔이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 삼각형이 아니기 때문에","correct":true},{"t":"밑면이 다각형이 아니기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 2개이고 옆면이 직사각형이기 때문에","mis":"M6-1-u2-X03"},{"t":"다각형인 면이 하나도 없기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","「한 면이 사각형이고 옆면이 모두 사다리꼴인 화분」을 이 조건에 대어 봐요.","옆면이 삼각형이 아니기 때문에 각뿔이 아니에요."],"variant_rule":{"alt":[{"stem":"「서로 평행한 두 오각형의 크기가 다른 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"평행한 두 면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행한 두 오각형의 크기가 다른 입체도형」을 이 조건에 하나씩 대어 봐요.","평행한 두 면이 서로 합동이 아니기 때문에 각기둥이 아니에요."]},{"stem":"「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」은 각기둥이 아니에요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에","correct":true},{"t":"평행한 두 면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 다각형이 아니고 굽은 면이 있기 때문에","mis":"M6-1-u2-X02"},{"t":"서로 평행하고 합동인 두 면이 없기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥은 두 면이 서로 평행하고 합동인 다각형이고, 옆면은 모두 직사각형이에요.","「서로 평행하고 합동인 두 오각형이 있지만 옆면이 평행사변형이고 밑면과 비스듬히 만나는 입체도형」을 이 조건에 하나씩 대어 봐요.","옆면이 직사각형이 아니고 밑면과 수직으로 만나지 않기 때문에 각기둥이 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#11','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C2',2,'sa','auto','문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 8 cm, 15 cm, 17 cm이고 옆면과 옆면이 만나는 모서리가 5 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M6-1-u2-C2","difficulty":2,"kind":"sa","stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 8 cm, 15 cm, 17 cm이고 옆면과 옆면이 만나는 모서리가 5 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 8 cm, 15 cm, 17 cm는 높이가 아니에요 — 높이는 5 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 6 cm, 8 cm, 10 cm이고 옆면과 옆면이 만나는 모서리가 9 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 6 cm, 8 cm, 10 cm는 높이가 아니에요 — 높이는 9 cm예요."]},{"stem":"문 고정 받침대는 삼각기둥 모양이에요. 밑면의 세 변이 5 cm, 12 cm, 13 cm이고 옆면과 옆면이 만나는 모서리가 4 cm일 때, 이 삼각기둥의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","옆면과 옆면이 만나는 모서리는 두 밑면과 수직이라 그 길이가 곧 높이예요.","밑면의 변 5 cm, 12 cm, 13 cm는 높이가 아니에요 — 높이는 4 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#12','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C6',2,'sa','auto','팔각뿔 모양 건축물이 있어요. 옆 모서리가 17 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 15 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M6-1-u2-C6","difficulty":2,"kind":"sa","stem":"팔각뿔 모양 건축물이 있어요. 옆 모서리가 17 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 15 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 17 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 15 cm예요."],"mis":"M6-1-u2-X06","variant_rule":{"alt":[{"stem":"육각뿔 모양 건축물이 있어요. 옆 모서리가 13 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 12 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 13 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 12 cm예요."]},{"stem":"사각뿔 모양 건축물이 있어요. 옆 모서리가 10 cm이고 각뿔의 꼭짓점에서 밑면까지 수직으로 내린 선분이 8 cm일 때, 이 건축물의 높이는 몇 cm인가요? 숫자로 쓰세요.","answer":["8"],"explanation":["각뿔의 높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요.","옆 모서리 10 cm는 비스듬히 기울어져 높이보다 길어요.","그래서 높이는 8 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#13','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C3',2,'mc','auto','팔각형 2개와 직사각형 8개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?',ARRAY['M6-1-u2-X11','M6-1-u2-X08']::text[],true,'{"seq":13,"concept":"M6-1-u2-C3","difficulty":2,"kind":"mc","stem":"팔각형 2개와 직사각형 8개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"팔각기둥","correct":true},{"t":"팔각뿔","mis":"M6-1-u2-X11"},{"t":"십각기둥","mis":"M6-1-u2-X08"},{"t":"십육각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 팔각형 2개가 밑면이 돼요.","직사각형 8개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 팔각기둥이 돼요."],"variant_rule":{"alt":[{"stem":"칠각형 2개와 직사각형 7개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"칠각기둥","correct":true},{"t":"칠각뿔","mis":"M6-1-u2-X11"},{"t":"구각기둥","mis":"M6-1-u2-X08"},{"t":"십사각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 칠각형 2개가 밑면이 돼요.","직사각형 7개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 칠각기둥이 돼요."]},{"stem":"구각형 2개와 직사각형 9개가 하나로 이어진 전개도를 접으면 어떤 입체도형이 되나요?","options":[{"t":"구각기둥","correct":true},{"t":"구각뿔","mis":"M6-1-u2-X11"},{"t":"십일각기둥","mis":"M6-1-u2-X08"},{"t":"십팔각기둥","mis":"M6-1-u2-X08"}],"explanation":["서로 합동인 구각형 2개가 밑면이 돼요.","직사각형 9개는 옆면 — 밑면의 변의 수와 같아요.","그래서 접으면 구각기둥이 돼요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#14','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C4',2,'sa','auto','밑면의 변이 6 cm, 8 cm, 10 cm인 삼각기둥의 높이가 5 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":14,"concept":"M6-1-u2-C4","difficulty":2,"kind":"sa","stem":"밑면의 변이 6 cm, 8 cm, 10 cm인 삼각기둥의 높이가 5 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","6 + 8 + 10 = 24 — 가로는 24 cm예요(높이 5 cm는 세로예요)."],"mis":"M6-1-u2-X09","variant_rule":{"alt":[{"stem":"밑면의 변이 5 cm, 12 cm, 13 cm인 삼각기둥의 높이가 7 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","5 + 12 + 13 = 30 — 가로는 30 cm예요(높이 7 cm는 세로예요)."]},{"stem":"밑면의 변이 3 cm, 4 cm, 5 cm인 삼각기둥의 높이가 9 cm예요. 전개도에서 옆면 3개를 옆으로 이어 붙인 직사각형의 가로는 몇 cm인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["옆면 하나의 가로는 밑면의 변 하나의 길이와 같아요.","옆면을 이어 붙이면 가로는 밑면의 변을 모두 더한 길이, 곧 밑면의 둘레예요.","3 + 4 + 5 = 12 — 가로는 12 cm예요(높이 9 cm는 세로예요)."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#15','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C7',2,'sa','auto','십사각뿔의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.','{}'::text[],true,'{"seq":15,"concept":"M6-1-u2-C7","difficulty":2,"kind":"sa","stem":"십사각뿔의 면은 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["15"],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","한 밑면의 변은 14개예요.","밑면 1개와 옆면 14개 — 14 + 1 = 15개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"십이각기둥의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["36"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3이에요.","한 밑면의 변은 12개예요.","위 밑면 12개, 아래 밑면 12개, 옆 모서리 12개 — 12 × 3 = 36개예요."]},{"stem":"십오각뿔의 모서리는 모두 몇 개인가요? 일일이 세지 말고 밑면의 변의 수로 구해 숫자로 쓰세요.","answer":["30"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","한 밑면의 변은 15개예요.","밑면의 변 15개와 옆 모서리 15개 — 15 × 2 = 30개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#16','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C3',2,'ox','auto','전개도에서 잘린 모서리는 점선으로 나타내요.',ARRAY['M6-1-u2-X07']::text[],true,'{"seq":16,"concept":"M6-1-u2-C3","difficulty":2,"kind":"ox","stem":"전개도에서 잘린 모서리는 점선으로 나타내요.","answer":"X","reason_options":[{"t":"잘린 모서리는 실선, 접히는 모서리가 점선이기 때문에","correct":true},{"t":"잘린 곳은 끊어져 보이게 점선으로 그리기 때문에","mis":"M6-1-u2-X07"}],"mis":"M6-1-u2-X07","explanation":["전개도는 모든 면이 이어지도록 모서리를 잘라 펼친 그림이에요.","실선은 잘린 모서리, 점선은 접히는 모서리예요.","밑면 2개, 옆면은 한 밑면의 변의 수만큼 그려져요."],"variant_rule":{"alt":[{"stem":"각뿔의 옆면은 모두 직사각형이에요.","answer":"X","reason_options":[{"t":"옆면은 밑면의 변과 한 점을 이은 삼각형이기 때문에","correct":true},{"t":"각기둥처럼 옆면이 밑면과 수직이기 때문에","mis":"M6-1-u2-X03"}],"explanation":["각뿔은 한 면이 다각형이고 다른 면이 모두 삼각형인 입체도형이에요.","다각형인 면 하나가 밑면, 삼각형들이 옆면이에요.","원뿔은 밑면이 원이라 각뿔이 아니에요."]},{"stem":"오각뿔의 꼭짓점은 5개예요.","answer":"X","reason_options":[{"t":"밑면의 꼭짓점 5개에 각뿔의 꼭짓점 1개를 더해 6개이기 때문에","correct":true},{"t":"밑면이 오각형이라 꼭짓점도 5개이기 때문에","mis":"M6-1-u2-X10"}],"explanation":["각뿔의 이름은 밑면의 모양으로 정해요.","옆면이 모두 만나는 점이 각뿔의 꼭짓점이고 꼭짓점을 셀 때 빠뜨리지 않아요.","높이는 각뿔의 꼭짓점에서 밑면에 수직으로 내린 선분의 길이예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#17','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C7',3,'mc','auto','어떤 각뿔의 면이 12개예요. 이 각뿔의 이름은 무엇인가요?',ARRAY['M6-1-u2-X04','M6-1-u2-X11','M6-1-u2-X12']::text[],true,'{"seq":17,"concept":"M6-1-u2-C7","difficulty":3,"kind":"mc","stem":"어떤 각뿔의 면이 12개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"십일각뿔","correct":true},{"t":"십이각뿔","mis":"M6-1-u2-X04"},{"t":"십일각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 면 수 = 변의 수 + 1이에요.","밑면 1개와 옆면 11개 — 11 + 1 = 12개예요.","한 밑면의 변이 11개라 이름은 십일각뿔이에요."],"variant_rule":{"alt":[{"stem":"어떤 각기둥의 꼭짓점이 20개예요. 이 각기둥의 이름은 무엇인가요?","options":[{"t":"십각기둥","correct":true},{"t":"이십각기둥","mis":"M6-1-u2-X04"},{"t":"십구각뿔","mis":"M6-1-u2-X12"},{"t":"십각뿔","mis":"M6-1-u2-X11"}],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2예요.","한 밑면의 꼭짓점 10개가 위아래로 짝을 이뤄 — 10 × 2 = 20개예요.","한 밑면의 변이 10개라 이름은 십각기둥이에요."]},{"stem":"어떤 각뿔의 모서리가 18개예요. 이 각뿔의 이름은 무엇인가요?","options":[{"t":"구각뿔","correct":true},{"t":"십팔각뿔","mis":"M6-1-u2-X04"},{"t":"구각기둥","mis":"M6-1-u2-X11"},{"t":"십각뿔","mis":"M6-1-u2-X12"}],"explanation":["각뿔의 모서리 수 = 변의 수 × 2예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요.","한 밑면의 변이 9개라 이름은 구각뿔이에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#18','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C7',3,'sa','auto','밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 27개일 때, 각뿔의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":18,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 27개일 때, 각뿔의 꼭짓점은 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 27개이니 한 밑면의 변은 9개예요.","같은 밑면의 각뿔은 구각뿔이에요.","밑면의 꼭짓점 9개와 각뿔의 꼭짓점 1개 — 9 + 1 = 10개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 모서리가 24개일 때, 각뿔의 모서리는 몇 개인가요? 숫자로 쓰세요.","answer":["16"],"explanation":["각기둥의 모서리 수 = 변의 수 × 3 — 24개이니 한 밑면의 변은 8개예요.","같은 밑면의 각뿔은 팔각뿔이에요.","밑면의 변 8개와 옆 모서리 8개 — 8 × 2 = 16개예요."]},{"stem":"밑면의 변의 수가 같은 각기둥과 각뿔이 있어요. 각기둥의 꼭짓점이 20개일 때, 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["각기둥의 꼭짓점 수 = 변의 수 × 2 — 20개이니 한 밑면의 변은 10개예요.","같은 밑면의 각뿔은 십각뿔이에요.","밑면 1개와 옆면 10개 — 10 + 1 = 11개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#19','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C3',3,'mc','auto','「크기가 다른 사각형 2개와 직사각형 4개가 이어진 그림」은 사각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X02']::text[],true,'{"seq":19,"concept":"M6-1-u2-C3","difficulty":3,"kind":"mc","stem":"「크기가 다른 사각형 2개와 직사각형 4개가 이어진 그림」은 사각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"두 밑면이 서로 합동이 아니기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X02"},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X02"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X02"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 두 밑면이 서로 합동이 아니기 때문에 전개도가 아니에요."],"variant_rule":{"alt":[{"stem":"「삼각형 2개와 직사각형 4개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","correct":true},{"t":"밑면이 1개뿐이기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 옆면의 수가 한 밑면의 변의 수와 다르기 때문에 전개도가 아니에요."]},{"stem":"「삼각형 1개와 직사각형 3개가 이어진 그림」은 삼각기둥의 전개도가 될 수 없어요. 그 까닭으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"밑면이 1개뿐이기 때문에","correct":true},{"t":"옆면의 수가 한 밑면의 변의 수와 다르기 때문에","mis":"M6-1-u2-X08"},{"t":"접으면 두 밑면이 겹쳐 맞닿지 않기 때문에","mis":"M6-1-u2-X08"},{"t":"두 밑면이 서로 합동이 아니기 때문에","mis":"M6-1-u2-X08"}],"explanation":["각기둥의 전개도에는 합동인 밑면 2개와 변의 수만큼의 옆면이 있어야 해요.","접었을 때 면이 겹치지 않고 맞닿는 선분의 길이가 같아야 해요.","이 그림은 밑면이 1개뿐이기 때문에 전개도가 아니에요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#20','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C3',3,'error','auto','육각기둥의 전개도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['M6-1-u2-X08','M6-1-u2-X14']::text[],true,'{"seq":20,"concept":"M6-1-u2-C3","difficulty":3,"kind":"error","stem":"육각기둥의 전개도를 보고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"여울 — 「옆면이 8개 그려져 있어.」","correct":true,"mis_target":"M6-1-u2-X08"},{"t":"라온 — 「밑면이 2개 그려져 있어.」","mis":"M6-1-u2-X14"},{"t":"예준 — 「접히는 모서리는 점선이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 전개도에서 옆면의 수는 한 밑면의 변의 수와 같아요.","육각기둥의 옆면은 6개, 밑면은 2개예요.","여울은 면 전체의 수를 옆면의 수로 잘못 말했어요."],"variant_rule":{"alt":[{"stem":"각기둥에 대해 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"준희 — 「각기둥을 옆으로 눕히면 바닥에 닿은 옆면이 밑면이 돼.」","correct":true,"mis_target":"M6-1-u2-X01"},{"t":"이현 — 「각기둥의 옆면은 모두 직사각형이야.」","mis":"M6-1-u2-X14"},{"t":"서아 — 「두 밑면은 서로 평행하고 합동이야.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥을 눕혀도 서로 평행하고 합동인 두 면이 밑면이에요.","바닥에 닿은 면이 직사각형 옆면이면 그것은 여전히 옆면이에요.","준희는 밑면을 위치로 잘못 정했어요."]},{"stem":"각기둥의 설명을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"서호 — 「각기둥의 높이는 밑면의 가장 긴 변의 길이야.」","correct":true,"mis_target":"M6-1-u2-X06"},{"t":"수아 — 「각기둥의 밑면은 2개야.」","mis":"M6-1-u2-X14"},{"t":"도윤 — 「각기둥의 밑면은 옆면과 수직으로 만나.」","mis":"M6-1-u2-X14"}],"explanation":["각기둥의 높이는 두 밑면 사이의 거리예요.","밑면의 변은 밑면 안의 선분이라 높이가 될 수 없어요.","서호는 높이를 잘못 말했어요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#21','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C7',3,'sa','auto','밑면이 칠각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":21,"concept":"M6-1-u2-C7","difficulty":3,"kind":"sa","stem":"밑면이 칠각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["한 밑면의 꼭짓점 7개가 위아래로 짝을 이뤄 — 7 × 2 = 14개예요.","밑면의 꼭짓점 7개와 각뿔의 꼭짓점 1개 — 7 + 1 = 8개예요.","차는 14 − 8 = 6개예요."],"mis":"M6-1-u2-X14","variant_rule":{"alt":[{"stem":"밑면이 육각형인 각기둥과 각뿔이 있어요. 두 입체도형의 꼭짓점 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["한 밑면의 꼭짓점 6개가 위아래로 짝을 이뤄 — 6 × 2 = 12개예요.","밑면의 꼭짓점 6개와 각뿔의 꼭짓점 1개 — 6 + 1 = 7개예요.","차는 12 − 7 = 5개예요."]},{"stem":"밑면이 구각형인 각기둥과 각뿔이 있어요. 두 입체도형의 모서리 수의 차는 몇 개인가요? 숫자로 쓰세요.","answer":["9"],"explanation":["위 밑면 9개, 아래 밑면 9개, 옆 모서리 9개 — 9 × 3 = 27개예요.","밑면의 변 9개와 옆 모서리 9개 — 9 × 2 = 18개예요.","차는 27 − 18 = 9개예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#22','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C4',3,'mc','auto','밑면이 한 변이 4 cm인 정삼각형이고 높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?',ARRAY['M6-1-u2-X09']::text[],true,'{"seq":22,"concept":"M6-1-u2-C4","difficulty":3,"kind":"mc","stem":"밑면이 한 변이 4 cm인 정삼각형이고 높이가 11 cm인 삼각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 4 cm, 세로 11 cm","correct":true},{"t":"가로 11 cm, 세로 12 cm","mis":"M6-1-u2-X09"},{"t":"가로 12 cm, 세로 11 cm","mis":"M6-1-u2-X09"},{"t":"가로 4 cm, 세로 4 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 4 cm예요.","옆면의 세로는 각기둥의 높이와 같아 11 cm예요.","그래서 옆면 하나는 「가로 4 cm, 세로 11 cm」예요."],"variant_rule":{"alt":[{"stem":"밑면이 한 변이 5 cm인 정사각형이고 높이가 8 cm인 사각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 5 cm, 세로 8 cm","correct":true},{"t":"가로 8 cm, 세로 20 cm","mis":"M6-1-u2-X09"},{"t":"가로 20 cm, 세로 8 cm","mis":"M6-1-u2-X09"},{"t":"가로 5 cm, 세로 5 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 5 cm예요.","옆면의 세로는 각기둥의 높이와 같아 8 cm예요.","그래서 옆면 하나는 「가로 5 cm, 세로 8 cm」예요."]},{"stem":"밑면이 한 변이 3 cm인 정육각형이고 높이가 10 cm인 육각기둥의 전개도를 그려요. 옆면 하나의 크기로 알맞은 것은 어느 것인가요?","options":[{"t":"가로 3 cm, 세로 10 cm","correct":true},{"t":"가로 10 cm, 세로 18 cm","mis":"M6-1-u2-X09"},{"t":"가로 18 cm, 세로 10 cm","mis":"M6-1-u2-X09"},{"t":"가로 3 cm, 세로 3 cm","mis":"M6-1-u2-X09"}],"explanation":["옆면 하나의 가로는 밑면의 한 변과 같아 3 cm예요.","옆면의 세로는 각기둥의 높이와 같아 10 cm예요.","그래서 옆면 하나는 「가로 3 cm, 세로 10 cm」예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#23','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C7',4,'sa','auto','어떤 각뿔의 모서리가 22개예요. 이 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":23,"concept":"M6-1-u2-C7","difficulty":4,"kind":"sa","stem":"어떤 각뿔의 모서리가 22개예요. 이 각뿔의 면은 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["각뿔의 모서리 수 = 변의 수 × 2 — 한 밑면의 변은 11개예요.","이 입체도형은 십일각뿔이에요.","밑면 1개와 옆면 11개 — 11 + 1 = 12개예요."],"mis":"M6-1-u2-X12","variant_rule":{"alt":[{"stem":"밑면이 한 변이 4 cm인 정사각형이고 높이가 6 cm인 사각기둥이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["56"],"explanation":["두 밑면의 변은 4개씩 — 4 × 2 = 8개이고 모두 4 cm예요.","옆 모서리는 4개이고 모두 높이와 같은 6 cm예요.","8 × 4 + 4 × 6 = 56 — 모두 56 cm예요."]},{"stem":"밑면이 한 변이 3 cm인 정오각형이고 옆 모서리가 모두 9 cm인 오각뿔이 있어요. 모든 모서리의 길이의 합은 몇 cm인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["밑면의 변은 5개이고 모두 3 cm예요.","옆 모서리도 5개이고 모두 9 cm예요.","5 × 3 + 5 × 9 = 60 — 모두 60 cm예요."]}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#24','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C7',4,'essay','teacher','어떤 각뿔의 면이 9개예요. 이 각뿔의 이름을 쓰고, 꼭짓점과 모서리의 수를 구하는 과정을 설명해 보세요.','{}'::text[],false,'{"seq":24,"concept":"M6-1-u2-C7","difficulty":4,"kind":"essay","stem":"어떤 각뿔의 면이 9개예요. 이 각뿔의 이름을 쓰고, 꼭짓점과 모서리의 수를 구하는 과정을 설명해 보세요.","answer_guide":{"answer":"예: 각뿔의 면의 수는 한 밑면의 변의 수에 1을 더한 수이므로 변의 수는 9 − 1 = 8이고 이름은 팔각뿔이다. 꼭짓점은 8 + 1 = 9개, 모서리는 8 × 2 = 16개이다.","scoring_points":["변의 수 8을 구해 팔각뿔이라고 했는가","꼭짓점 9개를 구했는가","모서리 16개를 구했는가"]},"explanation":["9 − 1 = 8 — 팔각뿔이에요.","꼭짓점은 8 + 1 = 9개예요.","모서리는 8 × 2 = 16개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g6_1_math_u2_review_d#25','math',6,1,'u2','','g6_1_math_u2_review_d','unit_review','M6-1-u2-C7',4,'essay','teacher','각기둥의 꼭짓점의 수는 한 밑면의 변의 수의 2배이고, 각뿔의 꼭짓점의 수는 한 밑면의 변의 수에 1을 더한 수예요. 두 규칙이 왜 다른지 세는 방법으로 설명하고, 십각기둥과 십각뿔의 꼭짓점의 수를 구해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M6-1-u2-C7","difficulty":4,"kind":"essay","stem":"각기둥의 꼭짓점의 수는 한 밑면의 변의 수의 2배이고, 각뿔의 꼭짓점의 수는 한 밑면의 변의 수에 1을 더한 수예요. 두 규칙이 왜 다른지 세는 방법으로 설명하고, 십각기둥과 십각뿔의 꼭짓점의 수를 구해 보세요.","answer_guide":{"answer":"예: 각기둥은 밑면이 2개라 한 밑면의 꼭짓점이 위아래로 짝을 이루므로 2배가 된다. 각뿔은 밑면이 1개이고 옆면이 모두 만나는 각뿔의 꼭짓점이 위에 한 점 더 있으므로 1을 더한다. 십각기둥의 꼭짓점은 10 × 2 = 20개, 십각뿔의 꼭짓점은 10 + 1 = 11개이다.","scoring_points":["각기둥은 밑면이 2개라 2배라고 설명했는가","각뿔은 위의 한 점을 더한다고 설명했는가","20개와 11개를 구했는가"]},"explanation":["각기둥은 위아래로 짝 — 2배예요.","각뿔은 위의 한 점 — 1을 더해요.","십각기둥 20개, 십각뿔 11개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
